import re
from functools import cmp_to_key

# Regex for a valid SemVer 2.0.0 string
_SEMVER_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?'
    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
)

def _parse(version: str):
    """Parse a version string into (major, minor, patch, prerelease_identifiers)."""
    m = _SEMVER_RE.match(version)
    if not m:
        raise ValueError(f"Invalid version: {version!r}")
    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))
    pre_str = m.group(4)
    if pre_str is None:
        pre = None
    else:
        pre = pre_str.split('.')
    return major, minor, patch, pre

def _compare_prerelease(a, b):
    """Compare two pre-release identifier lists according to SemVer precedence."""
    if a is None and b is None:
        return 0
    if a is None:
        return 1   # no pre-release has higher precedence
    if b is None:
        return -1

    for x, y in zip(a, b):
        x_num = x.isdigit()
        y_num = y.isdigit()
        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num:
            return -1   # numeric < non-numeric
        elif y_num:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1
    # all compared identifiers equal; longer list has higher precedence
    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0

def _compare_versions(v1, v2):
    p1 = _parse(v1)
    p2 = _parse(v2)
    # compare major, minor, patch
    for i in range(3):
        if p1[i] != p2[i]:
            return -1 if p1[i] < p2[i] else 1
    # compare pre-release
    return _compare_prerelease(p1[3], p2[3])

def sort_versions(versions: list[str]) -> list[str]:
    """Sort version strings in ascending SemVer 2.0.0 precedence order.
    Raises ValueError if any version is invalid.
    """
    # Validate all first (so we raise before sorting)
    for v in versions:
        _parse(v)
    return sorted(versions, key=cmp_to_key(_compare_versions))

import re
from functools import cmp_to_key

# Regex for a valid SemVer 2.0.0 string
_SEMVER_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?'
    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
)

def _parse_version(version: str):
    """Parse a version string into (major, minor, patch, prerelease, build).
    Raises ValueError if invalid.
    """
    m = _SEMVER_RE.match(version)
    if not m:
        raise ValueError(f"Invalid version: {version!r}")
    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))
    prerelease = m.group(4)
    build = m.group(5)
    pre_ids = prerelease.split('.') if prerelease else None
    return major, minor, patch, pre_ids, build

def _compare_prerelease(a_ids, b_ids):
    """Compare two prerelease identifier lists according to SemVer precedence.
    Returns -1, 0, or 1.
    """
    if a_ids is None and b_ids is None:
        return 0
    if a_ids is None:
        return 1   # no prerelease > prerelease
    if b_ids is None:
        return -1

    for a, b in zip(a_ids, b_ids):
        a_num = a.isdigit()
        b_num = b.isdigit()
        if a_num and b_num:
            ai, bi = int(a), int(b)
            if ai != bi:
                return -1 if ai < bi else 1
        elif a_num and not b_num:
            return -1
        elif not a_num and b_num:
            return 1
        else:
            if a != b:
                return -1 if a < b else 1
    # All compared identifiers equal; longer list has higher precedence
    if len(a_ids) != len(b_ids):
        return -1 if len(a_ids) < len(b_ids) else 1
    return 0

def _compare_versions(a, b):
    """Compare two parsed version tuples (major, minor, patch, pre_ids, build)."""
    for i in range(3):
        if a[i] != b[i]:
            return -1 if a[i] < b[i] else 1
    return _compare_prerelease(a[3], b[3])

def sort_versions(versions: list[str]) -> list[str]:
    """Sort version strings in ascending SemVer 2.0.0 precedence order.
    Stable sort preserves input order for equal precedence.
    Raises ValueError if any version is invalid.
    """
    parsed = []
    for v in versions:
        parsed.append((v, _parse_version(v)))

    def cmp(x, y):
        return _compare_versions(x[1], y[1])

    parsed.sort(key=cmp_to_key(cmp))
    return [v for v, _ in parsed]

import re
from functools import cmp_to_key

# Regex for a valid SemVer 2.0.0 string.
# Groups: 1=major, 2=minor, 3=patch, 4=prerelease (optional), 5=build (optional)
_SEMVER_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?'
    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
)

def _parse(version: str):
    """Parse a version string, raising ValueError if invalid."""
    m = _SEMVER_RE.match(version)
    if not m:
        raise ValueError(f"Invalid semantic version: {version!r}")
    major, minor, patch, prerelease, build = m.groups()
    pre_ids = prerelease.split('.') if prerelease is not None else None
    return (int(major), int(minor), int(patch), pre_ids)

def _compare_pre_ids(a: str, b: str) -> int:
    """Compare two pre-release identifiers."""
    a_num = a.isdigit()
    b_num = b.isdigit()
    if a_num and b_num:
        ai, bi = int(a), int(b)
        return (ai > bi) - (ai < bi)
    if a_num != b_num:
        # numeric identifiers have lower precedence than non-numeric
        return -1 if a_num else 1
    # both non-numeric: ASCII lexical order
    return (a > b) - (a < b)

def _compare_versions(v1: str, v2: str) -> int:
    """Compare two valid version strings by SemVer precedence."""
    a = _parse(v1)
    b = _parse(v2)
    # compare major, minor, patch
    for x, y in zip(a[:3], b[:3]):
        if x != y:
            return (x > y) - (x < y)
    pre_a, pre_b = a[3], b[3]
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1   # no pre-release has higher precedence
    if pre_b is None:
        return -1
    # compare pre-release identifiers
    for x, y in zip(pre_a, pre_b):
        c = _compare_pre_ids(x, y)
        if c != 0:
            return c
    # all compared identifiers equal; more identifiers = higher precedence
    return (len(pre_a) > len(pre_b)) - (len(pre_a) < len(pre_b))

def sort_versions(versions: list[str]) -> list[str]:
    """Sort version strings in ascending SemVer precedence order (stable)."""
    # Validate all first, so we raise ValueError before sorting.
    for v in versions:
        _parse(v)
    return sorted(versions, key=cmp_to_key(_compare_versions))

import re
from functools import cmp_to_key

# Regex for a valid SemVer 2.0.0 string (no leading zeros for numeric parts)
_SEMVER_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?'
    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
)

def _parse(version: str):
    m = _SEMVER_RE.match(version)
    if not m:
        raise ValueError(f"Invalid semantic version: {version!r}")
    major, minor, patch, prerelease, _build = m.groups()
    pre = prerelease.split('.') if prerelease is not None else None
    return (int(major), int(minor), int(patch), pre)

def _compare_pre(a, b):
    # a and b are either None (no prerelease) or lists of identifiers
    if a is None and b is None:
        return 0
    if a is None:
        return 1   # no prerelease has higher precedence
    if b is None:
        return -1
    for x, y in zip(a, b):
        x_num = x.isdigit()
        y_num = y.isdigit()
        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num:
            return -1   # numeric < non-numeric
        elif y_num:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1
    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0

def sort_versions(versions: list[str]) -> list[str]:
    parsed = [(v, _parse(v)) for v in versions]

    def cmp_items(item1, item2):
        v1, p1 = item1
        v2, p2 = item2
        if p1[:3] != p2[:3]:
            return -1 if p1[:3] < p2[:3] else 1
        return _compare_pre(p1[3], p2[3])

    parsed.sort(key=cmp_to_key(cmp_items))
    return [v for v, _ in parsed]

import re
from functools import cmp_to_key

_VERSION_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?'
    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
)

_NUMERIC_ID_RE = re.compile(r'^(0|[1-9]\d*)$')


def _parse_version(version: str):
    m = _VERSION_RE.match(version)
    if not m:
        raise ValueError(f"Invalid version: {version!r}")

    major, minor, patch, prerelease, build = m.groups()

    pre_ids = None
    if prerelease is not None:
        pre_ids = []
        for ident in prerelease.split('.'):
            if ident == '':
                raise ValueError(f"Invalid version: {version!r}")
            if ident.isdigit():
                if not _NUMERIC_ID_RE.match(ident):
                    raise ValueError(f"Invalid version: {version!r}")
                pre_ids.append((0, int(ident), ident))
            else:
                pre_ids.append((1, ident, ident))

    if build is not None:
        for ident in build.split('.'):
            if ident == '':
                raise ValueError(f"Invalid version: {version!r}")

    return (int(major), int(minor), int(patch), pre_ids)


def _compare(a, b):
    if a[:3] != b[:3]:
        return -1 if a[:3] < b[:3] else 1

    pa, pb = a[3], b[3]

    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1
    if pb is None:
        return -1

    for x, y in zip(pa, pb):
        if x[0] != y[0]:
            return -1 if x[0] < y[0] else 1
        if x[1] != y[1]:
            return -1 if x[1] < y[1] else 1

    if len(pa) != len(pb):
        return -1 if len(pa) < len(pb) else 1
    return 0


def sort_versions(versions: list[str]) -> list[str]:
    parsed = [_parse_version(v) for v in versions]
    indexed = list(enumerate(parsed))

    def cmp_items(item_a, item_b):
        c = _compare(item_a[1], item_b[1])
        if c != 0:
            return c
        return -1 if item_a[0] < item_b[0] else (1 if item_a[0] > item_b[0] else 0)

    indexed.sort(key=cmp_to_key(cmp_items))
    return [versions[i] for i, _ in indexed]

