    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
)

def _parse(version: str):
    """Parse a version string, returning (major, minor, patch, prerelease_list, build) or None if invalid."""
    m = _SEMVER_RE.match(version)
    if not m:
        return None
    major, minor, patch, prerelease, build = m.groups()
    pre = prerelease.split('.') if prerelease is not None else None
    return (int(major), int(minor), int(patch), pre, build)

def _cmp_prerelease(a, b):
    """Compare two prerelease lists (or None for no prerelease)."""
    if a is None and b is None:
        return 0
    if a is None:
        return 1   # no prerelease > prerelease
    if b is None:
        return -1
    for x, y in zip(a, b):
        x_num = x.isdigit()
        y_num = y.isdigit()
        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num:
            return -1  # numeric < non-numeric
        elif y_num:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1
    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0

def _cmp_versions(v1, v2):
    p1 = _parse(v1)
    p2 = _parse(v2)
    if p1 is None:
        raise ValueError(f"Invalid version: {v1!r}")
    if p2 is None:
        raise ValueError(f"Invalid version: {v2!r}")
    for i in range(3):
        if p1[i] != p2[i]:
            return -1 if p1[i] < p2[i] else 1
    return _cmp_prerelease(p1[3], p2[3])

def sort_versions(versions: list[str]) -> list[str]:
    # Validate all first (so we raise before sorting if any invalid)
    for v in versions:
        if _parse(v) is None:
            raise ValueError(f"Invalid version: {v!r}")
    return sorted(versions, key=cmp_to_key(_cmp_versions))

import re
from functools import cmp_to_key

_VERSION_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:[0-9A-Za-z-]+)(?:\.(?:[0-9A-Za-z-]+))*))?'
    r'(?:\+((?:[0-9A-Za-z-]+)(?:\.(?:[0-9A-Za-z-]+))*))?$'
)

_NUMERIC_RE = re.compile(r'^\d+$')


def _parse(version: str):
    m = _VERSION_RE.match(version)
    if m is None:
        raise ValueError(f"Invalid version: {version!r}")
    major, minor, patch, pre, build = m.groups()
    pre_ids = None
    if pre is not None:
        pre_ids = pre.split('.')
        for ident in pre_ids:
            if _NUMERIC_RE.match(ident) and len(ident) > 1 and ident[0] == '0':
                raise ValueError(f"Invalid version: {version!r}")
    return (int(major), int(minor), int(patch), pre_ids)


def _compare_pre(a, b):
    # a, b are lists of identifiers or None
    if a is None and b is None:
        return 0
    if a is None:
        return 1
    if b is None:
        return -1
    for x, y in zip(a, b):
        x_num = _NUMERIC_RE.match(x) is not None
        y_num = _NUMERIC_RE.match(y) is not None
        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num and not y_num:
            return -1
        elif not x_num and y_num:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1
    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


def sort_versions(versions: list[str]) -> list[str]:
    parsed = [(v, _parse(v)) for v in versions]

    def cmp(item1, item2):
        v1, p1 = item1
        v2, p2 = item2
        for i in range(3):
            if p1[i] != p2[i]:
                return -1 if p1[i] < p2[i] else 1
        return _compare_pre(p1[3], p2[3])

    parsed.sort(key=cmp_to_key(cmp))
    return [v for v, _ in parsed]

