import re
from functools import cmp_to_key

# Regex for a valid SemVer 2.0.0 string
_SEMVER_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?'
    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
)

def _parse(version: str):
    """Parse a version string into (major, minor, patch, prerelease, build).
    Raises ValueError if invalid.
    """
    m = _SEMVER_RE.match(version)
    if not m:
        raise ValueError(f"Invalid version: {version!r}")
    major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
    pre = m.group(4)
    build = m.group(5)
    prerelease = pre.split('.') if pre is not None else None
    return major, minor, patch, prerelease, build

def _compare_prerelease(a, b):
    """Compare two prerelease lists (or None). Returns -1, 0, 1."""
    if a is None and b is None:
        return 0
    if a is None:
        return 1   # no prerelease > prerelease
    if b is None:
        return -1

    for x, y in zip(a, b):
        x_num = x.isdigit()
        y_num = y.isdigit()
        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num:
            return -1  # numeric < non-numeric
        elif y_num:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1
    # all equal so far
    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0

def _cmp(v1, v2):
    m1, n1, p1, pre1, _ = _parse(v1)
    m2, n2, p2, pre2, _ = _parse(v2)
    if m1 != m2:
        return -1 if m1 < m2 else 1
    if n1 != n2:
        return -1 if n1 < n2 else 1
    if p1 != p2:
        return -1 if p1 < p2 else 1
    return _compare_prerelease(pre1, pre2)

def sort_versions(versions: list[str]) -> list[str]:
    # Validate all first (raises ValueError if any invalid)
    for v in versions:
        _parse(v)
    return sorted(versions, key=cmp_to_key(_cmp))

