        ai = int(a)
        bi = int(b)
        return (ai > bi) - (ai < bi)
    if a_numeric:
        return -1
    if b_numeric:
        return 1
    # both non-numeric: ASCII lexical order
    return (a > b) - (a < b)

def _compare_versions(v1: str, v2: str) -> int:
    """Compare two version strings by SemVer precedence. Build metadata ignored."""
    a_major, a_minor, a_patch, a_pre, _ = _parse(v1)
    b_major, b_minor, b_patch, b_pre, _ = _parse(v2)

    if a_major != b_major:
        return (a_major > b_major) - (a_major < b_major)
    if a_minor != b_minor:
        return (a_minor > b_minor) - (a_minor < b_minor)
    if a_patch != b_patch:
        return (a_patch > b_patch) - (a_patch < b_patch)

    # Pre-release precedence
    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1   # no pre-release > with pre-release
    if b_pre is None:
        return -1

    # Compare identifier by identifier
    for x, y in zip(a_pre, b_pre):
        c = _compare_pre_ids(x, y)
        if c != 0:
            return c
    # All compared identifiers equal; longer list has higher precedence
    if len(a_pre) != len(b_pre):
        return (len(a_pre) > len(b_pre)) - (len(a_pre) < len(b_pre))
    return 0

def sort_versions(versions: list[str]) -> list[str]:
    """Sort version strings in ascending SemVer 2.0.0 precedence order.
    Stable: equal precedence keeps original input order.
    Raises ValueError if any version is invalid.
    """
    # Validate all first (so we raise before sorting)
    for v in versions:
        _parse(v)
    return sorted(versions, key=cmp_to_key(_compare_versions))

import re
from functools import cmp_to_key

_VERSION_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:[0-9A-Za-z-]+)(?:\.[0-9A-Za-z-]+)*))?'
    r'(?:\+((?:[0-9A-Za-z-]+)(?:\.[0-9A-Za-z-]+)*))?$'
)

def _parse(version: str):
    m = _VERSION_RE.match(version)
    if not m:
        raise ValueError(f"Invalid semantic version: {version!r}")
    major, minor, patch, pre, build = m.groups()
    major, minor, patch = int(major), int(minor), int(patch)

    pre_ids = None
    if pre is not None:
        pre_ids = []
        for ident in pre.split('.'):
            if ident.isdigit():
                if len(ident) > 1 and ident[0] == '0':
                    raise ValueError(f"Invalid semantic version: {version!r}")
                pre_ids.append((0, int(ident)))
            else:
                pre_ids.append((1, ident))
    return (major, minor, patch, pre_ids)

def _compare(a, b):
    pa = _parse(a)
    pb = _parse(b)
    if pa[:3] != pb[:3]:
        return -1 if pa[:3] < pb[:3] else 1
    pre_a, pre_b = pa[3], pb[3]
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1
    for x, y in zip(pre_a, pre_b):
        if x == y:
            continue
        if x[0] != y[0]:
            return -1 if x[0] < y[0] else 1
        return -1 if x[1] < y[1] else 1
    if len(pre_a) == len(pre_b):
        return 0
    return -1 if len(pre_a) < len(pre_b) else 1

def sort_versions(versions: list[str]) -> list[str]:
    for v in versions:
        _parse(v)
    return sorted(versions, key=cmp_to_key(_compare))

