import re
from functools import cmp_to_key

_VERSION_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:[0-9A-Za-z-]+)(?:\.(?:[0-9A-Za-z-]+))*))?'
    r'(?:\+((?:[0-9A-Za-z-]+)(?:\.(?:[0-9A-Za-z-]+))*))?$'
)

_NUMERIC_ID_RE = re.compile(r'^(0|[1-9]\d*)$')


def _parse(version: str):
    m = _VERSION_RE.match(version)
    if m is None:
        raise ValueError(f"invalid version: {version!r}")

    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))

    prerelease = None
    if m.group(4) is not None:
        ids = m.group(4).split('.')
        parsed_ids = []
        for ident in ids:
            if _NUMERIC_ID_RE.match(ident):
                parsed_ids.append((0, int(ident), ident))
            else:
                parsed_ids.append((1, ident, ident))
        prerelease = parsed_ids

    return (major, minor, patch, prerelease)


def _compare(a, b):
    for i in range(3):
        if a[i] != b[i]:
            return -1 if a[i] < b[i] else 1

    pa, pb = a[3], b[3]

    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1
    if pb is None:
        return -1

    for x, y in zip(pa, pb):
        if x[0] != y[0]:
            return -1 if x[0] < y[0] else 1
        if x[1] != y[1]:
            return -1 if x[1] < y[1] else 1

    if len(pa) != len(pb):
        return -1 if len(pa) < len(pb) else 1

    return 0


def sort_versions(versions: list[str]) -> list[str]:
    parsed = [(v, _parse(v)) for v in versions]
    parsed.sort(key=cmp_to_key(lambda x, y: _compare(x[1], y[1])))
    return [v for v, _ in parsed]

