import re
from functools import cmp_to_key

_VERSION_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:[0-9A-Za-z-]+)(?:\.[0-9A-Za-z-]+)*))?'
    r'(?:\+((?:[0-9A-Za-z-]+)(?:\.[0-9A-Za-z-]+)*))?$'
)

_NUMERIC_ID_RE = re.compile(r'^(0|[1-9]\d*)$')


def _parse_version(version: str):
    m = _VERSION_RE.match(version)
    if not m:
        raise ValueError(f"Invalid version: {version!r}")

    major, minor, patch, prerelease, build = m.groups()

    pre_ids = None
    if prerelease is not None:
        pre_ids = prerelease.split('.')
        for ident in pre_ids:
            if not ident:
                raise ValueError(f"Invalid version: {version!r}")
            if _NUMERIC_ID_RE.match(ident):
                pass
            elif re.fullmatch(r'[0-9A-Za-z-]+', ident):
                pass
            else:
                raise ValueError(f"Invalid version: {version!r}")

    if build is not None:
        for ident in build.split('.'):
            if not ident or not re.fullmatch(r'[0-9A-Za-z-]+', ident):
                raise ValueError(f"Invalid version: {version!r}")

    return (int(major), int(minor), int(patch), pre_ids)


