    if a is None and b is None:
        return 0
    if a is None:
        return 1
    if b is None:
        return -1

    for x, y in zip(a, b):
        x_num = _NUMERIC_ID_RE.match(x) is not None
        y_num = _NUMERIC_ID_RE.match(y) is not None

        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num and not y_num:
            return -1
        elif not x_num and y_num:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1

    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


def _compare_versions(v1, v2):
    p1 = _parse_version(v1)
    p2 = _parse_version(v2)

    for i in range(3):
        if p1[i] != p2[i]:
            return -1 if p1[i] < p2[i] else 1

    return _compare_pre(p1[3], p2[3])


def sort_versions(versions: list[str]) -> list[str]:
    for v in versions:
        _parse_version(v)
    return sorted(versions, key=cmp_to_key(_compare_versions))

