    a_major, a_minor, a_patch, a_pre, _ = _parse_version(a)
    b_major, b_minor, b_patch, b_pre, _ = _parse_version(b)

    if a_major != b_major:
        return -1 if a_major < b_major else 1
    if a_minor != b_minor:
        return -1 if a_minor < b_minor else 1
    if a_patch != b_patch:
        return -1 if a_patch < b_patch else 1

    if a_pre is None and b_pre is None:
