import re
from functools import cmp_to_key

# Regex for a valid SemVer 2.0.0 version string
# Groups: 1=major, 2=minor, 3=patch, 4=prerelease (optional), 5=build (optional)
_SEMVER_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?'
    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
)

def _parse_version(version: str):
    """Parse a version string into a tuple (major, minor, patch, prerelease, build).
    Raises ValueError if invalid.
    """
    m = _SEMVER_RE.match(version)
    if not m:
        raise ValueError(f"Invalid version: {version!r}")
    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))
    prerelease_str = m.group(4)
    build_str = m.group(5)

    prerelease = None
    if prerelease_str is not None:
        prerelease = prerelease_str.split('.')

    build = None
    if build_str is not None:
        build = build_str.split('.')

    return (major, minor, patch, prerelease, build)

def _compare_prerelease(a, b):
    """Compare two pre-release lists according to SemVer precedence.
    Returns -1, 0, or 1.
    """
    if a is None and b is None:
        return 0
    if a is None:
        return 1   # no prerelease > prerelease
    if b is None:
        return -1

    # Compare identifier by identifier
    for id_a, id_b in zip(a, b):
        num_a = id_a.isdigit()
        num_b = id_b.isdigit()
        if num_a and num_b:
            va = int(id_a)
            vb = int(id_b)
            if va < vb:
                return -1
            if va > vb:
                return 1
        elif num_a:
            return -1   # numeric < non-numeric
        elif num_b:
            return 1
        else:
            if id_a < id_b:
                return -1
            if id_a > id_b:
                return 1
    # All compared identifiers equal; longer list has higher precedence
    if len(a) < len(b):
        return -1
    if len(a) > len(b):
        return 1
    return 0

def _compare_versions(v1, v2):
    """Compare two parsed version tuples according to SemVer precedence.
    Build metadata is ignored.
    """
    # Compare major, minor, patch
    for i in range(3):
        if v1[i] < v2[i]:
            return -1
        if v1[i] > v2[i]:
            return 1
    # Compare prerelease
    return _compare_prerelease(v1[3], v2[3])

def sort_versions(versions: list[str]) -> list[str]:
    """Sort version strings in ascending order of SemVer 2.0.0 precedence.
    Raises ValueError if any version is invalid.
    Stable sort preserves input order for equal precedence.
    """
    parsed = []
    for v in versions:
        parsed.append((_parse_version(v), v))
    # Use cmp_to_key for custom comparison
    def cmp_items(item1, item2):
        return _compare_versions(item1[0], item2[0])
    parsed.sort(key=cmp_to_key(cmp_items))
    return [v for _, v in parsed]

