from functools import cmp_to_key

# Regex for a valid SemVer 2.0.0 string
_SEMVER_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:[0-9A-Za-z-]+)(?:\.[0-9A-Za-z-]+)*))?'
    r'(?:\+((?:[0-9A-Za-z-]+)(?:\.[0-9A-Za-z-]+)*))?$'
)

def _parse(version: str):
    """Parse a version string into (major, minor, patch, prerelease_list, build_list)."""
    m = _SEMVER_RE.match(version)
    if not m:
        raise ValueError(f"Invalid version: {version!r}")
    major, minor, patch, pre, build = m.groups()
    major, minor, patch = int(major), int(minor), int(patch)

    prerelease = None
    if pre is not None:
        prerelease = pre.split('.')
        for ident in prerelease:
            if ident.isdigit() and len(ident) > 1 and ident[0] == '0':
                raise ValueError(f"Invalid version: {version!r}")

    build_list = None
    if build is not None:
        build_list = build.split('.')

    return major, minor, patch, prerelease, build_list

def _compare_prerelease(a, b):
    """Compare two pre-release lists. Returns -1, 0, or 1."""
    if a is None and b is None:
        return 0
    if a is None:
        return 1   # no pre-release has higher precedence
    if b is None:
        return -1

    for x, y in zip(a, b):
        x_num = x.isdigit()
        y_num = y.isdigit()
        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num and not y_num:
            return -1
        elif not x_num and y_num:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1
    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0

def _compare(v1, v2):
    """Compare two parsed versions for precedence."""
    m1, n1, p1, pre1, _ = v1
    m2, n2, p2, pre2, _ = v2
    if m1 != m2:
        return -1 if m1 < m2 else 1
    if n1 != n2:
        return -1 if n1 < n2 else 1
    if p1 != p2:
        return -1 if p1 < p2 else 1
    return _compare_prerelease(pre1, pre2)

def sort_versions(versions: list[str]) -> list[str]:
    parsed = [_parse(v) for v in versions]
    indexed = list(enumerate(parsed))
    indexed.sort(key=cmp_to_key(lambda a, b: _compare(a[1], b[1]) or (a[0] - b[0])))
    return [versions[i] for i, _ in indexed]

