    """Compare two prerelease strings according to SemVer precedence."""
    if a == b:
        return 0
    if a is None:
        return 1   # no prerelease has higher precedence
    if b is None:
        return -1

    a_ids = a.split('.')
    b_ids = b.split('.')

    for x, y in zip(a_ids, b_ids):
        x_num = x.isdigit()
        y_num = y.isdigit()

        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num:
            return -1  # numeric < non-numeric
        elif y_num:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1

    # All compared identifiers equal; more identifiers wins
    if len(a_ids) != len(b_ids):
        return -1 if len(a_ids) < len(b_ids) else 1
    return 0

