    a = _parse_version(v1)
    b = _parse_version(v2)

    for i in range(3):
        if a[i] != b[i]:
            return -1 if a[i] < b[i] else 1

    return _compare_prerelease(a[3], b[3])

def sort_versions(versions: list[str]) -> list[str]:
