    return (int(major), int(minor), int(patch), pre)


def _compare(a, b):
    if a[0] != b[0]:
        return -1 if a[0] < b[0] else 1
    if a[1] != b[1]:
        return -1 if a[1] < b[1] else 1
    if a[2] != b[2]:
        return -1 if a[2] < b[2] else 1

    pa, pb = a[3], b[3]
    if pa is None and pb is None:
        return 0
    if pa is None:
        return 1
    if pb is None:
        return -1

    for x, y in zip(pa, pb):
        if x[0] != y[0]:
            return -1 if x[0] < y[0] else 1
        if x[1] != y[1]:
            return -1 if x[1] < y[1] else 1

    if len(pa) != len(pb):
        return -1 if len(pa) < len(pb) else 1
    return 0


def sort_versions(versions: list[str]) -> list[str]:
    parsed = [(v, _parse(v)) for v in versions]

    def cmp(x, y):
        return _compare(x[1], y[1])

    parsed.sort(key=cmp_to_key(cmp))
    return [v for v, _ in parsed]

def check_invalid(pattern):
            n = 0
            for c in reversed(pattern):
                if c == '\\':
                    n += 1
                else:
                    break
            if n % 2 == 1:
                raise ValueError("Pattern ends with unpaired backslash")

def glob_match(pattern: str, path: str) -> bool:
    # Check for unpaired backslash at end
    if pattern.endswith('\\'):
        # count backslashes at end
        cnt = 0
        for c in reversed(pattern):
            if c == '\\':
                cnt += 1
            else:
                break
        if cnt % 2 == 1:
            raise ValueError("Pattern ends with unpaired backslash")

    # Split pattern into segments
    p_segs = []
    current = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '\\':
            if i + 1 >= len(pattern):
                raise ValueError("Pattern ends with unpaired backslash")
            current.append(c)
            current.append(pattern[i+1])
            i += 2
        elif c == '/':
            p_segs.append(''.join(current))
            current = []
            i += 1
        else:
            current.append(c)
            i += 1
    p_segs.append(''.join(current))

    # Split path into segments
    path_segs = path.split('/') if path else []

    # Now match segments
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match_seg(pat, s):
        # match a single segment
        # pat and s are strings
        # we'll use recursion with memoization
        @lru_cache(maxsize=None)
        def match(i, j):
            if i == len(pat):
                return j == len(s)
            if pat[i] == '\\':
                if i+1 >= len(pat):
                    raise ValueError("Pattern ends with unpaired backslash")
                if j >= len(s):
                    return False
                if pat[i+1] != s[j]:
                    return False
                return match(i+2, j+1)
            if pat[i] == '?':
                if j >= len(s):
                    return False
                return match(i+1, j+1)
            if pat[i] == '*':
                return match(i+1, j) or (j < len(s) and match(i, j+1))
            if pat[i] == '[':
                res = parse_class(pat, i)
                if res is None:
                    if j >= len(s):
                        return False
                    if pat[i] != s[j]:
                        return False
                    return match(i+1, j+1)
                else:
                    chars, negated, next_i = res
                    if j >= len(s):
                        return False
                    if (s[j] in chars) == negated:
                        return False
                    return match(next_i, j+1)
            else:
                if j >= len(s):
                    return False
                if pat[i] != s[j]:
                    return False
                return match(i+1, j+1)
        return match(0, 0)

    @lru_cache(maxsize=None)
    def match_segments(i, j):
        if i == len(p_segs):
            return j == len(path_segs)
        if p_segs[i] == "**":
            # match zero or more segments
            return match_segments(i+1, j) or (j < len(path_segs) and match_segments(i, j+1))
        else:
            if j >= len(path_segs):
                return False
            if not match_seg(p_segs[i], path_segs[j]):
                return False
            return match_segments(i+1, j+1)

    return match_segments(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    # Check for trailing unpaired backslash
    def check_trailing_backslash(p):
        i = 0
        while i < len(p):
            if p[i] == '\\':
                if i + 1 >= len(p):
                    raise ValueError("Pattern ends with unpaired backslash")
                i += 2
            else:
                i += 1
    check_trailing_backslash(pattern)

    # Split into segments
    pat_segs = pattern.split('/')
    path_segs = path.split('/')

    # Match segments with ** handling
    def match_segments(pi, si):
        if pi == len(pat_segs):
            return si == len(path_segs)
        if pat_segs[pi] == '**':
            # Try matching zero segments
            if match_segments(pi + 1, si):
                return True
            # Try matching one or more
            if si < len(path_segs):
                return match_segments(pi, si + 1)
            return False
        else:
            if si >= len(path_segs):
                return False
            if not match_segment(pat_segs[pi], path_segs[si]):
                return False
            return match_segments(pi + 1, si + 1)

    return match_segments(0, 0)


def match_segment(pat: str, s: str) -> bool:
    # Parse pattern into tokens
    tokens = []
    i = 0
    while i < len(pat):
        c = pat[i]
        if c == '\\':
            if i + 1 >= len(pat):
                raise ValueError("Pattern ends with unpaired backslash")
            tokens.append(('literal', pat[i+1]))
            i += 2
        elif c == '?':
            tokens.append(('any',))
            i += 1
        elif c == '*':
            tokens.append(('star',))
            i += 1
        elif c == '[':
            # Try to parse character class
            j = i + 1
            negate = False
            if j < len(pat) and pat[j] == '!':
                negate = True
                j += 1
            # Check for closing ]
            k = j
            # Handle first ] as literal
            if k < len(pat) and pat[k] == ']':
                k += 1
            while k < len(pat) and pat[k] != ']':
                k += 1
            if k >= len(pat):
                # No closing ], treat [ as literal
                tokens.append(('literal', '['))
                i += 1
            else:
                # Parse class content from j to k-1
                content = pat[j:k]
                # Build set of chars and ranges
                chars = set()
                ranges = []
                idx = 0
                while idx < len(content):
                    if idx + 2 < len(content) and content[idx+1] == '-':
                        # Range
                        start = content[idx]
                        end = content[idx+2]
                        if start > end:
                            # Invalid range? Treat as literals
                            chars.add(start)
                            chars.add('-')
                            chars.add(end)
                        else:
                            ranges.append((start, end))
                        idx += 3
                    else:
                        chars.add(content[idx])
                        idx += 1
                tokens.append(('class', negate, chars, ranges))
                i = k + 1
        else:
            tokens.append(('literal', c))
            i += 1

    # Now match tokens against s
    # Use recursion with memoization
    from functools import lru_cache

    @lru_cache(None)
    def dp(ti, si):
        if ti == len(tokens):
            return si == len(s)
        tok = tokens[ti]
        if tok[0] == 'literal':
            if si < len(s) and s[si] == tok[1]:
                return dp(ti + 1, si + 1)
            return False
        elif tok[0] == 'any':
            if si < len(s):
                return dp(ti + 1, si + 1)
            return False
        elif tok[0] == 'star':
            # Match zero or more
            if dp(ti + 1, si):
                return True
            if si < len(s):
                return dp(ti, si + 1)
            return False
        elif tok[0] == 'class':
            _, negate, chars, ranges = tok
            if si >= len(s):
                return False
            ch = s[si]
            matched = ch in chars
            if not matched:
                for start, end in ranges:
                    if start <= ch <= end:
                        matched = True
                        break
            if negate:
                matched = not matched
            if matched:
                return dp(ti + 1, si + 1)
            return False
        return False

    return dp(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    # Parse pattern into tokens.
    # Token types:
    #   ('lit', ch)        literal character
    #   ('any',)           ?  (one non-slash char)
    #   ('star',)          *  (zero or more non-slash chars)
    #   ('globstar',)      ** as a whole segment
    #   ('class', neg, items)  [...] character class
    tokens = []
    i = 0
    n = len(pattern)

    def parse_class(start):
        # pattern[start] == '['
        j = start + 1
        neg = False
        if j < n and pattern[j] == '!':
            neg = True
            j += 1
        items = []
        first = True
        while j < n:
            c = pattern[j]
            if c == ']' and not first:
                return ('class', neg, items), j + 1
            if c == '\\':
                if j + 1 >= n:
                    raise ValueError("pattern ends with unpaired backslash")
                c = pattern[j + 1]
                j += 2
            else:
                j += 1
            # check for range
            if j < n and pattern[j] == '-' and j + 1 < n and pattern[j + 1] != ']':
                # range
                if j + 1 < n and pattern[j + 1] == '\\':
                    if j + 2 >= n:
                        raise ValueError("pattern ends with unpaired backslash")
                    c2 = pattern[j + 2]
                    j += 3
                else:
                    c2 = pattern[j + 1]
                    j += 2
                items.append(('range', c, c2))
            else:
                items.append(('char', c))
            first = False
        # no closing ]
        return None, start

    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with unpaired backslash")
            tokens.append(('lit', pattern[i + 1]))
            i += 2
        elif c == '?':
            tokens.append(('any',))
            i += 1
        elif c == '*':
            # check for ** as whole segment
            if i + 1 < n and pattern[i + 1] == '*':
                # check if whole segment
                before_ok = (i == 0) or (pattern[i - 1] == '/')
                after_ok = (i + 2 == n) or (pattern[i + 2] == '/')
                if before_ok and after_ok:
                    tokens.append(('globstar',))
                    i += 2
                    # skip following slash if present
                    if i < n and pattern[i] == '/':
                        i += 1
                    continue
            tokens.append(('star',))
            i += 1
        elif c == '[':
            cls, new_i = parse_class(i)
            if cls is None:
                tokens.append(('lit', '['))
                i += 1
            else:
                tokens.append(cls)
                i = new_i
        else:
            tokens.append(('lit', c))
            i += 1

    # Now match tokens against path.
    # Use dynamic programming / recursion with memoization.
    # Since globstar can match zero or more segments, we can handle it.

    # Split path into segments for globstar handling? But other tokens can match across segments?
    # Actually * and ? and [] do not match '/', so they operate within a segment.
    # Literal '/' matches '/'. So the only token that can cross segments is globstar.
    # We can do a recursive matcher over the path string.

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match(ti, pi):
        if ti == len(tokens):
            return pi == len(path)
        tok = tokens[ti]
        t = tok[0]
        if t == 'lit':
            if pi < len(path) and path[pi] == tok[1]:
                return match(ti + 1, pi + 1)
            return False
        elif t == 'any':
            if pi < len(path) and path[pi] != '/':
                return match(ti + 1, pi + 1)
            return False
        elif t == 'star':
            # match zero or more non-slash chars
            # try all possible lengths
            k = pi
            while True:
                if match(ti + 1, k):
                    return True
                if k < len(path) and path[k] != '/':
                    k += 1
                else:
                    break
            return False
        elif t == 'globstar':
            # match zero or more whole segments
            # try all possible segment boundaries
            # zero segments: match(ti+1, pi)
            if match(ti + 1, pi):
                return True
            # one or more segments: must start at segment boundary
            # pi must be at start of a segment (pi==0 or path[pi-1]=='/')
            # Actually globstar can match from current position to some later position
            # that is a segment boundary.
            # We can try to consume segments.
            k = pi
            while k < len(path):
                # find next '/'
                if path[k] == '/':
                    # can't consume a segment that starts with '/'
                    # Actually we need to consume whole segments.
                    # If pi is at start of segment, we can consume up to next '/'
                    pass
                # find end of current segment
                j = k
                while j < len(path) and path[j] != '/':
                    j += 1
                # now j is at '/' or end
                # consume segment from k to j
                # next position is j+1 if j < len(path) else j
                next_pos = j + 1 if j < len(path) else j
                if match(ti + 1, next_pos):
                    return True
                if j >= len(path):
                    break
                k = j + 1
            return False
        elif t == 'class':
            if pi >= len(path):
                return False
            ch = path[pi]
            if ch == '/':
                return False
            neg = tok[1]
            items = tok[2]
            matched = False
            for item in items:
                if item[0] == 'char':
                    if ch == item[1]:
                        matched = True
                        break
                else:  # range
                    if item[1] <= ch <= item[2]:
                        matched = True
                        break
            if matched != neg:
                return match(ti + 1, pi + 1)
            return False
        return False

    return match(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    # Validate pattern: check for trailing unpaired backslash
    # We need to count backslashes at the end
    # Actually, we can check during parsing: if we see a backslash at the end, raise ValueError
    if pattern.endswith('\\'):
        # But could be escaped backslash? e.g., "\\\\" is two backslashes, which is an escaped backslash, so it's valid.
        # We need to count consecutive backslashes at the end.
        # If odd number, then last is unpaired.
        # Let's count:
        count = 0
        i = len(pattern) - 1
        while i >= 0 and pattern[i] == '\\':
            count += 1
            i -= 1
        if count % 2 == 1:
            raise ValueError("Pattern ends with unpaired backslash")

    # Split pattern into segments by unescaped '/'
    segments = []
    current = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 < n:
                # Escaped character: keep both backslash and next char? Or just next char?
                # We need to preserve the escape for later parsing.
                # Actually, we can keep the backslash and next char as part of the segment.
                # But when splitting, we should not split on escaped '/'.
                # So we can just add both to current.
                current.append(c)
                current.append(pattern[i+1])
                i += 2
            else:
                # Should have been caught earlier
                raise ValueError("Pattern ends with unpaired backslash")
        elif c == '/':
            segments.append(''.join(current))
            current = []
            i += 1
        else:
            current.append(c)
            i += 1
    segments.append(''.join(current))

    # Split path into segments by '/'
    path_segments = path.split('/') if path else []

    # Now match segments
    # We'll use recursion with memoization
    from functools import lru_cache

    @lru_cache(None)
    def match_segments(pi: int, si: int) -> bool:
        if pi == len(segments):
            return si == len(path_segments)
        seg = segments[pi]
        if seg == '**':
            # ** matches zero or more path segments
            # Try zero: skip this pattern segment
            if match_segments(pi + 1, si):
                return True
            # Try one or more: consume one path segment and keep **
            if si < len(path_segments):
                if match_segments(pi, si + 1):
                    return True
            return False
        else:
            if si >= len(path_segments):
                return False
            if not match_segment(seg, path_segments[si]):
                return False
            return match_segments(pi + 1, si + 1)

    def match_segment(pat: str, s: str) -> bool:
        # Match a single segment pattern against a string
        # pat may contain *, ?, [...], \ escapes
        # We'll parse pat into tokens and then match
        # We can use recursion with memoization
        # First, parse pat into tokens
        tokens = []
        i = 0
        n = len(pat)
        while i < n:
            c = pat[i]
            if c == '\\':
                if i + 1 < n:
                    tokens.append(('literal', pat[i+1]))
                    i += 2
                else:
                    # Should not happen due to earlier check
                    raise ValueError("Pattern ends with unpaired backslash")
            elif c == '?':
                tokens.append(('?', None))
                i += 1
            elif c == '*':
                # Check if it's part of **? But within a segment, ** is not special, so we treat as *
                # But we might have multiple * in a row, we can collapse them? Actually, ** is just two *s, which is same as one * for matching.
                # So we can just treat as *
                tokens.append(('*', None))
                i += 1
            elif c == '[':
                # Parse character class
                # Find closing ]
                j = i + 1
                if j < n and pat[j] == '!':
                    j += 1
                # If first char after [ or [! is ], it's literal ]
                if j < n and pat[j] == ']':
                    j += 1
                # Now find the closing ]
                while j < n and pat[j] != ']':
                    j += 1
                if j >= n:
                    # No closing ], so [ is literal
                    tokens.append(('literal', '['))
                    i += 1
                else:
                    # We have a valid class from i to j
                    class_str = pat[i+1:j]
                    tokens.append(('class', class_str))
                    i = j + 1
            else:
                tokens.append(('literal', c))
                i += 1

        # Now match tokens against s
        # We can use DP: dp[i][j] = match tokens[i:] against s[j:]
        # But tokens can have * which matches any sequence
        # We'll use recursion with memoization
        from functools import lru_cache

        @lru_cache(None)
        def match_tokens(ti: int, sj: int) -> bool:
            if ti == len(tokens):
                return sj == len(s)
            tok_type, tok_val = tokens[ti]
            if tok_type == 'literal':
                if sj < len(s) and s[sj] == tok_val:
                    return match_tokens(ti + 1, sj + 1)
                return False
            elif tok_type == '?':
                if sj < len(s) and s[sj] != '/':  # but s is a segment, so no '/'
                    return match_tokens(ti + 1, sj + 1)
                return False
            elif tok_type == '*':
                # * matches any sequence (including empty)
                # Try empty: skip *
                if match_tokens(ti + 1, sj):
                    return True
                # Try one or more: consume one char and keep *
                if sj < len(s):
                    if match_tokens(ti, sj + 1):
                        return True
                return False
            elif tok_type == 'class':
                if sj >= len(s):
                    return False
                c = s[sj]
                if c == '/':
                    return False
                # Parse class_str
                negate = False
                idx = 0
                if idx < len(tok_val) and tok_val[idx] == '!':
                    negate = True
                    idx += 1
                # Build set of chars and ranges
                # We need to handle ] as literal if first
                # and - as literal if first or last
                # Let's parse the class
                chars = set()
                ranges = []
                # We'll iterate through tok_val from idx
                k = idx
                while k < len(tok_val):
                    if tok_val[k] == ']' and k == idx:
                        # literal ]
                        chars.add(']')
                        k += 1
                    elif tok_val[k] == '-' and (k == idx or k == len(tok_val) - 1):
                        # literal -
                        chars.add('-')
                        k += 1
                    elif k + 2 < len(tok_val) and tok_val[k+1] == '-' and tok_val[k+2] != ']':
                        # range
                        start = tok_val[k]
                        end = tok_val[k+2]
                        ranges.append((start, end))
                        k += 3
                    else:
                        chars.add(tok_val[k])
                        k += 1
                # Check if c matches
                matched = False
                if c in chars:
                    matched = True
                else:
                    for start, end in ranges:
                        if start <= c <= end:
                            matched = True
                            break
                if negate:
                    matched = not matched
                if matched:
                    return match_tokens(ti + 1, sj + 1)
                return False
            return False

        return match_tokens(0, 0)

    return match_segments(0, 0)

def _split_pattern(pattern):
    """Split a glob pattern into path segments, respecting escapes and brackets."""
    segments = []
    current = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("Pattern ends with unpaired backslash")
            current.append(c)
            current.append(pattern[i + 1])
            i += 2
        elif c == '[':
            # Find the closing ']' respecting the bracket rules.
            j = i + 1
            if j < n and pattern[j] == '!':
                j += 1
            if j < n and pattern[j] == ']':
                j += 1
            while j < n and pattern[j] != ']':
                j += 1
            if j < n:
                # Include the whole bracket expression.
                current.append(pattern[i:j + 1])
                i = j + 1
            else:
                # No closing ']': literal '['.
                current.append('[')
                i += 1
        elif c == '/':
            segments.append(''.join(current))
            current = []
            i += 1
        else:
            current.append(c)
            i += 1
    segments.append(''.join(current))
    return segments


def _match_segment(pattern, text):
    """Match a single path segment (no '/') against a segment pattern."""
    # Tokenize the segment pattern into tokens.
    tokens = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("Pattern ends with unpaired backslash")
            tokens.append(('lit', pattern[i + 1]))
            i += 2
        elif c == '?':
            tokens.append(('any', None))
            i += 1
        elif c == '*':
            tokens.append(('star', None))
            i += 1
        elif c == '[':
            j = i + 1
            negated = False
            if j < n and pattern[j] == '!':
                negated = True
                j += 1
            chars = []
            if j < n and pattern[j] == ']':
                chars.append(']')
                j += 1
            while j < n and pattern[j] != ']':
                chars.append(pattern[j])
                j += 1
            if j >= n:
                # No closing ']': literal '['.
                tokens.append(('lit', '['))
                i += 1
            else:
                tokens.append(('class', (negated, chars)))
                i = j + 1
        else:
            tokens.append(('lit', c))
            i += 1

    # Build a set of allowed characters for a class token.
    def class_matches(negated, chars, ch):
        if ch == '/':
            return False
        matched = False
        k = 0
        m = len(chars)
        while k < m:
            if k + 2 < m and chars[k + 1] == '-':
                lo, hi = chars[k], chars[k + 2]
                if lo <= ch <= hi:
                    matched = True
                k += 3
            else:
                if chars[k] == ch:
                    matched = True
                k += 1
        return matched != negated

    # Dynamic programming over tokens and text.
    # dp[j] = True if text[:j] can be matched by tokens processed so far.
    dp = [False] * (len(text) + 1)
    dp[0] = True
    for tok in tokens:
        kind, val = tok
        ndp = [False] * (len(text) + 1)
        if kind == 'star':
            # '*' matches any sequence (including empty) of non-'/' chars.
            # Since text has no '/', it matches any sequence.
            ndp[0] = dp[0]
            for j in range(1, len(text) + 1):
                ndp[j] = dp[j] or ndp[j - 1]
        elif kind == 'any':
            for j in range(1, len(text) + 1):
                if dp[j - 1]:
                    ndp[j] = True
        elif kind == 'lit':
            for j in range(1, len(text) + 1):
                if dp[j - 1] and text[j - 1] == val:
                    ndp[j] = True
        elif kind == 'class':
            negated, chars = val
            for j in range(1, len(text) + 1):
                if dp[j - 1] and class_matches(negated, chars, text[j - 1]):
                    ndp[j] = True
        dp = ndp
    return dp[len(text)]


def glob_match(pattern: str, path: str) -> bool:
    pat_segs = _split_pattern(pattern)
    path_segs = path.split('/') if path != '' else ['']

    # Handle empty path edge case: path never starts/ends with '/', but could be ''.
    if path == '':
        path_segs = []

    # Match segments with '**' support.
    # dp[i][j] = True if pat_segs[:i] matches path_segs[:j].
    np = len(pat_segs)
    ns = len(path_segs)
    dp = [[False] * (ns + 1) for _ in range(np + 1)]
    dp[0][0] = True

    for i in range(1, np + 1):
        seg = pat_segs[i - 1]
        is_doublestar = (seg == '**')
        for j in range(ns + 1):
            if is_doublestar:
                # '**' matches zero or more whole segments.
                if dp[i - 1][j]:
                    dp[i][j] = True
                if j > 0 and dp[i][j - 1]:
                    dp[i][j] = True
            else:
                if j > 0 and dp[i - 1][j - 1]:
                    if _match_segment(seg, path_segs[j - 1]):
                        dp[i][j] = True

    return dp[np][ns]

def glob_match(pattern: str, path: str) -> bool:
    tokens = []
    i = 0
    n = len(pattern)

    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with unpaired backslash")
            tokens.append(('lit', pattern[i + 1]))
            i += 2
        elif c == '?':
            tokens.append(('?',))
            i += 1
        elif c == '*':
            if i + 1 < n and pattern[i + 1] == '*':
                start_ok = (i == 0) or (pattern[i - 1] == '/')
                end_ok = (i + 2 == n) or (pattern[i + 2] == '/')
                if start_ok and end_ok:
                    tokens.append(('**',))
                    i += 2
                else:
                    tokens.append(('*',))
                    i += 1
            else:
                tokens.append(('*',))
                i += 1
        elif c == '[':
            j = i + 1
            neg = False
            if j < n and pattern[j] == '!':
                neg = True
                j += 1
            items = []
            if j < n and pattern[j] == ']':
                items.append(('char', ']'))
                j += 1
            closed = False
            while j < n:
                if pattern[j] == ']':
                    closed = True
                    j += 1
                    break
                if j + 2 < n and pattern[j + 1] == '-' and pattern[j + 2] != ']':
                    lo = pattern[j]
                    hi = pattern[j + 2]
                    items.append(('range', lo, hi))
                    j += 3
                else:
                    items.append(('char', pattern[j]))
                    j += 1
            if not closed:
                tokens.append(('lit', '['))
                i += 1
            else:
                tokens.append(('class', neg, items))
                i = j
        else:
            tokens.append(('lit', c))
            i += 1

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match(ti, pi):
        if ti == len(tokens):
            return pi == len(path)
        tok = tokens[ti]
        if tok[0] == 'lit':
            if pi < len(path) and path[pi] == tok[1]:
                return match(ti + 1, pi + 1)
            return False
        elif tok[0] == '?':
            if pi < len(path) and path[pi] != '/':
                return match(ti + 1, pi + 1)
            return False
        elif tok[0] == '*':
            if match(ti + 1, pi):
                return True
            if pi < len(path) and path[pi] != '/':
                return match(ti, pi + 1)
            return False
        elif tok[0] == '**':
            # Try matching zero or more whole segments
            if match(ti + 1, pi):
                return True
            if pi < len(path):
                next_slash = path.find('/', pi)
                if next_slash == -1:
                    # consume rest of path as one segment
                    if match(ti + 1, len(path)):
                        return True
                else:
                    if match(ti, next_slash + 1):
                        return True
            return False
        elif tok[0] == 'class':
            if pi >= len(path):
                return False
            ch = path[pi]
            if ch == '/':
                return False
            neg, items = tok[1], tok[2]
            matched = False
            for item in items:
                if item[0] == 'char':
                    if ch == item[1]:
                        matched = True
                        break
                else:
                    lo, hi = item[1], item[2]
                    if lo <= ch <= hi:
                        matched = True
                        break
            if neg:
                matched = not matched
            if matched:
                return match(ti + 1, pi + 1)
            return False
        return False

    return match(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    # Check for trailing backslash
    if pattern.endswith('\\') and (len(pattern) < 2 or pattern[-2] != '\\'):
        # Actually need to check if it's unpaired
        # Count trailing backslashes
        i = len(pattern) - 1
        cnt = 0
        while i >= 0 and pattern[i] == '\\':
            cnt += 1
            i -= 1
        if cnt % 2 == 1:
            raise ValueError("Pattern ends with unpaired backslash")

    # Parse pattern into segments
    segments = []
    i = 0
    n = len(pattern)
    while i < n:
        # Read one segment until '/' or end
        start = i
        while i < n and pattern[i] != '/':
            if pattern[i] == '\\':
                i += 2  # skip escaped char
            else:
                i += 1
        seg = pattern[start:i]
        segments.append(seg)
        if i < n and pattern[i] == '/':
            i += 1  # skip '/'

    # Now check which segments are '**'
    # A segment is '**' if it's exactly "**" (no escapes)
    is_double_star = []
    for seg in segments:
        if seg == '**':
            is_double_star.append(True)
        else:
            is_double_star.append(False)

    # Split path into segments
    path_segs = path.split('/') if path else []

    # Now match segments against path_segs with ** handling
    # Use DP: dp[i][j] = match segments[i:] against path_segs[j:]
    m = len(segments)
    k = len(path_segs)

    # Precompile normal segments into matchers
    def compile_segment(seg):
        # Returns a function that matches a string against this segment pattern
        # Handle escapes, *, ?, [...]
        tokens = []
        i = 0
        L = len(seg)
        while i < L:
            c = seg[i]
            if c == '\\':
                if i + 1 < L:
                    tokens.append(('literal', seg[i+1]))
                    i += 2
                else:
                    # Should not happen due to earlier check, but just in case
                    tokens.append(('literal', '\\'))
                    i += 1
            elif c == '*':
                tokens.append(('star',))
                i += 1
            elif c == '?':
                tokens.append(('any',))
                i += 1
            elif c == '[':
                # Try to parse character class
                j = i + 1
                neg = False
                if j < L and seg[j] == '!':
                    neg = True
                    j += 1
                # Now parse set
                # Special: ']' right after '[' or '[!' is literal
                chars = []
                if j < L and seg[j] == ']':
                    chars.append(']')
                    j += 1
                # Now read until closing ']'
                closed = False
                while j < L:
                    if seg[j] == ']':
                        closed = True
                        break
                    if seg[j] == '\\':
                        if j + 1 < L:
                            chars.append(seg[j+1])
                            j += 2
                        else:
                            chars.append('\\')
                            j += 1
                    else:
                        chars.append(seg[j])
                        j += 1
                if not closed:
                    # No closing ']', treat '[' as literal
                    tokens.append(('literal', '['))
                    i += 1
                else:
                    # Process ranges
                    # chars may contain '-' for ranges
                    # But '-' is literal if first or last
                    # We'll build a set of allowed chars and ranges
                    # Actually easier: build a list of (char) or (start, end)
                    # But need to handle '-' as literal if first or last
                    # Let's parse chars into ranges
                    ranges = []
                    idx = 0
                    while idx < len(chars):
                        if idx + 2 < len(chars) and chars[idx+1] == '-':
                            # range
                            ranges.append((chars[idx], chars[idx+2]))
                            idx += 3
                        else:
                            ranges.append((chars[idx], chars[idx]))
                            idx += 1
                    tokens.append(('class', neg, ranges))
                    i = j + 1  # skip closing ']'
            else:
                tokens.append(('literal', c))
                i += 1

        # Now return a matcher function
        def match(s):
            # DP match tokens against s
            # tokens: list of ('literal', ch), ('star',), ('any',), ('class', neg, ranges)
            # s: string to match
            # Use recursion with memo
            from functools import lru_cache
            @lru_cache(None)
            def dp(ti, si):
                if ti == len(tokens):
                    return si == len(s)
                tok = tokens[ti]
                if tok[0] == 'literal':
                    if si < len(s) and s[si] == tok[1]:
                        return dp(ti+1, si+1)
                    return False
                elif tok[0] == 'any':
                    if si < len(s) and s[si] != '/':
                        return dp(ti+1, si+1)
                    return False
                elif tok[0] == 'star':
                    # match zero or more non-/ chars
                    # try all possibilities
                    for k in range(si, len(s)+1):
                        if k > si and s[k-1] == '/':
                            break
                        if dp(ti+1, k):
                            return True
                    return False
                elif tok[0] == 'class':
                    if si < len(s) and s[si] != '/':
                        ch = s[si]
                        neg, ranges = tok[1], tok[2]
                        matched = False
                        for a, b in ranges:
                            if a <= ch <= b:
                                matched = True
                                break
                        if neg:
                            matched = not matched
                        if matched:
                            return dp(ti+1, si+1)
                    return False
                return False
            return dp(0, 0)
        return match

    # Compile normal segments
    matchers = []
    for seg, is_ds in zip(segments, is_double_star):
        if is_ds:
            matchers.append(None)
        else:
            matchers.append(compile_segment(seg))

    # DP for segment matching
    from functools import lru_cache
    @lru_cache(None)
    def dp(i, j):
        if i == m:
            return j == k
        if is_double_star[i]:
            # ** matches zero or more segments
            # try all possibilities
            for nj in range(j, k+1):
                if dp(i+1, nj):
                    return True
            return False
        else:
            if j < k and matchers[i](path_segs[j]):
                return dp(i+1, j+1)
            return False

    return dp(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    # Validate trailing backslash
    if pattern.endswith("\\"):
        raise ValueError("pattern ends with an unpaired backslash")

    # Split pattern into raw segments by unescaped '/'
    segments = []
    buf = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == "\\":
            if i + 1 >= len(pattern):
                raise ValueError("pattern ends with an unpaired backslash")
            buf.append(c)
            buf.append(pattern[i + 1])
            i += 2
        elif c == "/":
            segments.append("".join(buf))
            buf = []
            i += 1
        else:
            buf.append(c)
            i += 1
    segments.append("".join(buf))

    path_segments = path.split("/") if path else []

    # Match segment lists with special handling for "**"
    def match_segments(pi: int, si: int) -> bool:
        if pi == len(segments):
            return si == len(path_segments)
        seg = segments[pi]
        if seg == "**":
            # ** matches zero or more whole path segments
            if match_segments(pi + 1, si):
                return True
            if si < len(path_segments):
                return match_segments(pi, si + 1)
            return False
        else:
            if si >= len(path_segments):
                return False
            if not match_segment(seg, path_segments[si]):
                return False
            return match_segments(pi + 1, si + 1)

    return match_segments(0, 0)


def match_segment(pattern: str, text: str) -> bool:
    # Parse pattern segment into tokens
    tokens = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == "\\":
            if i + 1 >= len(pattern):
                raise ValueError("pattern ends with an unpaired backslash")
            tokens.append(("lit", pattern[i + 1]))
            i += 2
        elif c == "?":
            tokens.append(("?",))
            i += 1
        elif c == "*":
            tokens.append(("*",))
            i += 1
        elif c == "[":
            # Try to parse a character class
            j = i + 1
            negated = False
            if j < len(pattern) and pattern[j] == "!":
                negated = True
                j += 1
            # A ']' right after '[' or '[!' is literal
            if j < len(pattern) and pattern[j] == "]":
                j += 1
            # Find closing ']'
            close = -1
            k = j
            while k < len(pattern):
                if pattern[k] == "]":
                    close = k
                    break
                k += 1
            if close == -1:
                # No closing ']', treat '[' as literal
                tokens.append(("lit", "["))
                i += 1
            else:
                content = pattern[i + 1 : close]
                # Parse content into ranges
                ranges = []
                if content.startswith("!"):
                    negated = True
                    content = content[1:]
                # Handle first ']' as literal
                if content.startswith("]"):
                    ranges.append(("]", "]"))
                    content = content[1:]
                # Parse ranges
                idx = 0
                while idx < len(content):
                    if idx + 2 < len(content) and content[idx + 1] == "-":
                        ranges.append((content[idx], content[idx + 2]))
                        idx += 3
                    else:
                        ranges.append((content[idx], content[idx]))
                        idx += 1
                tokens.append(("class", negated, ranges))
                i = close + 1
        else:
            tokens.append(("lit", c))
            i += 1

    # Match tokens against text
    def match_tokens(ti: int, si: int) -> bool:
        if ti == len(tokens):
            return si == len(text)
        tok = tokens[ti]
        if tok[0] == "?":
            if si >= len(text):
                return False
            return match_tokens(ti + 1, si + 1)
        elif tok[0] == "*":
            # * matches any sequence (including empty)
            if match_tokens(ti + 1, si):
                return True
            if si < len(text):
                return match_tokens(ti, si + 1)
            return False
        elif tok[0] == "lit":
            if si >= len(text) or text[si] != tok[1]:
                return False
            return match_tokens(ti + 1, si + 1)
        elif tok[0] == "class":
            if si >= len(text):
                return False
            ch = text[si]
            negated = tok[1]
            ranges = tok[2]
            matched = False
            for lo, hi in ranges:
                if lo <= ch <= hi:
                    matched = True
                    break
            if negated:
                matched = not matched
            if not matched:
                return False
            return match_tokens(ti + 1, si + 1)
        return False

    return match_tokens(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    # Validate pattern: no unpaired trailing backslash.
    i = 0
    n = len(pattern)
    while i < n:
        if pattern[i] == '\\':
            if i + 1 >= n:
                raise ValueError("Pattern ends with unpaired backslash")
            i += 2
        else:
            i += 1

    pat_segs = pattern.split('/')
    path_segs = path.split('/')

    # Determine which pattern segments are "**" whole segments.
    def is_double_star(seg):
        return seg == '**'

    # Compile a single non-** segment into a matcher function.
    def compile_segment(seg):
        # Tokenize into a list of matchers.
        tokens = []  # each is a function(ch)->bool
        i = 0
        m = len(seg)
        while i < m:
            c = seg[i]
            if c == '\\':
                # next char literal
                if i + 1 >= m:
                    raise ValueError("Pattern ends with unpaired backslash")
                lit = seg[i + 1]
                tokens.append(('lit', lit))
                i += 2
            elif c == '?':
                tokens.append(('any',))
                i += 1
            elif c == '*':
                # collapse consecutive '*' (non-** case)
                tokens.append(('star',))
                i += 1
            elif c == '[':
                # try to parse a class
                parsed = parse_class(seg, i)
                if parsed is None:
                    tokens.append(('lit', '['))
                    i += 1
                else:
                    matcher, next_i = parsed
                    tokens.append(('class', matcher))
                    i = next_i
            else:
                tokens.append(('lit', c))
                i += 1

        # Match tokens against a string (no '/' inside since segments are split).
        def match(s):
            # DP over token index and string index.
            # Use recursion with memo.
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def rec(ti, si):
                if ti == len(tokens):
                    return si == len(s)
                tok = tokens[ti]
                kind = tok[0]
                if kind == 'lit':
                    if si < len(s) and s[si] == tok[1]:
                        return rec(ti + 1, si + 1)
                    return False
                elif kind == 'any':
                    if si < len(s):
                        return rec(ti + 1, si + 1)
                    return False
                elif kind == 'star':
                    # match zero or more chars
                    if rec(ti + 1, si):
                        return True
                    if si < len(s):
                        return rec(ti, si + 1)
                    return False
                elif kind == 'class':
                    if si < len(s) and tok[1](s[si]):
                        return rec(ti + 1, si + 1)
                    return False
                return False

            return rec(0, 0)

        return match

    def parse_class(seg, start):
        # start is index of '['
        i = start + 1
        n = len(seg)
        negated = False
        if i < n and seg[i] == '!':
            negated = True
            i += 1
        # find closing ']'
        j = i
        # A ']' right after '[' or '[!' is a literal ']'
        if j < n and seg[j] == ']':
            j += 1
        while j < n and seg[j] != ']':
            j += 1
        if j >= n:
            return None  # no closing ']', treat '[' as literal
        content = seg[i:j]
        # Parse content into items: ('char', c) or ('range', a, b)
        items = []
        k = 0
        m = len(content)
        while k < m:
            ch = content[k]
            # Check for range: current char, then '-', then next char
            if (k + 2 < m and content[k + 1] == '-'):
                # range from ch to content[k+2]
                items.append(('range', ch, content[k + 2]))
                k += 3
            else:
                items.append(('char', ch))
                k += 1

        def matcher(ch):
            if ch == '/':
                return False
            in_set = False
            for item in items:
                if item[0] == 'char':
                    if ch == item[1]:
                        in_set = True
                        break
                else:
                    if item[1] <= ch <= item[2]:
                        in_set = True
                        break
            return (not in_set) if negated else in_set

        return matcher, j + 1

    # Compile all non-** segments.
    compiled = []
    for seg in pat_segs:
        if is_double_star(seg):
            compiled.append(None)  # marker for **
        else:
            compiled.append(compile_segment(seg))

    # Match pattern segments against path segments with ** support.
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match_segs(pi, si):
        if pi == len(compiled):
            return si == len(path_segs)
        seg = compiled[pi]
        if seg is None:
            # '**' matches zero or more path segments
            # try matching zero segments
            if match_segs(pi + 1, si):
                return True
            # or consume one path segment
            if si < len(path_segs):
                return match_segs(pi, si + 1)
            return False
        else:
            if si < len(path_segs) and seg(path_segs[si]):
                return match_segs(pi + 1, si + 1)
            return False

    return match_segs(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    # Parse pattern into tokens
    tokens = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("Pattern ends with unpaired backslash")
            tokens.append(('literal', pattern[i+1]))
            i += 2
        elif c == '?':
            tokens.append(('?',))
            i += 1
        elif c == '*':
            if i + 1 < n and pattern[i+1] == '*':
                start_ok = (i == 0 or pattern[i-1] == '/')
                end_ok = (i + 2 == n or pattern[i+2] == '/')
                if start_ok and end_ok:
                    tokens.append(('**',))
                    i += 2
                else:
                    tokens.append(('*',))
                    i += 1
            else:
                tokens.append(('*',))
                i += 1
        elif c == '[':
            j = i + 1
            if j >= n:
                tokens.append(('literal', '['))
                i += 1
                continue
            negated = False
            if pattern[j] == '!':
                negated = True
                j += 1
            chars = []
            if j < n and pattern[j] == ']':
                chars.append(']')
                j += 1
            closed = False
            while j < n:
                if pattern[j] == ']':
                    closed = True
                    j += 1
                    break
                elif pattern[j] == '\\':
                    if j + 1 >= n:
                        chars.append('\\')
                        j += 1
                    else:
                        chars.append(pattern[j+1])
                        j += 2
                else:
                    chars.append(pattern[j])
                    j += 1
            if not closed:
                tokens.append(('literal', '['))
                i += 1
                continue
            ranges = []
            k = 0
            while k < len(chars):
                if k + 2 < len(chars) and chars[k+1] == '-' and chars[k] != '-' and chars[k+2] != '-':
                    ranges.append((chars[k], chars[k+2]))
                    k += 3
                else:
                    ranges.append((chars[k], chars[k]))
                    k += 1
            tokens.append(('class', negated, ranges))
            i = j
        else:
            tokens.append(('literal', c))
            i += 1

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match(ti, pi):
        if ti == len(tokens):
            return pi == len(path)

        tok = tokens[ti]
        if tok[0] == 'literal':
            if pi < len(path) and path[pi] == tok[1]:
                return match(ti+1, pi+1)
            return False
        elif tok[0] == '?':
            if pi < len(path) and path[pi] != '/':
                return match(ti+1, pi+1)
            return False
        elif tok[0] == '*':
            if match(ti+1, pi):
                return True
            j = pi
            while j < len(path) and path[j] != '/':
                if match(ti+1, j+1):
                    return True
                j += 1
            return False
        elif tok[0] == '**':
            # Try matching zero segments.
            # If the next token is a literal '/', we can also skip it (since **/ can match zero segments).
            if match(ti+1, pi):
                return True
            if ti + 1 < len(tokens) and tokens[ti+1] == ('literal', '/'):
                if match(ti+2, pi):
                    return True
            # Try matching one or more segments.
            # A segment starts at pi if pi is not at '/' and pi < len(path).
            if pi < len(path) and path[pi] != '/':
                j = pi
                while j < len(path) and path[j] != '/':
                    j += 1
                # j is at '/' or end.
                # After consuming the segment, we can either:
                # - continue with ** at j (if j is at '/', we need to skip the '/' first)
                # - or move to next token at j (if next token is '/', it matches the '/')
                # - or if next token is '/', we can skip it and continue with ** after it
                if j < len(path) and path[j] == '/':
                    # Option 1: continue with ** after skipping the '/'
                    if match(ti, j+1):
                        return True
                    # Option 2: move to next token at j (which might be '/')
                    if match(ti+1, j):
                        return True
                    # Option 3: if next token is '/', skip it and continue with ** after it
                    if ti + 1 < len(tokens) and tokens[ti+1] == ('literal', '/'):
                        if match(ti, j+1):
                            return True
                else:
                    # j is at end
                    if match(ti, j):
                        return True
                    if match(ti+1, j):
                        return True
            return False
        elif tok[0] == 'class':
            if pi < len(path) and path[pi] != '/':
                ch = path[pi]
                negated = tok[1]
                ranges = tok[2]
                matched = False
                for lo, hi in ranges:
                    if lo <= ch <= hi:
                        matched = True
                        break
                if matched != negated:
                    return match(ti+1, pi+1)
            return False
        else:
            raise ValueError("Unknown token")

    return match(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    # Split pattern into segments, respecting backslash escapes.
    # A backslash escapes the next character, so an escaped '/' is not a separator.
    segments = []
    current = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with an unpaired backslash")
            current.append(c)
            current.append(pattern[i + 1])
            i += 2
        elif c == '/':
            segments.append(''.join(current))
            current = []
            i += 1
        else:
            current.append(c)
            i += 1
    segments.append(''.join(current))

    path_segments = path.split('/') if path != '' else []

    # Compile a non-** segment into a list of tokens.
    # Token types:
    #   ('lit', ch)
    #   ('any',)          -> ?
    #   ('star',)         -> *
    #   ('class', negated, items) where items is list of (lo, hi) ranges or single chars
    def compile_segment(seg):
        tokens = []
        i = 0
        m = len(seg)
        while i < m:
            c = seg[i]
            if c == '\\':
                if i + 1 >= m:
                    raise ValueError("pattern ends with an unpaired backslash")
                tokens.append(('lit', seg[i + 1]))
                i += 2
            elif c == '?':
                tokens.append(('any',))
                i += 1
            elif c == '*':
                tokens.append(('star',))
                i += 1
            elif c == '[':
                # Try to parse a character class.
                j = i + 1
                negated = False
                if j < m and seg[j] == '!':
                    negated = True
                    j += 1
                items = []
                # A ']' right after '[' or '[!' is a literal ']'.
                if j < m and seg[j] == ']':
                    items.append((']', ']'))
                    j += 1
                closed = False
                while j < m:
                    if seg[j] == ']':
                        closed = True
                        j += 1
                        break
                    # Check for range a-z
                    if (j + 2 < m and seg[j + 1] == '-' and seg[j + 2] != ']'):
                        lo = seg[j]
                        hi = seg[j + 2]
                        items.append((lo, hi))
                        j += 3
                    else:
                        ch = seg[j]
                        items.append((ch, ch))
                        j += 1
                if not closed:
                    # No closing ']': '[' is a literal.
                    tokens.append(('lit', '['))
                    i += 1
                else:
                    tokens.append(('class', negated, items))
                    i = j
            else:
                tokens.append(('lit', c))
                i += 1
        return tokens

    compiled = []
    for seg in segments:
        if seg == '**':
            compiled.append(None)  # None marks a ** segment
        else:
            compiled.append(compile_segment(seg))

    # Match a single compiled segment (list of tokens) against a path segment.
    def match_segment(tokens, s):
        # DP over token index and string index.
        memo = {}

        def rec(ti, si):
            key = (ti, si)
            if key in memo:
                return memo[key]
            if ti == len(tokens):
                res = (si == len(s))
            else:
                tok = tokens[ti]
                kind = tok[0]
                if kind == 'lit':
                    if si < len(s) and s[si] == tok[1]:
                        res = rec(ti + 1, si + 1)
                    else:
                        res = False
                elif kind == 'any':
                    if si < len(s) and s[si] != '/':
                        res = rec(ti + 1, si + 1)
                    else:
                        res = False
                elif kind == 'star':
                    # Match zero or more non-'/' characters.
                    res = rec(ti + 1, si)
                    if not res and si < len(s) and s[si] != '/':
                        res = rec(ti, si + 1)
                elif kind == 'class':
                    negated = tok[1]
                    items = tok[2]
                    if si < len(s) and s[si] != '/':
                        ch = s[si]
                        inside = False
                        for lo, hi in items:
                            if lo <= ch <= hi:
                                inside = True
                                break
                        if inside != negated:
                            res = rec(ti + 1, si + 1)
                        else:
                            res = False
                    else:
                        res = False
                else:
                    res = False
            memo[key] = res
            return res

        return rec(0, 0)

    # Match compiled segments against path segments, handling ** specially.
    memo2 = {}

    def rec2(pi, si):
        key = (pi, si)
        if key in memo2:
            return memo2[key]
        if pi == len(compiled):
            res = (si == len(path_segments))
        else:
            seg = compiled[pi]
            if seg is None:
                # ** matches zero or more whole path segments.
                res = rec2(pi + 1, si)
                if not res and si < len(path_segments):
                    res = rec2(pi, si + 1)
            else:
                if si < len(path_segments) and match_segment(seg, path_segments[si]):
                    res = rec2(pi + 1, si + 1)
                else:
                    res = False
        memo2[key] = res
        return res

    return rec2(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    # Validate: a pattern ending with an unpaired backslash is invalid.
    # Count trailing backslashes; odd count means the last one is unpaired.
    bs = 0
    i = len(pattern) - 1
    while i >= 0 and pattern[i] == '\\':
        bs += 1
        i -= 1
    if bs % 2 == 1:
        raise ValueError("Pattern ends with unpaired backslash")

    # Parse pattern into path segments, respecting escapes.
    # A '/' is a separator only when not escaped.
    segments = []
    current = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            # We already know there is a next char (no unpaired trailing backslash)
            current.append(c)
            current.append(pattern[i + 1])
            i += 2
        elif c == '/':
            segments.append(''.join(current))
            current = []
            i += 1
        else:
            current.append(c)
            i += 1
    segments.append(''.join(current))

    # Special case: empty pattern -> segments == [''] which should match empty path.
    if pattern == '':
        return path == ''

    path_segments = path.split('/') if path != '' else []

    # Determine which segments are "**" (whole segment, unescaped).
    def is_double_star(seg: str) -> bool:
        return seg == '**'

    from functools import lru_cache

    @lru_cache(None)
    def match_segments(pi: int, si: int) -> bool:
        if pi == len(segments):
            return si == len(path_segments)
        seg = segments[pi]
        if is_double_star(seg):
            # ** matches zero or more whole path segments
            if match_segments(pi + 1, si):
                return True
            if si < len(path_segments):
                if match_segments(pi, si + 1):
                    return True
            return False
        else:
            if si >= len(path_segments):
                return False
            if not match_segment(seg, path_segments[si]):
                return False
            return match_segments(pi + 1, si + 1)

    def match_segment(pat: str, text: str) -> bool:
        # Tokenize the segment pattern.
        tokens = []
        m = len(pat)
        i = 0
        while i < m:
            c = pat[i]
            if c == '\\':
                # next char is literal (guaranteed to exist)
                tokens.append(('literal', pat[i + 1]))
                i += 2
            elif c == '*':
                tokens.append(('star',))
                i += 1
            elif c == '?':
                tokens.append(('any',))
                i += 1
            elif c == '[':
                j = i + 1
                negate = False
                if j < m and pat[j] == '!':
                    negate = True
                    j += 1
                chars = []
                # A ']' right after '[' or '[!' is a literal ']'
                if j < m and pat[j] == ']':
                    chars.append(']')
                    j += 1
                while j < m and pat[j] != ']':
                    if pat[j] == '\\':
                        if j + 1 < m:
                            chars.append(pat[j + 1])
                            j += 2
                        else:
                            chars.append('\\')
                            j += 1
                    else:
                        chars.append(pat[j])
                        j += 1
                if j >= m:
                    # No closing ']' -> literal '['
                    tokens.append(('literal', '['))
                    i += 1
                else:
                    # Build ranges from chars.
                    ranges = []
                    k = 0
                    L = len(chars)
                    while k < L:
                        if k + 2 < L and chars[k + 1] == '-':
                            start = chars[k]
                            end = chars[k + 2]
                            if ord(start) <= ord(end):
                                ranges.append((start, end))
                            else:
                                ranges.append((start, start))
                                ranges.append(('-', '-'))
                                ranges.append((end, end))
                            k += 3
                        else:
                            ranges.append((chars[k], chars[k]))
                            k += 1
                    tokens.append(('class', negate, ranges))
                    i = j + 1
            else:
                tokens.append(('literal', c))
                i += 1

        n = len(text)

        @lru_cache(None)
        def dp(ti: int, tj: int) -> bool:
            if ti == len(tokens):
                return tj == n
            tok = tokens[ti]
            kind = tok[0]
            if kind == 'star':
                if dp(ti + 1, tj):
                    return True
                if tj < n:
                    if dp(ti, tj + 1):
                        return True
                return False
            elif kind == 'any':
                if tj < n:
                    return dp(ti + 1, tj + 1)
                return False
            elif kind == 'literal':
                if tj < n and text[tj] == tok[1]:
                    return dp(ti + 1, tj + 1)
                return False
            elif kind == 'class':
                if tj < n:
                    ch = text[tj]
                    negate, ranges = tok[1], tok[2]
                    matched = False
                    for start, end in ranges:
                        if start <= ch <= end:
                            matched = True
                            break
                    if negate:
                        matched = not matched
                    if matched:
                        return dp(ti + 1, tj + 1)
                return False
            return False

        return dp(0, 0)

    return match_segments(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    # Validate trailing unpaired backslash in the whole pattern.
    i = 0
    while i < len(pattern):
        if pattern[i] == '\\':
            if i + 1 == len(pattern):
                raise ValueError("pattern ends with an unpaired backslash")
            i += 2
        else:
            i += 1

    # Paths never start or end with '/', and never contain '//'.
    if path.startswith('/') or path.endswith('/') or '//' in path:
        return False

    pat_segs = pattern.split('/')
    path_segs = path.split('/') if path != '' else []

    def match_segment(pat: str, s: str) -> bool:
        memo = {}

        def parse_class(p: str, i: int):
            # p[i] == '['
            j = i + 1
            negate = False
            if j < len(p) and p[j] == '!':
                negate = True
                j += 1

            chars = []
            first = True
            while j < len(p):
                if p[j] == ']' and not first:
                    return (j + 1, negate, chars)
                first = False

                if p[j] == '\\':
                    if j + 1 >= len(p):
                        return None
                    chars.append(('char', p[j + 1]))
                    j += 2
                    continue

                if (
                    j + 2 < len(p)
                    and p[j + 1] == '-'
                    and p[j + 2] != ']'
                ):
                    chars.append(('range', p[j], p[j + 2]))
                    j += 3
                else:
                    chars.append(('char', p[j]))
                    j += 1

            return None

        def class_match(chars, negate, ch):
            found = False
            for kind, *vals in chars:
                if kind == 'char':
                    if ch == vals[0]:
                        found = True
                        break
                else:
                    lo, hi = vals
                    if lo <= ch <= hi:
                        found = True
                        break
            return found != negate

        def rec(pi: int, si: int) -> bool:
            key = (pi, si)
            if key in memo:
                return memo[key]

            if pi == len(pat):
                ans = si == len(s)
                memo[key] = ans
                return ans

            c = pat[pi]

            if c == '\\':
                if pi + 1 >= len(pat):
                    ans = False
                elif si < len(s) and s[si] == pat[pi + 1]:
                    ans = rec(pi + 2, si + 1)
                else:
                    ans = False
                memo[key] = ans
                return ans

            if c == '?':
                ans = si < len(s) and s[si] != '/' and rec(pi + 1, si + 1)
                memo[key] = ans
                return ans

            if c == '*':
                ans = rec(pi + 1, si) or (si < len(s) and s[si] != '/' and rec(pi, si + 1))
                memo[key] = ans
                return ans

            if c == '[':
                parsed = parse_class(pat, pi)
                if parsed is not None:
                    npi, negate, chars = parsed
                    if si < len(s) and s[si] != '/' and class_match(chars, negate, s[si]):
                        ans = rec(npi, si + 1)
                    else:
                        ans = False
                    memo[key] = ans
                    return ans

            if si < len(s) and s[si] == c:
                ans = rec(pi + 1, si + 1)
            else:
                ans = False
            memo[key] = ans
            return ans

        return rec(0, 0)

    memo = {}

    def match_segments(pi: int, si: int) -> bool:
        key = (pi, si)
        if key in memo:
            return memo[key]

        if pi == len(pat_segs):
            ans = si == len(path_segs)
            memo[key] = ans
            return ans

        seg = pat_segs[pi]

        if seg == '**':
            # Match zero or more whole path segments.
            if match_segments(pi + 1, si):
                memo[key] = True
                return True
            if si < len(path_segs) and match_segments(pi, si + 1):
                memo[key] = True
                return True
            memo[key] = False
            return False

        if si >= len(path_segs):
            memo[key] = False
            return False

        if match_segment(seg, path_segs[si]):
            ans = match_segments(pi + 1, si + 1)
        else:
            ans = False
        memo[key] = ans
        return ans

    return match_segments(0, 0)

@lru_cache(maxsize=None)
    def match_segment(pat: str, s: str) -> bool:
        ...
        @lru_cache(maxsize=None)
        def rec(i: int, j: int) -> bool:
            ...
        return rec(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    # Tokenize pattern into path segments, respecting backslash escapes.
    # A segment is a list of tokens; '**' is recognized only as a whole segment.
    segments = []
    cur = []
    i = 0
    n = len(pattern)

    def parse_class(seg, i):
        # seg is the pattern string, i points at '['
        j = i + 1
        negated = False
        if j < len(seg) and seg[j] == '!':
            negated = True
            j += 1
        chars = set()
        ranges = []
        first = True
        if j < len(seg) and seg[j] == ']':
            chars.add(']')
            j += 1
            first = False
        while j < len(seg) and seg[j] != ']':
            if first and seg[j] == '-':
                chars.add('-')
                j += 1
                first = False
            elif j + 2 < len(seg) and seg[j + 1] == '-' and seg[j + 2] != ']':
                ranges.append((seg[j], seg[j + 2]))
                j += 3
                first = False
            else:
                chars.add(seg[j])
                j += 1
                first = False
        if j >= len(seg):
            # No closing ']': literal '['
            return None, i + 1
        return ('class', negated, chars, ranges), j + 1

    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with unpaired backslash")
            cur.append(('lit', pattern[i + 1]))
            i += 2
        elif c == '/':
            segments.append(cur)
            cur = []
            i += 1
        elif c == '?':
            cur.append(('any',))
            i += 1
        elif c == '*':
            if i + 1 < n and pattern[i + 1] == '*':
                # Check if this '**' is a whole segment.
                left_ok = (i == 0) or (pattern[i - 1] == '/')
                # find end of run of '*'
                k = i
                while k < n and pattern[k] == '*':
                    k += 1
                right_ok = (k == n) or (pattern[k] == '/')
                if left_ok and right_ok:
                    cur.append(('globstar',))
                    i = k
                else:
                    cur.append(('star',))
                    i += 1
            else:
                cur.append(('star',))
                i += 1
        elif c == '[':
            tok, ni = parse_class(pattern, i)
            if tok is None:
                cur.append(('lit', '['))
                i = ni
            else:
                cur.append(tok)
                i = ni
        else:
            cur.append(('lit', c))
            i += 1
    segments.append(cur)

    path_segs = path.split('/')

    def match_segment(tokens, s):
        # DP over tokens and string positions
        L = len(s)
        reachable = [False] * (L + 1)
        reachable[0] = True
        for t in tokens:
            new_reach = [False] * (L + 1)
            if t[0] == 'lit':
                ch = t[1]
                for p in range(L):
                    if reachable[p] and s[p] == ch:
                        new_reach[p + 1] = True
            elif t[0] == 'any':
                for p in range(L):
                    if reachable[p] and s[p] != '/':
                        new_reach[p + 1] = True
            elif t[0] == 'star':
                acc = False
                for p in range(L + 1):
                    if reachable[p]:
                        acc = True
                    if acc:
                        new_reach[p] = True
            elif t[0] == 'class':
                _, negated, chars, ranges = t
                for p in range(L):
                    if not reachable[p]:
                        continue
                    ch = s[p]
                    if ch == '/':
                        continue
                    inside = ch in chars
                    if not inside:
                        for lo, hi in ranges:
                            if lo <= ch <= hi:
                                inside = True
                                break
                    if inside != negated:
                        new_reach[p + 1] = True
            reachable = new_reach
        return reachable[L]

    P = len(segments)
    S = len(path_segs)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def rec(pi, si):
        if pi == P:
            return si == S
        seg = segments[pi]
        if len(seg) == 1 and seg[0][0] == 'globstar':
            for k in range(si, S + 1):
                if rec(pi + 1, k):
                    return True
            return False
        if si >= S:
            return False
        if not match_segment(seg, path_segs[si]):
            return False
        return rec(pi + 1, si + 1)

    return rec(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    pat_segs = _split_pattern(pattern)
    path_segs = path.split('/') if path != '' else []
    return _match_segments(pat_segs, path_segs)


def _split_pattern(pattern: str):
    """Split pattern into path segments, respecting escapes and brackets.

    Returns a list of segment strings. Raises ValueError on trailing backslash.
    """
    segs = []
    cur = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with unpaired backslash")
            cur.append(c)
            cur.append(pattern[i + 1])
            i += 2
        elif c == '[':
            # find closing bracket
            j = i + 1
            if j < n and pattern[j] == '!':
                j += 1
            if j < n and pattern[j] == ']':
                j += 1
            while j < n and pattern[j] != ']':
                j += 1
            if j < n:
                # valid bracket expression
                cur.append(pattern[i:j + 1])
                i = j + 1
            else:
                # no closing bracket: literal '['
                cur.append('[')
                i += 1
        elif c == '/':
            segs.append(''.join(cur))
            cur = []
            i += 1
        else:
            cur.append(c)
            i += 1
    segs.append(''.join(cur))
    return segs


def _match_segments(pat_segs, path_segs):
    if not pat_segs:
        return not path_segs
    if pat_segs[0] == '**':
        # ** matches zero or more whole segments
        for i in range(len(path_segs) + 1):
            if _match_segments(pat_segs[1:], path_segs[i:]):
                return True
        return False
    else:
        if not path_segs:
            return False
        if _match_segment(pat_segs[0], path_segs[0]):
            return _match_segments(pat_segs[1:], path_segs[1:])
        return False


def _match_segment(pattern: str, text: str) -> bool:
    """Match a single path segment (no '/' inside) against a segment pattern."""
    return _match_here(pattern, 0, text, 0)


def _match_here(pattern, pi, text, ti):
    while pi < len(pattern):
        c = pattern[pi]
        if c == '\\':
            # escaped literal
            pi += 1
            if pi >= len(pattern):
                return False
            if ti >= len(text) or text[ti] != pattern[pi]:
                return False
            pi += 1
            ti += 1
        elif c == '?':
            if ti >= len(text) or text[ti] == '/':
                return False
            pi += 1
            ti += 1
        elif c == '*':
            # collapse consecutive stars (non-** case)
            while pi < len(pattern) and pattern[pi] == '*':
                pi += 1
            if pi == len(pattern):
                # matches rest of segment (no '/')
                return '/' not in text[ti:]
            # try to match remaining pattern at every position
            for k in range(ti, len(text) + 1):
                if '/' in text[ti:k]:
                    break
                if _match_here(pattern, pi, text, k):
                    return True
            return False
        elif c == '[':
            matched, new_pi = _match_bracket(pattern, pi, text, ti)
            if not matched:
                return False
            pi = new_pi
            ti += 1
        else:
            if ti >= len(text) or text[ti] != c:
                return False
            pi += 1
            ti += 1
    return ti == len(text)


def _match_bracket(pattern, pi, text, ti):
    """Try to match a bracket expression at pattern[pi] against text[ti].

    Returns (matched, new_pi). If no valid closing bracket, treats '[' as literal.
    """
    n = len(pattern)
    j = pi + 1
    negate = False
    if j < n and pattern[j] == '!':
        negate = True
        j += 1

    # collect set items
    items = []
    first = True
    while j < n:
        if pattern[j] == ']' and not first:
            break
        if pattern[j] == ']' and first:
            # literal ']' right after '[' or '[!'
            items.append(']')
            first = False
            j += 1
            continue
        # handle range
        if (j + 2 < n and pattern[j + 1] == '-' and pattern[j + 2] != ']'
                and not (j + 2 == n)):
            # range a-z
            items.append(('range', pattern[j], pattern[j + 2]))
            j += 3
            first = False
        else:
            items.append(('char', pattern[j]))
            j += 1
            first = False

    if j >= n or pattern[j] != ']':
        # no closing bracket: literal '['
        if ti < len(text) and text[ti] == '[':
            return True, pi + 1
        return False, pi

    # j points at closing ']'
    if ti >= len(text) or text[ti] == '/':
        return False, j + 1

    ch = text[ti]
    found = False
    for item in items:
        if item[0] == 'char':
            if ch == item[1]:
                found = True
                break
        else:
            lo, hi = item[1], item[2]
            if lo <= ch <= hi:
                found = True
                break

    if negate:
        found = not found

    return found, j + 1

def glob_match(pattern: str, path: str) -> bool:
    segments = []
    i = 0
    n = len(pattern)
    current_tokens = []
    current_raw = []

    def flush_segment():
        nonlocal current_tokens, current_raw
        if len(current_raw) == 2 and current_raw[0] == '*' and current_raw[1] == '*':
            segments.append([('**',)])
        else:
            segments.append(current_tokens)
        current_tokens = []
        current_raw = []

    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("Pattern ends with unpaired backslash")
            lit = pattern[i+1]
            current_tokens.append(('lit', lit))
            current_raw.append(lit)
            i += 2
        elif c == '/':
            flush_segment()
            i += 1
        elif c == '?':
            current_tokens.append(('?',))
            current_raw.append('?')
            i += 1
        elif c == '*':
            current_tokens.append(('*',))
            current_raw.append('*')
            i += 1
        elif c == '[':
            j = i + 1
            negated = False
            if j < n and pattern[j] == '!':
                negated = True
                j += 1
            items = []
            if j < n and pattern[j] == ']':
                items.append(('lit', ']'))
                j += 1
            closed = False
            while j < n:
                if pattern[j] == ']':
                    closed = True
                    break
                if j + 2 < n and pattern[j+1] == '-' and pattern[j+2] != ']':
                    lo = pattern[j]
                    hi = pattern[j+2]
                    items.append(('range', lo, hi))
                    j += 3
                else:
                    items.append(('lit', pattern[j]))
                    j += 1
            if not closed:
                current_tokens.append(('lit', '['))
                current_raw.append('[')
                i += 1
            else:
                current_tokens.append(('class', negated, items))
                current_raw.append('[')
                i = j + 1
        else:
            current_tokens.append(('lit', c))
            current_raw.append(c)
            i += 1

    flush_segment()

    # Fix: an empty path is a single empty segment, not zero segments.
    path_segs = path.split('/')

    def match_segment(tokens, s):
        m = len(tokens)
        k = len(s)
        dp = [[False] * (k + 1) for _ in range(m + 1)]
        dp[m][k] = True
        for i in range(m - 1, -1, -1):
            for j in range(k, -1, -1):
                tok = tokens[i]
                if tok[0] == 'lit':
                    if j < k and s[j] == tok[1]:
                        dp[i][j] = dp[i+1][j+1]
                elif tok[0] == '?':
                    if j < k and s[j] != '/':
                        dp[i][j] = dp[i+1][j+1]
                elif tok[0] == '*':
                    if dp[i+1][j]:
                        dp[i][j] = True
                    elif j < k and s[j] != '/':
                        dp[i][j] = dp[i][j+1]
                elif tok[0] == 'class':
                    if j < k and s[j] != '/':
                        negated, items = tok[1], tok[2]
                        ch = s[j]
                        matched = False
                        for item in items:
                            if item[0] == 'lit':
                                if ch == item[1]:
                                    matched = True
                                    break
                            elif item[0] == 'range':
                                lo, hi = item[1], item[2]
                                if lo <= ch <= hi:
                                    matched = True
                                    break
                        if negated:
                            matched = not matched
                        if matched:
                            dp[i][j] = dp[i+1][j+1]
        return dp[0][0]

    P = len(segments)
    S = len(path_segs)
    dp = [[False] * (S + 1) for _ in range(P + 1)]
    dp[P][S] = True
    for i in range(P - 1, -1, -1):
        for j in range(S, -1, -1):
            seg = segments[i]
            if len(seg) == 1 and seg[0][0] == '**':
                if dp[i+1][j]:
                    dp[i][j] = True
                elif j < S:
                    dp[i][j] = dp[i][j+1]
            else:
                if j < S:
                    if match_segment(seg, path_segs[j]):
                        dp[i][j] = dp[i+1][j+1]
    return dp[0][0]

def glob_match(pattern: str, path: str) -> bool:
    tokens = []
    i = 0
    n = len(pattern)

    def parse_class(start):
        j = start + 1
        neg = False
        if j < n and pattern[j] == '!':
            neg = True
            j += 1
        items = []
        first = True
        while j < n:
            c = pattern[j]
            if c == ']' and not first:
                return ('class', neg, items), j + 1
            first = False
            if c == '\\':
                if j + 1 >= n:
                    items.append(('char', '\\'))
                    j += 1
                    continue
                items.append(('char', pattern[j + 1]))
                j += 2
                continue
            if (j + 2 < n and pattern[j + 1] == '-' and pattern[j + 2] != ']'
                    and c != '-'):
                items.append(('range', c, pattern[j + 2]))
                j += 3
                continue
            items.append(('char', c))
            j += 1
        return None, start

    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with unpaired backslash")
            tokens.append(('lit', pattern[i + 1]))
            i += 2
        elif c == '?':
            tokens.append(('any',))
            i += 1
        elif c == '*':
            if i + 1 < n and pattern[i + 1] == '*':
                before_ok = (i == 0) or (pattern[i - 1] == '/')
                after_idx = i + 2
                after_ok = (after_idx == n) or (pattern[after_idx] == '/')
                if before_ok and after_ok:
                    tokens.append(('globstar',))
                    i += 2
                    if i < n and pattern[i] == '/':
                        i += 1
                    continue
            tokens.append(('star',))
            i += 1
        elif c == '[':
            cls, new_i = parse_class(i)
            if cls is None:
                tokens.append(('lit', '['))
                i += 1
            else:
                tokens.append(cls)
                i = new_i
        else:
            tokens.append(('lit', c))
            i += 1

    path_segs = path.split('/') if path != '' else []

    def match_segment(toks, seg):
        m = len(toks)
        k = len(seg)
        dp = [[False] * (k + 1) for _ in range(m + 1)]
        dp[m][k] = True
        for a in range(m, -1, -1):
            for b in range(k, -1, -1):
                if a == m:
                    continue
                tok = toks[a]
                if tok[0] == 'star':
                    res = dp[a + 1][b]
                    if not res and b < k:
                        res = dp[a][b + 1]
                    dp[a][b] = res
                elif b >= k:
                    dp[a][b] = False
                else:
                    ch = seg[b]
                    if tok[0] == 'lit':
                        dp[a][b] = (ch == tok[1]) and dp[a + 1][b + 1]
                    elif tok[0] == 'any':
                        dp[a][b] = (ch != '/') and dp[a + 1][b + 1]
                    elif tok[0] == 'class':
                        neg = tok[1]
                        items = tok[2]
                        matched = False
                        for it in items:
                            if it[0] == 'char':
                                if ch == it[1]:
                                    matched = True
                                    break
                            else:
                                lo, hi = it[1], it[2]
                                if lo <= ch <= hi:
                                    matched = True
                                    break
                        if neg:
                            matched = not matched
                        if ch == '/':
                            matched = False
                        dp[a][b] = matched and dp[a + 1][b + 1]
                    else:
                        dp[a][b] = False
        return dp[0][0]

    groups = []
    cur = []
    for tok in tokens:
        if tok[0] == 'globstar':
            if cur:
                groups.append(('seg', cur))
                cur = []
            groups.append(('gs', None))
        else:
            cur.append(tok)
    if cur:
        groups.append(('seg', cur))

    if not groups:
        return path == ''

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def rec(gi, si):
        if gi == len(groups):
            return si == len(path_segs)
        kind, toks = groups[gi]
        if kind == 'gs':
            for k in range(si, len(path_segs) + 1):
                if rec(gi + 1, k):
                    return True
            return False
        else:
            if si >= len(path_segs):
                return False
            if not match_segment(toks, path_segs[si]):
                return False
            return rec(gi + 1, si + 1)

    return rec(0, 0)

from typing import List, Tuple


def glob_match(pattern: str, path: str) -> bool:
    # Reject a pattern ending with an unpaired backslash.
    if pattern:
        cnt = 0
        i = len(pattern) - 1
        while i >= 0 and pattern[i] == '\\':
            cnt += 1
            i -= 1
        if cnt % 2 == 1:
            raise ValueError("Pattern ends with unpaired backslash")

    def split_pattern(p: str) -> List[str]:
        segments = []
        current = []
        i = 0
        while i < len(p):
            if p[i] == '\\':
                if i + 1 < len(p):
                    current.append(p[i])
                    current.append(p[i + 1])
                    i += 2
                else:
                    raise ValueError("Pattern ends with unpaired backslash")
            elif p[i] == '/':
                segments.append(''.join(current))
                current = []
                i += 1
            else:
                current.append(p[i])
                i += 1
        segments.append(''.join(current))
        return segments

    P = split_pattern(pattern)
    # An empty path is a single empty segment, not zero segments.
    S = path.split('/')

    def parse_segment(pat: str) -> List[Tuple]:
        tokens = []
        i = 0
        while i < len(pat):
            c = pat[i]
            if c == '\\':
                if i + 1 < len(pat):
                    tokens.append(('lit', pat[i + 1]))
                    i += 2
                else:
                    raise ValueError("Pattern ends with unpaired backslash")
            elif c == '?':
                tokens.append(('?',))
                i += 1
            elif c == '*':
                while i < len(pat) and pat[i] == '*':
                    i += 1
                tokens.append(('*',))
            elif c == '[':
                # Determine whether there is a valid closing ']'.
                j = i + 1
                if j < len(pat) and pat[j] == '!':
                    j += 1
                # A ']' right after '[' or '[!' is a literal.
                if j < len(pat) and pat[j] == ']':
                    j += 1
                # Scan for the closing ']'.
                while j < len(pat) and pat[j] != ']':
                    j += 1
                if j >= len(pat):
                    # No closing ']': '[' is a literal.
                    tokens.append(('lit', '['))
                    i += 1
                else:
                    content = pat[i + 1:j]
                    negated = False
                    if content.startswith('!'):
                        negated = True
                        content = content[1:]
                    ranges = []
                    if content.startswith(']'):
                        ranges.append((']', ']'))
                        content = content[1:]
                    k = 0
                    while k < len(content):
                        if k + 2 < len(content) and content[k + 1] == '-':
                            ranges.append((content[k], content[k + 2]))
                            k += 3
                        else:
                            ranges.append((content[k], content[k]))
                            k += 1
                    tokens.append(('class', ranges, negated))
                    i = j + 1
            else:
                tokens.append(('lit', c))
                i += 1
        return tokens

    def match_segment(pat: str, s: str) -> bool:
        tokens = parse_segment(pat)
        n = len(tokens)
        m = len(s)
        dp = [[False] * (m + 1) for _ in range(n + 1)]
        dp[n][m] = True
        for i in range(n - 1, -1, -1):
            for j in range(m, -1, -1):
                tok = tokens[i]
                if tok[0] == 'lit':
                    if j < m and s[j] == tok[1]:
                        dp[i][j] = dp[i + 1][j + 1]
                elif tok[0] == '?':
                    if j < m and s[j] != '/':
                        dp[i][j] = dp[i + 1][j + 1]
                elif tok[0] == '*':
                    dp[i][j] = dp[i + 1][j] or (j < m and s[j] != '/' and dp[i][j + 1])
                elif tok[0] == 'class':
                    _, ranges, negated = tok
                    if j < m and s[j] != '/':
                        c = s[j]
                        in_set = any(start <= c <= end for start, end in ranges)
                        if negated:
                            in_set = not in_set
                        if in_set:
                            dp[i][j] = dp[i + 1][j + 1]
        return dp[0][0]

    n = len(P)
    m = len(S)
    dp = [[False] * (m + 1) for _ in range(n + 1)]
    dp[n][m] = True
    for i in range(n - 1, -1, -1):
        for j in range(m, -1, -1):
            if P[i] == '**':
                dp[i][j] = dp[i + 1][j] or (j < m and dp[i][j + 1])
            else:
                if j < m and match_segment(P[i], S[j]):
                    dp[i][j] = dp[i + 1][j + 1]
    return dp[0][0]

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("wrong number of fields")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    def parse_field(field, min_val, max_val, is_dow=False):
        if not field:
            raise ValueError("empty field")
        items = field.split(',')
        if not items:
            raise ValueError("empty field")
        values = set()
        for item in items:
            if not item:
                raise ValueError("empty item")
            if item == '*':
                values.update(range(min_val, max_val + 1))
            elif '/' in item:
                parts = item.split('/')
                if len(parts) != 2:
                    raise ValueError("invalid step syntax")
                base, step_str = parts
                if not step_str.isdigit():
                    raise ValueError("invalid step")
                step = int(step_str)
                if step < 1:
                    raise ValueError("step must be >= 1")
                if base == '*':
                    start, end = min_val, max_val
                elif '-' in base:
                    range_parts = base.split('-')
                    if len(range_parts) != 2:
                        raise ValueError("invalid range")
                    a_str, b_str = range_parts
                    if not a_str.isdigit() or not b_str.isdigit():
                        raise ValueError("invalid range values")
                    a, b = int(a_str), int(b_str)
                    if a > b:
                        raise ValueError("A > B")
                    if a < min_val or b > max_val:
                        raise ValueError("value out of range")
                    start, end = a, b
                else:
                    if not base.isdigit():
                        raise ValueError("invalid base")
                    start = int(base)
                    if start < min_val or start > max_val:
                        raise ValueError("value out of range")
                    end = max_val
                for v in range(start, end + 1, step):
                    values.add(v)
            elif '-' in item:
                parts = item.split('-')
                if len(parts) != 2:
                    raise ValueError("invalid range")
                a_str, b_str = parts
                if not a_str.isdigit() or not b_str.isdigit():
                    raise ValueError("invalid range values")
                a, b = int(a_str), int(b_str)
                if a > b:
                    raise ValueError("A > B")
                if a < min_val or b > max_val:
                    raise ValueError("value out of range")
                values.update(range(a, b + 1))
            else:
                if not item.isdigit():
                    raise ValueError("invalid value")
                v = int(item)
                if v < min_val or v > max_val:
                    raise ValueError("value out of range")
                values.add(v)
        if is_dow:
            if 7 in values:
                values.add(0)
            values.discard(7)
        return values

    minutes = parse_field(minute_field, 0, 59)
    hours = parse_field(hour_field, 0, 23)
    doms = parse_field(dom_field, 1, 31)
    months = parse_field(month_field, 1, 12)
    dows = parse_field(dow_field, 0, 7, is_dow=True)

    dom_starts_star = dom_field.startswith('*')
    dow_starts_star = dow_field.startswith('*')

    try:
        after_dt = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("invalid after format")

    start = after_dt + timedelta(minutes=1)
    end_limit = after_dt + timedelta(days=8 * 365)

    current = start
    while current <= end_limit:
        if current.month not in months:
            if current.month == 12:
                current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
            continue

        if current.hour not in hours:
            next_hour = current.hour + 1
            if next_hour > 23:
                current = current.replace(day=current.day + 1, hour=0, minute=0)
            else:
                current = current.replace(hour=next_hour, minute=0)
            continue

        if current.minute not in minutes:
            next_min = current.minute + 1
            if next_min > 59:
                current = current.replace(hour=current.hour + 1, minute=0)
            else:
                current = current.replace(minute=next_min)
            continue

        dom_match = current.day in doms
        dow_match = current.weekday() in dows

        if dom_starts_star and dow_starts_star:
            day_ok = dom_match and dow_match
        elif dom_starts_star:
            day_ok = dom_match
        elif dow_starts_star:
            day_ok = dow_match
        else:
            day_ok = dom_match or dow_match

        if day_ok:
            return current.strftime("%Y-%m-%dT%H:%M")

        current = current.replace(hour=0, minute=0) + timedelta(days=1)

    raise ValueError("no matching time within 8 years")

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("wrong number of fields")

    minute_f, hour_f, dom_f, month_f, dow_f = fields

    def parse_field(field, lo, hi, is_dow=False):
        if not field:
            raise ValueError("empty field")
        items = field.split(',')
        if not items:
            raise ValueError("empty field")
        values = set()
        for item in items:
            if not item:
                raise ValueError("empty item")
            if item == '*':
                values.update(range(lo, hi + 1))
            elif '/' in item:
                parts = item.split('/')
                if len(parts) != 2:
                    raise ValueError("bad step")
                base, step_str = parts
                if not step_str.isdigit():
                    raise ValueError("bad step")
                step = int(step_str)
                if step < 1:
                    raise ValueError("step must be >= 1")
                if base == '*':
                    start, end = lo, hi
                elif '-' in base:
                    bparts = base.split('-')
                    if len(bparts) != 2:
                        raise ValueError("bad range")
                    if not bparts[0].isdigit() or not bparts[1].isdigit():
                        raise ValueError("bad range")
                    start, end = int(bparts[0]), int(bparts[1])
                    if start > end:
                        raise ValueError("A > B")
                    if start < lo or end > hi:
                        raise ValueError("out of range")
                else:
                    if not base.isdigit():
                        raise ValueError("bad base")
                    start = int(base)
                    if start < lo or start > hi:
                        raise ValueError("out of range")
                    end = hi
                for v in range(start, end + 1, step):
                    values.add(v)
            elif '-' in item:
                parts = item.split('-')
                if len(parts) != 2:
                    raise ValueError("bad range")
                if not parts[0].isdigit() or not parts[1].isdigit():
                    raise ValueError("bad range")
                a, b = int(parts[0]), int(parts[1])
                if a > b:
                    raise ValueError("A > B")
                if a < lo or b > hi:
                    raise ValueError("out of range")
                values.update(range(a, b + 1))
            else:
                if not item.isdigit():
                    raise ValueError("bad value")
                v = int(item)
                if v < lo or v > hi:
                    raise ValueError("out of range")
                values.add(v)
        if is_dow:
            if 7 in values:
                values.discard(7)
                values.add(0)
        return values

    minutes = parse_field(minute_f, 0, 59)
    hours = parse_field(hour_f, 0, 23)
    doms = parse_field(dom_f, 1, 31)
    months = parse_field(month_f, 1, 12)
    dows = parse_field(dow_f, 0, 7, is_dow=True)

    dom_star = dom_f.startswith('*')
    dow_star = dow_f.startswith('*')

    try:
        dt = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad after format")

    start = dt + timedelta(minutes=1)
    limit = dt + timedelta(days=8 * 366)

    cur = start
    while cur <= limit:
        if cur.month not in months:
            if cur.month == 12:
                cur = cur.replace(year=cur.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                cur = cur.replace(month=cur.month + 1, day=1, hour=0, minute=0)
            continue
        if cur.day not in doms and cur.weekday() not in dows:
            cur = cur.replace(hour=0, minute=0) + timedelta(days=1)
            continue
        if not dom_star and not dow_star:
            day_ok = (cur.day in doms) or (cur.weekday() in dows)
        else:
            day_ok = (cur.day in doms) and (cur.weekday() in dows)
        if not day_ok:
            cur = cur.replace(hour=0, minute=0) + timedelta(days=1)
            continue
        if cur.hour not in hours:
            cur = cur.replace(minute=0) + timedelta(hours=1)
            continue
        if cur.minute not in minutes:
            cur = cur.replace(second=0, microsecond=0) + timedelta(minutes=1)
            continue
        return cur.strftime("%Y-%m-%dT%H:%M")

    raise ValueError("no matching time within 8 years")

