        values = set()
        for item in field.split(','):
            if item == '*':
                values.update(range(lo, hi + 1))
            elif '/' in item:
                base, step_str = item.split('/', 1)
                if not step_str.isdigit():
                    raise ValueError("bad step")
                step = int(step_str)
                if step < 1:
                    raise ValueError("step must be >= 1")
                if base == '*':
                    start, end = lo, hi
                elif '-' in base:
                    parts = base.split('-')
                    if len(parts) != 2:
                        raise ValueError("bad range")
                    if not parts[0].isdigit() or not parts[1].isdigit():
                        raise ValueError("bad range")
                    start, end = int(parts[0]), int(parts[1])
                    if start > end:
                        raise ValueError("A > B")
                else:
                    if not base.isdigit():
                        raise ValueError("bad base")
                    start = int(base)
                    end = hi
                if start < lo or end > hi:
                    raise ValueError("out of range")
                values.update(range(start, end + 1, step))
            elif '-' in item:
                parts = item.split('-')
                if len(parts) != 2:
                    raise ValueError("bad range")
                if not parts[0].isdigit() or not parts[1].isdigit():
                    raise ValueError("bad range")
                a, b = int(parts[0]), int(parts[1])
                if a > b:
                    raise ValueError("A > B")
                if a < lo or b > hi:
                    raise ValueError("out of range")
                values.update(range(a, b + 1))
            else:
                if not item.isdigit():
                    raise ValueError("bad value")
                v = int(item)
                if v < lo or v > hi:
                    raise ValueError("out of range")
                values.add(v)
        if is_dow:
            if 7 in values:
                values.discard(7)
                values.add(0)
        return values

    minutes = parse_field(fields[0], 0, 59)
    hours = parse_field(fields[1], 0, 23)
    doms = parse_field(fields[2], 1, 31)
    months = parse_field(fields[3], 1, 12)
    dows = parse_field(fields[4], 0, 7, is_dow=True)

    dom_star = fields[2].startswith('*')
    dow_star = fields[4].startswith('*')

    def day_matches(dt):
        dom_ok = dt.day in doms
        dow_ok = dt.weekday() in dows  # Monday=0, Sunday=6
        # convert cron dow (0=Sunday) to python weekday
        cron_dow = (dt.weekday() + 1) % 7
        dow_ok = cron_dow in dows
        if not dom_star and not dow_star:
            return dom_ok or dow_ok
        else:
            return dom_ok and dow_ok

    try:
        start = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad after format")

    # start from next minute
    current = start + timedelta(minutes=1)
    # truncate seconds
    current = current.replace(second=0, microsecond=0)

    limit = start + timedelta(days=8*365 + 2)  # 8 years plus leap days

    while current <= limit:
        if current.month not in months:
            # jump to first day of next month
            if current.month == 12:
                current = current.replace(year=current.year+1, month=1, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=current.month+1, day=1, hour=0, minute=0)
            continue
        if not day_matches(current):
            current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue
        if current.hour not in hours:
            current = (current + timedelta(hours=1)).replace(minute=0)
            continue
        if current.minute not in minutes:
            current = current + timedelta(minutes=1)
            continue
        return current.strftime("%Y-%m-%dT%H:%M")

    raise ValueError("no matching time found")

