                    raise ValueError("bad value")
                v = int(item)
                if v < lo or v > hi:
                    raise ValueError("out of range")
                values.add(v)
        if is_dow:
            if 7 in values:
                values.discard(7)
                values.add(0)
        return values

    minutes = parse_field(fields[0], 0, 59)
    hours = parse_field(fields[1], 0, 23)
    doms = parse_field(fields[2], 1, 31)
    months = parse_field(fields[3], 1, 12)
    dows = parse_field(fields[4], 0, 7, is_dow=True)

    dom_star = fields[2].startswith('*')
    dow_star = fields[4].startswith('*')

    try:
        start = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad after format")

    limit = start + timedelta(days=8 * 366)
    current = start + timedelta(minutes=1)
    current = current.replace(second=0, microsecond=0)

    while current <= limit:
        if current.month not in months:
            if current.month == 12:
                current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
            continue
        if current.day not in doms and current.weekday() not in dows:
            if dom_star or dow_star:
                current = current.replace(hour=0, minute=0) + timedelta(days=1)
                continue
        if not dom_star and not dow_star:
            if current.day not in doms and (current.weekday() + 1) % 7 not in dows:
                current = current.replace(hour=0, minute=0) + timedelta(days=1)
                continue
        else:
            if current.day not in doms or (current.weekday() + 1) % 7 not in dows:
                current = current.replace(hour=0, minute=0) + timedelta(days=1)
                continue
        if current.hour not in hours:
            current = current.replace(minute=0) + timedelta(hours=1)
            continue
        if current.minute not in minutes:
            current = current.replace(second=0, microsecond=0) + timedelta(minutes=1)
            continue
        return current.strftime("%Y-%m-%dT%H:%M")

    raise ValueError("no matching time found within 8 years")

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    # Parse the expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Expression must have exactly 5 fields")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    # Parse each field into a set of allowed values
    def parse_field(field, min_val, max_val, is_dow=False):
        # Handle the special case for day of week: 0 and 7 both mean Sunday
        values = set()
        for item in field.split(','):
            if item == '*':
                values.update(range(min_val, max_val + 1))
            elif '/' in item:
                parts = item.split('/')
                if len(parts) != 2:
                    raise ValueError(f"Invalid step syntax: {item}")
                base, step_str = parts
                try:
                    step = int(step_str)
                except ValueError:
                    raise ValueError(f"Invalid step value: {step_str}")
                if step < 1:
                    raise ValueError(f"Step must be >= 1: {step}")

                if base == '*':
                    start, end = min_val, max_val
                elif '-' in base:
                    range_parts = base.split('-')
                    if len(range_parts) != 2:
                        raise ValueError(f"Invalid range: {base}")
                    try:
                        start = int(range_parts[0])
                        end = int(range_parts[1])
                    except ValueError:
                        raise ValueError(f"Invalid range values: {base}")
                    if start > end:
                        raise ValueError(f"Range start > end: {base}")
                    if start < min_val or end > max_val:
                        raise ValueError(f"Range out of bounds: {base}")
                else:
                    try:
                        start = int(base)
                    except ValueError:
                        raise ValueError(f"Invalid base value: {base}")
                    if start < min_val or start > max_val:
                        raise ValueError(f"Value out of range: {start}")
                    end = max_val

                for v in range(start, end + 1, step):
                    values.add(v)
            elif '-' in item:
                range_parts = item.split('-')
                if len(range_parts) != 2:
                    raise ValueError(f"Invalid range: {item}")
                try:
                    start = int(range_parts[0])
                    end = int(range_parts[1])
                except ValueError:
                    raise ValueError(f"Invalid range values: {item}")
                if start > end:
                    raise ValueError(f"Range start > end: {item}")
                if start < min_val or end > max_val:
                    raise ValueError(f"Range out of bounds: {item}")
                values.update(range(start, end + 1))
            else:
                try:
                    val = int(item)
                except ValueError:
                    raise ValueError(f"Invalid value: {item}")
                if val < min_val or val > max_val:
                    raise ValueError(f"Value out of range: {val}")
                values.add(val)

        # For day of week, normalize 7 to 0
        if is_dow:
            if 7 in values:
                values.remove(7)
                values.add(0)

        return values

    minutes = parse_field(minute_field, 0, 59)
    hours = parse_field(hour_field, 0, 23)
    doms = parse_field(dom_field, 1, 31)
    months = parse_field(month_field, 1, 12)
    dows = parse_field(dow_field, 0, 7, is_dow=True)

    # Determine day matching logic
    dom_starts_with_star = dom_field.startswith('*')
    dow_starts_with_star = dow_field.startswith('*')

    # Parse the 'after' time
    try:
        after_dt = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError(f"Invalid 'after' time format: {after}")

    # Start from the next minute
    current = after_dt + timedelta(minutes=1)
    # Remove seconds if any (shouldn't be any)
    current = current.replace(second=0, microsecond=0)

    # Limit search to 8 years
    max_time = after_dt + timedelta(days=8*365 + 2)  # Add a couple days for leap years

    while current <= max_time:
        # Check month
        if current.month not in months:
            # Jump to first day of next month
            if current.month == 12:
                current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
            continue

        # Check day
        dom_match = current.day in doms
        dow_match = current.weekday() in dows  # weekday() returns 0=Monday, 6=Sunday
        # Convert to cron dow: 0=Sunday, 1=Monday, ..., 6=Saturday
        cron_dow = (current.weekday() + 1) % 7
        dow_match = cron_dow in dows

        if dom_starts_with_star and dow_starts_with_star:
            day_match = dom_match and dow_match
        elif dom_starts_with_star:
            day_match = dom_match
        elif dow_starts_with_star:
            day_match = dow_match
        else:
            day_match = dom_match or dow_match

        if not day_match:
            # Jump to next day
            current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        # Check hour
        if current.hour not in hours:
            # Jump to next hour
            current = (current + timedelta(hours=1)).replace(minute=0)
            continue

        # Check minute
        if current.minute not in minutes:
            # Jump to next minute
            current = current + timedelta(minutes=1)
            continue

        # Found a match
        return current.strftime("%Y-%m-%dT%H:%M")

    raise ValueError("No matching time found within 8 years")

