                if base == '*':
                    start, end = lo, hi
                elif '-' in base:
                    bparts = base.split('-')
                    if len(bparts) != 2:
                        raise ValueError("bad range")
                    a_s, b_s = bparts
                    if not a_s.isdigit() or not b_s.isdigit():
                        raise ValueError("bad range")
                    a, b = int(a_s), int(b_s)
                    if a > b:
                        raise ValueError("A > B")
                    if a < lo or b > hi:
