from datetime import datetime, timedelta

def _parse_field(field: str, lo: int, hi: int, name: str):
    """Parse a cron field into a sorted list of allowed values."""
    if not field:
        raise ValueError(f"empty {name} field")
    values = set()
    for item in field.split(','):
        if not item:
            raise ValueError(f"empty item in {name} field")
        step = 1
        if '/' in item:
            parts = item.split('/')
            if len(parts) != 2:
                raise ValueError(f"bad step in {name} field: {item}")
            base, step_s = parts
            if not step_s.isdigit():
                raise ValueError(f"bad step in {name} field: {item}")
            step = int(step_s)
            if step < 1:
                raise ValueError(f"step must be >= 1 in {name} field: {item}")
        else:
            base = item

        if base == '*':
            start, end = lo, hi
        elif '-' in base:
            parts = base.split('-')
            if len(parts) != 2:
                raise ValueError(f"bad range in {name} field: {item}")
            a_s, b_s = parts
            if not a_s.isdigit() or not b_s.isdigit():
                raise ValueError(f"bad range in {name} field: {item}")
            start, end = int(a_s), int(b_s)
            if start > end:
                raise ValueError(f"range start > end in {name} field: {item}")
            if start < lo or end > hi:
                raise ValueError(f"range out of bounds in {name} field: {item}")
        else:
            if not base.isdigit():
                raise ValueError(f"bad value in {name} field: {item}")
            start = end = int(base)
            if start < lo or start > hi:
                raise ValueError(f"value out of range in {name} field: {item}")

        if start < lo or end > hi:
            raise ValueError(f"value out of range in {name} field: {item}")

        for v in range(start, end + 1, step):
            values.add(v)

    if not values:
        raise ValueError(f"no values in {name} field")
    return sorted(values)


def _parse_expr(expr: str):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("expression must have exactly 5 fields")
    minute_f, hour_f, dom_f, month_f, dow_f = fields

    minutes = _parse_field(minute_f, 0, 59, "minute")
    hours = _parse_field(hour_f, 0, 23, "hour")
    doms = _parse_field(dom_f, 1, 31, "day of month")
    months = _parse_field(month_f, 1, 12, "month")
    dows = _parse_field(dow_f, 0, 7, "day of week")

    # Normalize Sunday: 0 and 7 both mean Sunday
    dow_set = set()
    for d in dows:
        dow_set.add(d % 7)
    dows = sorted(dow_set)

    dom_star = dom_f.startswith('*')
    dow_star = dow_f.startswith('*')

    return minutes, hours, doms, months, dows, dom_star, dow_star


def _days_in_month(year: int, month: int) -> int:
    if month == 2:
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            return 29
        return 28
    if month in (4, 6, 9, 11):
        return 30
    return 31


def _day_matches(dt: datetime, doms, months, dows, dom_star, dow_star) -> bool:
    if dt.month not in months:
        return False
    dom_ok = dt.day in doms
    # Python weekday: Monday=0 ... Sunday=6. Cron: Sunday=0, Monday=1...
    cron_dow = (dt.weekday() + 1) % 7
    dow_ok = cron_dow in dows

    if not dom_star and not dow_star:
        return dom_ok or dow_ok
    return dom_ok and dow_ok


def next_cron(expr: str, after: str) -> str:
    minutes, hours, doms, months, dows, dom_star, dow_star = _parse_expr(expr)

    try:
        start = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError(f"invalid 'after' time: {after}")

    # Start from the next minute strictly after 'after'
    current = start + timedelta(minutes=1)
    # Remove seconds just in case
    current = current.replace(second=0, microsecond=0)

    limit = start + timedelta(days=8 * 366)

    # Precompute sets for fast lookup
    minute_set = set(minutes)
    hour_set = set(hours)

    while current <= limit:
        if not _day_matches(current, doms, months, dows, dom_star, dow_star):
            # Skip to next day at 00:00
            current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        if current.hour not in hour_set:
            # Skip to next hour
            current = (current + timedelta(hours=1)).replace(minute=0)
            continue

        if current.minute not in minute_set:
            # Skip to next minute
            current = current + timedelta(minutes=1)
            continue

        return current.strftime("%Y-%m-%dT%H:%M")

    raise ValueError("no matching time found within 8 years")

