            for v in range(start, end + 1):
                values.add(v)

        else:
            try:
                v = int(item)
            except ValueError:
                raise ValueError("invalid value")
            if v < min_val or v > max_val:
                raise ValueError("value out of range")
            values.add(v)

    if not values:
        raise ValueError("no values in field")

    return values

