    hours = parse_field(hour_field, 0, 23)
    doms = parse_field(dom_field, 1, 31)
    months = parse_field(month_field, 1, 12)
    dows = parse_field(dow_field, 0, 7, is_dow=True)

    # Convert cron DOW (0=Sunday) to Python weekday (0=Monday)
    py_dows = set()
    for d in dows:
        # cron: 0=Sun,1=Mon,...,6=Sat
        # python: 0=Mon,...,6=Sun
        py_dows.add((d - 1) % 7)

    dom_star = dom_field.startswith('*')
    dow_star = dow_field.startswith('*')

    def day_matches(dt):
        dom_ok = dt.day in doms
        dow_ok = dt.weekday() in py_dows
        if not dom_star and not dow_star:
            return dom_ok or dow_ok
        else:
            return dom_ok and dow_ok

    try:
        start = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("invalid after format")

    current = start + timedelta(minutes=1)
    current = current.replace(second=0, microsecond=0)

    limit = start + timedelta(days=8 * 365 + 2)

    while current <= limit:
        if current.month not in months:
            if current.month == 12:
                current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
            continue
        if not day_matches(current):
            current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue
        if current.hour not in hours:
            current = (current + timedelta(hours=1)).replace(minute=0)
            continue
        if current.minute not in minutes:
            current = current + timedelta(minutes=1)
            continue
        return current.strftime("%Y-%m-%dT%H:%M")

    raise ValueError("no matching time found within 8 years")

