def next_cron(expr: str, after: str) -> str:
    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("wrong number of fields")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    def parse_field(field, min_val, max_val):
        starts_with_star = field.startswith('*')
        values = set()
        items = field.split(',')
        if not items or any(item == '' for item in items):
            raise ValueError("empty item")
        for item in items:
            if item == '*':
                values.update(range(min_val, max_val + 1))
            elif '/' in item:
                parts = item.split('/')
                if len(parts) != 2:
                    raise ValueError("bad step")
                base, step_str = parts
                try:
                    step = int(step_str)
                except ValueError:
                    raise ValueError("bad step")
                if step < 1:
                    raise ValueError("step must be >= 1")
                if base == '*':
                    start, end = min_val, max_val
                elif '-' in base:
                    range_parts = base.split('-')
                    if len(range_parts) != 2:
                        raise ValueError("bad range")
                    try:
                        start = int(range_parts[0])
                        end = int(range_parts[1])
                    except ValueError:
                        raise ValueError("bad range")
                    if start > end:
                        raise ValueError("A > B")
                    if start < min_val or end > max_val:
                        raise ValueError("out of range")
                else:
                    try:
                        start = int(base)
                    except ValueError:
                        raise ValueError("bad value")
                    if start < min_val or start > max_val:
                        raise ValueError("out of range")
                    end = max_val
                for v in range(start, end + 1, step):
                    values.add(v)
            elif '-' in item:
                parts = item.split('-')
                if len(parts) != 2:
                    raise ValueError("bad range")
                try:
                    start = int(parts[0])
                    end = int(parts[1])
                except ValueError:
                    raise ValueError("bad range")
                if start > end:
                    raise ValueError("A > B")
                if start < min_val or end > max_val:
                    raise ValueError("out of range")
                values.update(range(start, end + 1))
            else:
                try:
                    v = int(item)
                except ValueError:
                    raise ValueError("bad value")
                if v < min_val or v > max_val:
                    raise ValueError("out of range")
                values.add(v)
        return values, starts_with_star

    minutes, _ = parse_field(minute_field, 0, 59)
    hours, _ = parse_field(hour_field, 0, 23)
    doms, dom_star = parse_field(dom_field, 1, 31)
    months, _ = parse_field(month_field, 1, 12)
    dows, dow_star = parse_field(dow_field, 0, 7)

    # Normalize dow: 7 -> 0
    if 7 in dows:
        dows.add(0)
        dows.discard(7)

    try:
        dt = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad after format")

    dt = dt + timedelta(minutes=1)
    dt = dt.replace(second=0, microsecond=0)

    limit = dt + timedelta(days=8 * 366)

    while dt <= limit:
        if dt.month not in months:
            if dt.month == 12:
                dt = dt.replace(year=dt.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                dt = dt.replace(month=dt.month + 1, day=1, hour=0, minute=0)
            continue

        dom_match = dt.day in doms
        cron_dow = (dt.weekday() + 1) % 7
        dow_match = cron_dow in dows

        # Classic cron: if neither field starts with '*', OR them.
        # Otherwise, AND them.
        if not dom_star and not dow_star:
            day_ok = dom_match or dow_match
        else:
            day_ok = dom_match and dow_match

        if not day_ok:
            dt = (dt + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        if dt.hour not in hours:
            dt = (dt.replace(minute=0) + timedelta(hours=1))
            continue

        if dt.minute not in minutes:
            dt = dt + timedelta(minutes=1)
            continue

        return dt.strftime("%Y-%m-%dT%H:%M")

    raise ValueError("no matching time found within 8 years")

