            continue

        dom_match = current.day in doms
        cron_dow = (current.weekday() + 1) % 7
        dow_match = cron_dow in dows

        if dom_restricted and dow_restricted:
            day_match = dom_match or dow_match
        else:
            day_match = dom_match and dow_match

        if not day_match:
            current = (current + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        if current.hour not in hours:
            current = (current + timedelta(hours=1)).replace(minute=0)
            continue

        if current.minute not in minutes:
            current = current + timedelta(minutes=1)
            continue

        return current.strftime("%Y-%m-%dT%H:%M")

    raise ValueError("no matching time found within 8 years")

