    def parse_field(field, lo, hi, is_dow=False):
        if not field:
            raise ValueError("empty field")
        items = field.split(',')
        if not items:
            raise ValueError("empty field")
        values = set()
        for item in items:
            if item == '*':
                values.update(range(lo, hi + 1))
            elif '/' in item:
                parts = item.split('/')
                if len(parts) != 2:
                    raise ValueError("bad step")
                base, step_s = parts
                try:
                    step = int(step_s)
                except ValueError:
                    raise ValueError("bad step")
                if step < 1:
                    raise ValueError("step must be >= 1")
                if base == '*':
                    start, end = lo, hi
                elif '-' in base:
                    bparts = base.split('-')
                    if len(bparts) != 2:
                        raise ValueError("bad range")
                    try:
                        start = int(bparts[0])
                        end = int(bparts[1])
                    except ValueError:
                        raise ValueError("bad range")
                    if start > end:
                        raise ValueError("A > B")
                    if start < lo or end > hi:
                        raise ValueError("out of range")
                else:
                    try:
                        start = int(base)
                    except ValueError:
                        raise ValueError("bad value")
                    if start < lo or start > hi:
                        raise ValueError("out of range")
                    end = hi
                for v in range(start, end + 1, step):
                    values.add(v)
            elif '-' in item:
                parts = item.split('-')
                if len(parts) != 2:
                    raise ValueError("bad range")
                try:
                    a = int(parts[0])
                    b = int(parts[1])
                except ValueError:
                    raise ValueError("bad range")
                if a > b:
                    raise ValueError("A > B")
                if a < lo or b > hi:
                    raise ValueError("out of range")
                values.update(range(a, b + 1))
            else:
                try:
                    v = int(item)
                except ValueError:
                    raise ValueError("bad value")
                if v < lo or v > hi:
                    raise ValueError("out of range")
                values.add(v)
        if is_dow:
            if 7 in values:
                values.add(0)
            values = {v for v in values if 0 <= v <= 6}
        return values

    minutes = parse_field(minute_f, 0, 59)
    hours = parse_field(hour_f, 0, 23)
    doms = parse_field(dom_f, 1, 31)
    months = parse_field(month_f, 1, 12)
    dows = parse_field(dow_f, 0, 7, is_dow=True)

    dom_star = dom_f.startswith('*')
    dow_star = dow_f.startswith('*')

    try:
        start = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad after format")

    current = start + timedelta(minutes=1)
    limit = start + timedelta(days=8 * 366)

    while current <= limit:
        if current.month not in months:
            current = (current.replace(day=1, hour=0, minute=0) + timedelta(days=32)).replace(day=1)
            continue
        if current.hour not in hours:
            current = (current + timedelta(hours=1)).replace(minute=0)
            continue
        if current.minute not in minutes:
            current = current + timedelta(minutes=1)
            continue

        dom_match = current.day in doms
        # cron weekday: Sunday=0 ... Saturday=6
        cron_dow = (current.weekday() + 1) % 7
        dow_match = cron_dow in dows

        if not dom_star and not dow_star:
            day_ok = dom_match or dow_match
        else:
            day_ok = dom_match and dow_match

        if day_ok:
            return current.strftime("%Y-%m-%dT%H:%M")

        current = (current + timedelta(days=1)).replace(hour=0, minute=0)

    raise ValueError("no matching time found within 8 years")

