            elif '-' in item:
                parts = item.split('-')
                if len(parts) != 2:
                    raise ValueError("invalid range")
                if not parts[0].isdigit() or not parts[1].isdigit():
                    raise ValueError("invalid range")
                start = int(parts[0])
                end = int(parts[1])
                if start > end:
