                if start < min_val or end > max_val:
                    raise ValueError("out of range")
                values.update(range(start, end + 1))
            else:
                if not item.isdigit():
                    raise ValueError("invalid value")
                v = int(item)
                if v < min_val or v > max_val:
                    raise ValueError("out of range")
                values.add(v)
        if is_dow:
            if 7 in values:
                values.add(0)
                values.discard(7)
