def next_cron(expr: str, after: str) -> str:
    fields = expr.split(' ')
    if len(fields) != 5 or any(f == '' for f in fields):
        raise ValueError("wrong number of fields or empty field")
    minute_f, hour_f, dom_f, month_f, dow_f = fields

    def parse_field(field, lo, hi, is_dow=False):
        if not field:
            raise ValueError("empty field")
        items = field.split(',')
        if not items:
            raise ValueError("empty field")
        values = set()
        for item in items:
            if not item:
                raise ValueError("empty item")
            step = 1
            if '/' in item:
                parts = item.split('/')
                if len(parts) != 2:
                    raise ValueError("bad step")
                base, step_s = parts
                if not step_s.isdigit():
                    raise ValueError("bad step")
                step = int(step_s)
                if step < 1:
                    raise ValueError("step must be >= 1")
            else:
                base = item
            if base == '*':
                start, end = lo, hi
            elif '-' in base:
                parts = base.split('-')
                if len(parts) != 2:
                    raise ValueError("bad range")
                a_s, b_s = parts
                if not a_s.isdigit() or not b_s.isdigit():
                    raise ValueError("bad range")
                start, end = int(a_s), int(b_s)
                if start > end:
                    raise ValueError("A > B")
            else:
                if not base.isdigit():
                    raise ValueError("bad value")
                start = end = int(base)
            if start < lo or end > hi:
                raise ValueError("out of range")
            if is_dow:
                for v in range(start, end + 1, step):
                    values.add(v % 7)
            else:
                for v in range(start, end + 1, step):
                    values.add(v)
        return values

    minutes = parse_field(minute_f, 0, 59)
    hours = parse_field(hour_f, 0, 23)
    doms = parse_field(dom_f, 1, 31)
    months = parse_field(month_f, 1, 12)
    dows = parse_field(dow_f, 0, 7, is_dow=True)

    dom_star = dom_f.startswith('*')
    dow_star = dow_f.startswith('*')

    def day_matches(dt):
        dom_ok = dt.day in doms
        dow_ok = (dt.weekday() + 1) % 7 in dows
        if not dom_star and not dow_star:
            return dom_ok or dow_ok
        else:
            return dom_ok and dow_ok

    try:
        start = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad after format")

    current = start + timedelta(minutes=1)
    end_date = (start + timedelta(days=8*366)).date()

    d = current.date()
    while d <= end_date:
        if d.month not in months:
