from fractions import Fraction
import re

def evaluate(expr: str) -> str:
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c!r}")
    if not tokens:
        raise ValueError("Empty expression")

    # Parser
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else (None, None)

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        # expr := term (('+' | '-') term)*
        left = parse_term()
        while True:
            t = peek()[0]
            if t in ('+', '-'):
                op = advance()[0]
                right = parse_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_term():
        # term := factor (('*' | '/') factor)*
        left = parse_factor()
        while True:
            t = peek()[0]
            if t in ('*', '/'):
                op = advance()[0]
                right = parse_factor()
                if op == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("Division by zero")
                    left = left / right
            else:
                break
        return left

    def parse_factor():
        # factor := ('+' | '-')* power
        sign = 1
        while True:
            t = peek()[0]
            if t == '+':
                advance()
            elif t == '-':
                advance()
                sign = -sign
            else:
                break
        val = parse_power()
        return sign * val

    def parse_power():
        # power := atom ('^' factor)?  (right-associative)
        base = parse_atom()
        if peek()[0] == '^':
            advance()
            exp = parse_factor()  # exponent may have unary sign
            if exp.denominator != 1:
                raise ValueError("Exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("0 raised to negative power")
            if e == 0:
                return Fraction(1)
            if e < 0:
                if base == 0:
                    raise ZeroDivisionError("0 raised to negative power")
                return Fraction(1) / (base ** (-e))
            return base ** e
        return base

    def parse_atom():
        t = peek()[0]
        if t == '(':
            advance()
            val = parse_expr()
            if peek()[0] != ')':
                raise ValueError("Unbalanced parentheses")
            advance()
            return val
        elif t == 'num':
            return Fraction(advance()[1])
        else:
            raise ValueError("Expected operand")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected token after expression")

    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"

from fractions import Fraction

def evaluate(expr: str) -> str:
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c!r}")
    tokens.append(('end', None))

    pos = 0

    def peek():
        return tokens[pos]

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def expect(kind):
        tok = peek()
        if tok[0] != kind:
            raise ValueError(f"Expected {kind}, got {tok}")
        return advance()

    # Grammar:
    # expr    := term (('+' | '-') term)*
    # term    := factor (('*' | '/') factor)*
    # factor  := ('+' | '-')* power
    # power   := atom ('^' factor)?   -- right-assoc, exponent may have unary
    # atom    := number | '(' expr ')'

    def parse_expr():
        val = parse_term()
        while peek()[0] in ('+', '-'):
            op = advance()[0]
            rhs = parse_term()
            if op == '+':
                val = val + rhs
            else:
                val = val - rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek()[0] in ('*', '/'):
            op = advance()[0]
            rhs = parse_factor()
            if op == '*':
                val = val * rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                val = val / rhs
        return val

    def parse_factor():
        # unary signs
        sign = 1
        while peek()[0] in ('+', '-'):
            if advance()[0] == '-':
                sign = -sign
        val = parse_power()
        return sign * val

    def parse_power():
        base = parse_atom()
        if peek()[0] == '^':
            advance()
            exp = parse_factor()  # exponent may have unary signs
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("0 raised to negative power")
            if e == 0:
                return Fraction(1)
            return base ** e
        return base

    def parse_atom():
        tok = peek()
        if tok[0] == 'num':
            advance()
            return Fraction(tok[1])
        elif tok[0] == '(':
            advance()
            val = parse_expr()
            expect(')')
            return val
        else:
            raise ValueError(f"Unexpected token: {tok}")

    if tokens[0][0] == 'end':
        raise ValueError("empty expression")

    result = parse_expr()
    if peek()[0] != 'end':
        raise ValueError(f"Unexpected token after expression: {peek()}")

    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"

