    def parse_term():
        val = parse_factor()
        while peek()[0] in ('*', '/'):
            op = advance()[0]
            rhs = parse_factor()
            if op == '*':
                val = val * rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                val = val / rhs
