def evaluate(expr: str) -> str:
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c!r}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        # expr := term (('+' | '-') term)*
        left = parse_term()
        while True:
            tok = peek()
            if tok and tok[0] in ('+', '-'):
                op = consume()[0]
                right = parse_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_term():
        # term := factor (('*' | '/') factor)*
        left = parse_factor()
        while True:
            tok = peek()
            if tok and tok[0] in ('*', '/'):
                op = consume()[0]
                right = parse_factor()
                if op == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    left = left / right
            else:
                break
        return left

    def parse_factor():
        # factor := ('+' | '-')* power
        sign = 1
        while True:
            tok = peek()
            if tok and tok[0] == '+':
                consume()
            elif tok and tok[0] == '-':
                consume()
                sign = -sign
            else:
                break
        val = parse_power()
        return sign * val

    def parse_power():
        # power := atom ('^' factor)?   (right-associative, exponent may have unary sign)
        base = parse_atom()
        tok = peek()
        if tok and tok[0] == '^':
            consume()
            exp = parse_factor()  # exponent can have unary signs
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("0 raised to negative power")
            if e == 0:
                return Fraction(1)
            if e < 0:
                if base == 0:
                    raise ZeroDivisionError("0 raised to negative power")
                return Fraction(1) / (base ** (-e))
            return base ** e
        return base

    def parse_atom():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok[0] == 'num':
            consume()
            return Fraction(tok[1])
        elif tok[0] == '(':
            consume()
            val = parse_expr()
            tok2 = peek()
            if tok2 is None or tok2[0] != ')':
                raise ValueError("Unbalanced parentheses")
            consume()
            return val
        else:
            raise ValueError(f"Unexpected token: {tok}")

