class Parser:
    def __init__(self, s):
        self.s = s
        self.i = 0
        self.n = len(s)

    def error(self):
        raise ValueError("syntax error")

    def skip_ws(self):
        while self.i < self.n and self.s[self.i] == ' ':
            self.i += 1

    def peek(self):
        self.skip_ws()
        if self.i < self.n:
            return self.s[self.i]
        return None

    def parse(self):
        self.skip_ws()
        if self.i >= self.n:
            self.error()
        val = self.parse_expr()
        self.skip_ws()
        if self.i != self.n:
            self.error()
        return val

    def parse_expr(self):
        val = self.parse_term()
        while True:
            c = self.peek()
            if c == '+':
                self.i += 1
                rhs = self.parse_term()
                val = val + rhs
            elif c == '-':
                self.i += 1
                rhs = self.parse_term()
                val = val - rhs
            else:
                break
        return val

    def parse_term(self):
        val = self.parse_unary()
        while True:
            c = self.peek()
            if c == '*':
                self.i += 1
                rhs = self.parse_unary()
                val = val * rhs
            elif c == '/':
                self.i += 1
                rhs = self.parse_unary()
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                val = val / rhs
            else:
                break
        return val

    def parse_unary(self):
        c = self.peek()
        if c == '+':
            self.i += 1
            return self.parse_unary()
        elif c == '-':
            self.i += 1
            return -self.parse_unary()
        else:
            return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        c = self.peek()
        if c == '^':
            self.i += 1
            exp = self.parse_unary()
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("zero to negative power")
            if e == 0:
                return Fraction(1)
            return base ** e
        return base

    def parse_atom(self):
        c = self.peek()
        if c is None:
            self.error()
        if c == '(':
            self.i += 1
            val = self.parse_expr()
            if self.peek() != ')':
                self.error()
            self.i += 1
            return val
        if c.isdigit():
            start = self.i
            while self.i < self.n and self.s[self.i].isdigit():
                self.i += 1
            return Fraction(int(self.s[start:self.i]))
        self.error()


def evaluate(expr: str) -> str:
    p = Parser(expr)
    result = p.parse()
    if result.denominator == 1:
        return str(result.numerator)
    return f"{result.numerator}/{result.denominator}"

from fractions import Fraction

def evaluate(expr: str) -> str:
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c!r}")
    tokens.append(('end', None))

    pos = 0

    def peek():
        return tokens[pos][0]

    def consume(expected=None):
        nonlocal pos
        tok = tokens[pos]
        if expected is not None and tok[0] != expected:
            raise ValueError(f"Expected {expected}, got {tok[0]}")
        pos += 1
        return tok

    # Grammar:
    # expr    := term (('+' | '-') term)*
    # term    := factor (('*' | '/') factor)*
    # factor  := ('+' | '-')* power
    # power   := atom ('^' factor)?    # right-assoc, exponent may have unary sign
    # atom    := number | '(' expr ')'

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = consume()[0]
            rhs = parse_term()
            if op == '+':
                val = val + rhs
            else:
                val = val - rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek() in ('*', '/'):
            op = consume()[0]
            rhs = parse_factor()
            if op == '*':
                val = val * rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                val = val / rhs
        return val

    def parse_factor():
        sign = 1
        while peek() in ('+', '-'):
            if consume()[0] == '-':
                sign = -sign
        val = parse_power()
        return sign * val

    def parse_power():
        base = parse_atom()
        if peek() == '^':
            consume('^')
            exp = parse_factor()  # exponent can have unary sign, right-assoc
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("0 raised to negative power")
            return base ** e
        return base

    def parse_atom():
        tok = tokens[pos]
        if tok[0] == 'num':
            consume()
            return Fraction(tok[1])
        elif tok[0] == '(':
            consume('(')
            val = parse_expr()
            if peek() != ')':
                raise ValueError("Unbalanced parentheses")
            consume(')')
            return val
        else:
            raise ValueError(f"Unexpected token: {tok[0]}")

    if tokens[0][0] == 'end':
        raise ValueError("Empty expression")

    result = parse_expr()
    if peek() != 'end':
        raise ValueError("Unexpected token after expression")

    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"

