def evaluate(expr: str) -> str:
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/^()':
            tokens.append((c, c))
            i += 1
            continue
        raise ValueError(f"Invalid character: {c!r}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        # expr := term (('+' | '-') term)*
        left = parse_term()
        while True:
            tok = peek()
            if tok and tok[0] in ('+', '-'):
                op = consume()[0]
                right = parse_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_term():
        # term := unary (('*' | '/') unary)*
        left = parse_unary()
        while True:
            tok = peek()
            if tok and tok[0] in ('*', '/'):
                op = consume()[0]
                right = parse_unary()
                if op == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    left = left / right
            else:
                break
        return left

    def parse_unary():
        # unary := ('+' | '-')* power
        tok = peek()
        if tok and tok[0] in ('+', '-'):
            op = consume()[0]
            operand = parse_unary()
            if op == '-':
                return -operand
            return operand
        return parse_power()

    def parse_power():
        # power := atom ('^' unary)?
        base = parse_atom()
        tok = peek()
        if tok and tok[0] == '^':
            consume()
            exponent = parse_unary()
            if exponent.denominator != 1:
                raise ValueError("Exponent must be an integer")
            exp = exponent.numerator
            if base == 0 and exp < 0:
                raise ZeroDivisionError("0 raised to negative power")
            return base ** exp
        return base

    def parse_atom():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok[0] == 'num':
            consume()
            return Fraction(tok[1])
        if tok[0] == '(':
            consume()
            val = parse_expr()
            tok2 = peek()
            if tok2 is None or tok2[0] != ')':
                raise ValueError("Unbalanced parentheses")
            consume()
            return val
        raise ValueError(f"Unexpected token: {tok}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected token after expression")

    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"

from fractions import Fraction

class Parser:
    def __init__(self, s: str):
        self.s = s
        self.i = 0
        self.n = len(s)

    def skip_spaces(self):
        while self.i < self.n and self.s[self.i] == ' ':
            self.i += 1

    def peek(self):
        self.skip_spaces()
        if self.i < self.n:
            return self.s[self.i]
        return None

    def consume(self):
        self.skip_spaces()
        if self.i < self.n:
            c = self.s[self.i]
            self.i += 1
            return c
        return None

    def parse(self):
        self.skip_spaces()
        if self.i >= self.n:
            raise ValueError("empty expression")
        val = self.parse_expr()
        self.skip_spaces()
        if self.i < self.n:
            raise ValueError("unexpected character")
        return val

    def parse_expr(self):
        left = self.parse_term()
        while True:
            c = self.peek()
            if c == '+' or c == '-':
                op = self.consume()
                right = self.parse_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_term(self):
        left = self.parse_unary()
        while True:
            c = self.peek()
            if c == '*' or c == '/':
                op = self.consume()
                right = self.parse_unary()
                if op == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    left = left / right
            else:
                break
        return left

    def parse_unary(self):
        c = self.peek()
        if c == '+' or c == '-':
            op = self.consume()
            val = self.parse_unary()
            if op == '-':
                return -val
            return val
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        c = self.peek()
        if c == '^':
            self.consume()
            exp = self.parse_unary()
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("zero to negative power")
            if base == 0 and e == 0:
                return Fraction(1)
            return base ** e
        return base

    def parse_atom(self):
        c = self.peek()
        if c is None:
            raise ValueError("missing operand")
        if c == '(':
            self.consume()
            val = self.parse_expr()
            if self.peek() != ')':
                raise ValueError("unbalanced parentheses")
            self.consume()
            return val
        if c.isdigit():
            start = self.i
            while self.i < self.n and self.s[self.i].isdigit():
                self.i += 1
            num = int(self.s[start:self.i])
            return Fraction(num)
        raise ValueError("invalid syntax")


def evaluate(expr: str) -> str:
    p = Parser(expr)
    result = p.parse()
    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"

