def evaluate(expr: str) -> str:
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c!r}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else (None, None)

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        # expr := term (('+' | '-') term)*
        left = parse_term()
        while True:
            t = peek()[0]
            if t in ('+', '-'):
                op = advance()[0]
                right = parse_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_term():
        # term := factor (('*' | '/') factor)*
        left = parse_factor()
        while True:
            t = peek()[0]
            if t in ('*', '/'):
                op = advance()[0]
                right = parse_factor()
                if op == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    left = left / right
            else:
                break
        return left

    def parse_factor():
        # factor := unary
        return parse_unary()

    def parse_unary():
        # unary := ('+' | '-')* power
        sign = 1
        while True:
            t = peek()[0]
            if t == '+':
                advance()
            elif t == '-':
                advance()
                sign = -sign
            else:
                break
        val = parse_power()
        return sign * val

    def parse_power():
        # power := atom ('^' unary)?   (right-associative)
        base = parse_atom()
        if peek()[0] == '^':
            advance()
            exp = parse_unary()
            if exp.denominator != 1:
                raise ValueError("Exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("0 raised to negative power")
            if e == 0:
                return Fraction(1)
            if e < 0:
                if base == 0:
                    raise ZeroDivisionError("0 raised to negative power")
                return Fraction(1) / (base ** (-e))
            return base ** e
        return base

    def parse_atom():
        t, v = peek()
        if t == 'num':
            advance()
            return Fraction(v)
        elif t == '(':
            advance()
            val = parse_expr()
            if peek()[0] != ')':
                raise ValueError("Unbalanced parentheses")
            advance()
            return val
        else:
            raise ValueError("Expected operand")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected token after expression")

    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"

from fractions import Fraction

class Parser:
    def __init__(self, s: str):
        self.s = s
        self.i = 0
        self.n = len(s)

    def error(self):
        raise ValueError("syntax error")

    def skip_spaces(self):
        while self.i < self.n and self.s[self.i] == ' ':
            self.i += 1

    def peek(self):
        self.skip_spaces()
        if self.i >= self.n:
            return None
        return self.s[self.i]

    def consume(self, ch):
        self.skip_spaces()
        if self.i < self.n and self.s[self.i] == ch:
            self.i += 1
            return True
        return False

    def parse(self):
        self.skip_spaces()
        if self.i >= self.n:
            self.error()
        val = self.parse_expr()
        self.skip_spaces()
        if self.i != self.n:
            self.error()
        return val

    def parse_expr(self):
        val = self.parse_term()
        while True:
            c = self.peek()
            if c == '+':
                self.consume('+')
                rhs = self.parse_term()
                val = val + rhs
            elif c == '-':
                self.consume('-')
                rhs = self.parse_term()
                val = val - rhs
            else:
                break
        return val

    def parse_term(self):
        val = self.parse_unary()
        while True:
            c = self.peek()
            if c == '*':
                self.consume('*')
                rhs = self.parse_unary()
                val = val * rhs
            elif c == '/':
                self.consume('/')
                rhs = self.parse_unary()
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                val = val / rhs
            else:
                break
        return val

    def parse_unary(self):
        c = self.peek()
        if c == '+':
            self.consume('+')
            return self.parse_unary()
        elif c == '-':
            self.consume('-')
            return -self.parse_unary()
        else:
            return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        c = self.peek()
        if c == '^':
            self.consume('^')
            exp = self.parse_unary()
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("zero to negative power")
            if e == 0:
                return Fraction(1)
            return base ** e
        return base

    def parse_atom(self):
        self.skip_spaces()
        if self.i >= self.n:
            self.error()
        c = self.s[self.i]
        if c == '(':
            self.consume('(')
            val = self.parse_expr()
            if not self.consume(')'):
                self.error()
            return val
        elif c.isdigit():
            start = self.i
            while self.i < self.n and self.s[self.i].isdigit():
                self.i += 1
            return Fraction(int(self.s[start:self.i]))
        else:
            self.error()


def evaluate(expr: str) -> str:
    p = Parser(expr)
    result = p.parse()
    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"

