        val = self.parse_term()
        while True:
            c = self.peek()
            if c == '+':
                self.consume('+')
                rhs = self.parse_term()
                val = val + rhs
            elif c == '-':
                self.consume('-')
                rhs = self.parse_term()
                val = val - rhs
            else:
                break
        return val

    def parse_term(self):
        val = self.parse_unary()
        while True:
            c = self.peek()
            if c == '*':
                self.consume('*')
                rhs = self.parse_unary()
                val = val * rhs
            elif c == '/':
                self.consume('/')
                rhs = self.parse_unary()
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                val = val / rhs
            else:
                break
        return val

    def parse_unary(self):
        c = self.peek()
        if c == '+':
            self.consume('+')
            return self.parse_unary()
        elif c == '-':
            self.consume('-')
            return -self.parse_unary()
        else:
            return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        c = self.peek()
        if c == '^':
            self.consume('^')
            exp = self.parse_unary()
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("zero to negative power")
            if e == 0:
                return Fraction(1)
            return base ** e
        return base

    def parse_atom(self):
        self.skip_spaces()
        if self.i >= self.n:
            self.error()
        c = self.s[self.i]
        if c == '(':
            self.consume('(')
            val = self.parse_expr()
            if not self.consume(')'):
                self.error()
            return val
        elif c.isdigit():
            start = self.i
            while self.i < self.n and self.s[self.i].isdigit():
                self.i += 1
            return Fraction(int(self.s[start:self.i]))
        else:
            self.error()


def evaluate(expr: str) -> str:
    p = Parser(expr)
    result = p.parse()
    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"

