def evaluate(expr: str) -> str:
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c!r}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else (None, None)

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        # expr := term (('+'|'-') term)*
        left = parse_term()
        while True:
            t = peek()[0]
            if t in ('+', '-'):
                op = advance()[0]
                right = parse_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_term():
        # term := factor (('*'|'/') factor)*
        left = parse_factor()
        while True:
            t = peek()[0]
            if t in ('*', '/'):
                op = advance()[0]
                right = parse_factor()
                if op == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    left = left / right
            else:
                break
        return left

    def parse_factor():
        # factor := ('+'|'-')* power
        sign = 1
        while True:
            t = peek()[0]
            if t == '+':
                advance()
            elif t == '-':
                advance()
                sign = -sign
            else:
                break
        val = parse_power()
        return sign * val

    def parse_power():
        # power := atom ('^' factor)?
        base = parse_atom()
        if peek()[0] == '^':
            advance()
            exp = parse_factor()  # right-associative, exponent can have unary sign
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("0 raised to negative power")
            if e == 0:
                return Fraction(1)
            # compute base ** e exactly
            if e > 0:
                return base ** e
            else:
                if base == 0:
                    raise ZeroDivisionError("0 raised to negative power")
                return Fraction(1) / (base ** (-e))
        return base

    def parse_atom():
        t = peek()[0]
        if t == 'num':
            return Fraction(advance()[1])
        elif t == '(':
            advance()
            val = parse_expr()
            if peek()[0] != ')':
                raise ValueError("missing closing parenthesis")
            advance()
            return val
        else:
            raise ValueError("expected number or '('")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("unexpected token")

    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"

