        # factor := ('+' | '-')* power
        sign = 1
        while True:
            tok = peek()
            if tok and tok[0] == '+':
                consume()
            elif tok and tok[0] == '-':
                consume()
                sign = -sign
            else:
                break
        val = parse_power()
        return sign * val

    def parse_power():
        # power := atom ('^' factor)?
        # Right-associative; exponent may start with unary sign.
        base = parse_atom()
        tok = peek()
        if tok and tok[0] == '^':
            consume()
            exp = parse_factor()  # allows unary signs, but must not consume * or /
            if exp.denominator != 1:
                raise ValueError("Exponent must be an integer")
