        t = peek()
        if t[0] == '+':
            consume()
            return parse_unary()
        elif t[0] == '-':
            consume()
            return -parse_unary()
        else:
            return parse_power()

    def parse_power():
        base = parse_atom()
        t = peek()
        if t[0] == '^':
            consume()
            # Exponent: parse a unary expression that may include * and /
