            if base == 0 and e < 0:
                raise ZeroDivisionError("0 raised to negative power")
            if e == 0:
                return Fraction(1)
            if e < 0:
                return Fraction(1) / (base ** (-e))
            return base ** e
        return base

    def parse_exponent():
        # Like parse_term but without consuming ^ (to keep right-assoc via recursion)
        left = parse_unary()
        while True:
            t = peek()
            if t[0] in ('*', '/'):
