def evaluate(expr: str) -> str:
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c!r}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else (None, None)

    def consume(expected=None):
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")
        tok = tokens[pos]
        if expected is not None and tok[0] != expected:
            raise ValueError(f"Expected {expected}, got {tok[0]}")
        pos += 1
        return tok

    def parse_expr():
        # expr := term (('+'|'-') term)*
        left = parse_term()
        while True:
            t = peek()[0]
            if t in ('+', '-'):
                op = consume()[0]
                right = parse_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_term():
        # term := factor (('*'|'/') factor)*
        left = parse_factor()
        while True:
            t = peek()[0]
            if t in ('*', '/'):
                op = consume()[0]
                right = parse_factor()
                if op == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("Division by zero")
                    left = left / right
            else:
                break
        return left

    def parse_factor():
        # factor := unary
        return parse_unary()

    def parse_unary():
        # unary := ('+'|'-')* power
        sign = 1
        while True:
            t = peek()[0]
            if t == '+':
                consume()
            elif t == '-':
                consume()
                sign = -sign
            else:
                break
        val = parse_power()
        return sign * val

    def parse_power():
        # power := atom ('^' unary)?   (right-associative)
        base = parse_atom()
        if peek()[0] == '^':
            consume('^')
            exp = parse_unary()
            if exp.denominator != 1:
                raise ValueError("Exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("0 raised to a negative power")
            if e == 0:
                return Fraction(1)
            return base ** e
        return base

    def parse_atom():
        t, v = peek()
        if t == 'NUM':
            consume()
            return Fraction(v)
        elif t == '(':
            consume('(')
            val = parse_expr()
            if peek()[0] != ')':
                raise ValueError("Missing closing parenthesis")
            consume(')')
            return val
        else:
            raise ValueError(f"Unexpected token: {t}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected token after expression")

    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"

