from fractions import Fraction

class Parser:
    def __init__(self, s):
        self.s = s
        self.i = 0
        self.n = len(s)

    def skip_ws(self):
        while self.i < self.n and self.s[self.i] == ' ':
            self.i += 1

    def peek(self):
        self.skip_ws()
        if self.i < self.n:
            return self.s[self.i]
        return None

    def parse(self):
        self.skip_ws()
        if self.i >= self.n:
            raise ValueError("empty expression")
        val = self.parse_expr()
        self.skip_ws()
        if self.i < self.n:
            raise ValueError("unexpected character")
        return val

    def parse_expr(self):
        val = self.parse_term()
        while True:
            c = self.peek()
            if c == '+':
                self.i += 1
                rhs = self.parse_term()
                val = val + rhs
            elif c == '-':
                self.i += 1
                rhs = self.parse_term()
                val = val - rhs
            else:
                break
        return val

    def parse_term(self):
        val = self.parse_unary()
        while True:
            c = self.peek()
            if c == '*':
                self.i += 1
                rhs = self.parse_unary()
                val = val * rhs
            elif c == '/':
                self.i += 1
                rhs = self.parse_unary()
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                val = val / rhs
            else:
                break
        return val

    def parse_unary(self):
        c = self.peek()
        if c == '-':
            self.i += 1
            val = self.parse_unary()
            return -val
        elif c == '+':
            self.i += 1
            return self.parse_unary()
        else:
            return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        c = self.peek()
        if c == '^':
            self.i += 1
            exp = self.parse_unary()
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("0 raised to negative power")
            if base == 0 and e == 0:
                return Fraction(1)
            return base ** e
        return base

    def parse_atom(self):
        c = self.peek()
        if c is None:
            raise ValueError("missing operand")
        if c == '(':
            self.i += 1
            val = self.parse_expr()
            if self.peek() != ')':
                raise ValueError("unbalanced parentheses")
            self.i += 1
            return val
        if c.isdigit():
            start = self.i
            while self.i < self.n and self.s[self.i].isdigit():
                self.i += 1
            return Fraction(int(self.s[start:self.i]))
        raise ValueError("unexpected character")

def evaluate(expr: str) -> str:
    p = Parser(expr)
    val = p.parse()
    if val.denominator == 1:
        return str(val.numerator)
    return f"{val.numerator}/{val.denominator}"

from fractions import Fraction

def evaluate(expr: str) -> str:
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c!r}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else (None, None)

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        # expr := term (('+' | '-') term)*
        left = parse_term()
        while True:
            t = peek()
            if t[0] in ('+', '-'):
                op = advance()[0]
                right = parse_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_term():
        # term := unary (('*' | '/') unary)*
        left = parse_unary()
        while True:
            t = peek()
            if t[0] in ('*', '/'):
                op = advance()[0]
                right = parse_unary()
                if op == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("Division by zero")
                    left = left / right
            else:
                break
        return left

    def parse_unary():
        # unary := ('+' | '-')* power
        t = peek()
        if t[0] == '+':
            advance()
            return parse_unary()
        elif t[0] == '-':
            advance()
            return -parse_unary()
        else:
            return parse_power()

    def parse_power():
        # power := atom ('^' unary)?
        base = parse_atom()
        t = peek()
        if t[0] == '^':
            advance()
            exp = parse_unary()
            if exp.denominator != 1:
                raise ValueError("Exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("0 raised to negative power")
            if e == 0:
                return Fraction(1)
            if e < 0:
                if base == 0:
                    raise ZeroDivisionError("0 raised to negative power")
                return Fraction(1) / (base ** (-e))
            return base ** e
        return base

    def parse_atom():
        t = peek()
        if t[0] == 'num':
            advance()
            return Fraction(t[1])
        elif t[0] == '(':
            advance()
            val = parse_expr()
            if peek()[0] != ')':
                raise ValueError("Unbalanced parentheses")
            advance()
            return val
        else:
            raise ValueError("Expected operand")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected token")

    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"

from fractions import Fraction


def evaluate(expr: str) -> str:
    tokens = _tokenize(expr)
    parser = _Parser(tokens)
    value = parser.parse_expr()
    if parser.pos != len(parser.tokens):
        raise ValueError("unexpected token")
    if value.denominator == 1:
        return str(value.numerator)
    return f"{value.numerator}/{value.denominator}"


def _tokenize(expr: str):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(("num", int(expr[i:j])))
            i = j
            continue
        if c in "+-*/^()":
            tokens.append((c, c))
            i += 1
            continue
        raise ValueError(f"invalid character: {c!r}")
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return (None, None)

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse_expr(self):
        value = self.parse_term()
        while True:
            kind, _ = self.peek()
            if kind == "+":
                self.advance()
                value = value + self.parse_term()
            elif kind == "-":
                self.advance()
                value = value - self.parse_term()
            else:
                break
        return value

    def parse_term(self):
        value = self.parse_factor()
        while True:
            kind, _ = self.peek()
            if kind == "*":
                self.advance()
                value = value * self.parse_factor()
            elif kind == "/":
                self.advance()
                rhs = self.parse_factor()
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                value = value / rhs
            else:
                break
        return value

    def parse_factor(self):
        sign = 1
        while True:
            kind, _ = self.peek()
            if kind == "+":
                self.advance()
            elif kind == "-":
                self.advance()
                sign = -sign
            else:
                break
        value = self.parse_power()
        return sign * value

    def parse_power(self):
        base = self.parse_atom()
        kind, _ = self.peek()
        if kind == "^":
            self.advance()
            exponent = self.parse_factor()
            if exponent.denominator != 1:
                raise ValueError("exponent must be an integer")
            exp = exponent.numerator
            if base == 0 and exp < 0:
                raise ZeroDivisionError("zero to negative power")
            if exp == 0:
                return Fraction(1)
            return base ** exp
        return base

    def parse_atom(self):
        kind, val = self.peek()
        if kind == "num":
            self.advance()
            return Fraction(val)
        if kind == "(":
            self.advance()
            value = self.parse_expr()
            kind2, _ = self.peek()
            if kind2 != ")":
                raise ValueError("unbalanced parentheses")
            self.advance()
            return value
        raise ValueError("expected operand")

from fractions import Fraction


def evaluate(expr: str) -> str:
    # ---- Tokenizer ----
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/^()':
            tokens.append((c, c))
            i += 1
            continue
        raise ValueError(f"Invalid character: {c!r}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else (None, None)

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    # Grammar (right-assoc power, unary binds looser than ^):
    #   expr    := term (('+' | '-') term)*
    #   term    := unary (('*' | '/') unary)*
    #   unary   := ('+' | '-')* power
    #   power   := atom ('^' unary)?          # right-associative
    #   atom    := num | '(' expr ')'

    def parse_expr():
        left = parse_term()
        while True:
            t = peek()[0]
            if t == '+' or t == '-':
                op = advance()[0]
                right = parse_term()
                left = left + right if op == '+' else left - right
            else:
                break
        return left

    def parse_term():
        left = parse_unary()
        while True:
            t = peek()[0]
            if t == '*' or t == '/':
                op = advance()[0]
                right = parse_unary()
                if op == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    left = left / right
            else:
                break
        return left

    def parse_unary():
        sign = 1
        while True:
            t = peek()[0]
            if t == '+':
                advance()
            elif t == '-':
                advance()
                sign = -sign
            else:
                break
        val = parse_power()
        return sign * val

    def parse_power():
        base = parse_atom()
        if peek()[0] == '^':
            advance()
            exp = parse_unary()  # right-associative, exponent may have unary sign
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("0 raised to negative power")
            return base ** e
        return base

    def parse_atom():
        t, v = peek()
        if t == 'num':
            advance()
            return Fraction(v)
        if t == '(':
            advance()
            val = parse_expr()
            if peek()[0] != ')':
                raise ValueError("missing closing parenthesis")
            advance()
            return val
        raise ValueError("expected operand")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("unexpected token")

    if result.denominator == 1:
        return str(result.numerator)
    return f"{result.numerator}/{result.denominator}"

from fractions import Fraction

class Parser:
    def __init__(self, s: str):
        self.s = s
        self.i = 0
        self.n = len(s)

    def skip_spaces(self):
        while self.i < self.n and self.s[self.i] == ' ':
            self.i += 1

    def peek(self):
        self.skip_spaces()
        if self.i < self.n:
            return self.s[self.i]
        return None

    def consume(self, ch=None):
        self.skip_spaces()
        if self.i >= self.n:
            raise ValueError("Unexpected end of expression")
        c = self.s[self.i]
        if ch is not None and c != ch:
            raise ValueError(f"Expected '{ch}', got '{c}'")
        self.i += 1
        return c

    def parse(self):
        self.skip_spaces()
        if self.i >= self.n:
            raise ValueError("Empty expression")
        val = self.parse_expr()
        self.skip_spaces()
        if self.i < self.n:
            raise ValueError(f"Unexpected character: {self.s[self.i]}")
        return val

    def parse_expr(self):
        left = self.parse_term()
        while True:
            c = self.peek()
            if c == '+':
                self.consume('+')
                right = self.parse_term()
                left = left + right
            elif c == '-':
                self.consume('-')
                right = self.parse_term()
                left = left - right
            else:
                break
        return left

    def parse_term(self):
        left = self.parse_unary()
        while True:
            c = self.peek()
            if c == '*':
                self.consume('*')
                right = self.parse_unary()
                left = left * right
            elif c == '/':
                self.consume('/')
                right = self.parse_unary()
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                left = left / right
            else:
                break
        return left

    def parse_unary(self):
        c = self.peek()
        if c == '-':
            self.consume('-')
            val = self.parse_unary()
            return -val
        elif c == '+':
            self.consume('+')
            return self.parse_unary()
        else:
            return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        c = self.peek()
        if c == '^':
            self.consume('^')
            exp = self.parse_unary()
            if exp.denominator != 1:
                raise ValueError("Exponent must be an integer")
            e = exp.numerator
            if base == 0 and e < 0:
                raise ZeroDivisionError("0 raised to negative power")
            return base ** e
        return base

    def parse_atom(self):
        c = self.peek()
        if c is None:
            raise ValueError("Missing operand")
        if c == '(':
            self.consume('(')
            val = self.parse_expr()
            self.skip_spaces()
            if self.i >= self.n or self.s[self.i] != ')':
                raise ValueError("Unbalanced parentheses")
            self.consume(')')
            return val
        if c.isdigit():
            start = self.i
            while self.i < self.n and self.s[self.i].isdigit():
                self.i += 1
            return Fraction(int(self.s[start:self.i]))
        raise ValueError(f"Unexpected character: {c}")


def evaluate(expr: str) -> str:
    p = Parser(expr)
    result = p.parse()
    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"

import re
from fractions import Fraction

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    if not s.startswith('P'):
        raise ValueError("must start with P")
    body = s[1:]
    if body == '':
        raise ValueError("empty duration")

    # Split date and time parts
    if 'T' in body:
        if body.count('T') != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split('T')
        if time_part == '':
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Tokenize a part into (number_string, letter) pairs
    token_re = re.compile(r'(\d+(?:[.,]\d+)?)([A-Z])')
    def tokenize(part):
        tokens = []
        pos = 0
        while pos < len(part):
            m = token_re.match(part, pos)
            if not m:
                raise ValueError("invalid component")
            tokens.append((m.group(1), m.group(2)))
            pos = m.end()
        return tokens

    date_tokens = tokenize(date_part) if date_part else []
    time_tokens = tokenize(time_part) if time_part is not None else []

    # Validate date part
    date_letters = [t[1] for t in date_tokens]
    if 'W' in date_letters:
        if len(date_tokens) != 1 or date_tokens[0][1] != 'W' or time_tokens:
            raise ValueError("W must be alone")
    else:
        order = ['Y', 'M', 'D']
        idx = -1
        for letter in date_letters:
            if letter not in order:
                raise ValueError("invalid date letter")
            j = order.index(letter)
            if j <= idx:
                raise ValueError("date order/duplicate")
            idx = j

    # Validate time part
    order_t = ['H', 'M', 'S']
    idx = -1
    for letter in [t[1] for t in time_tokens]:
        if letter not in order_t:
            raise ValueError("invalid time letter")
        j = order_t.index(letter)
        if j <= idx:
            raise ValueError("time order/duplicate")
        idx = j

    if not date_tokens and not time_tokens:
        raise ValueError("no components")

    # Combine tokens in order, last overall may be fractional
    all_tokens = date_tokens + time_tokens
    if not all_tokens:
        raise ValueError("no components")

    # Check fractions: only last token may have fraction
    for i, (num, _) in enumerate(all_tokens):
        has_frac = ('.' in num) or (',' in num)
        if has_frac and i != len(all_tokens) - 1:
            raise ValueError("fraction only allowed on last component")

    # Conversion factors
    factors = {
        'Y': 365 * 86400,
        'M_date': 30 * 86400,
        'W': 7 * 86400,
        'D': 86400,
        'H': 3600,
        'M_time': 60,
        'S': 1,
    }

    total = Fraction(0)
    for i, (num, letter) in enumerate(all_tokens):
        num = num.replace(',', '.')
        value = Fraction(num)
        if letter == 'M':
            factor = factors['M_date'] if i < len(date_tokens) else factors['M_time']
        else:
            factor = factors[letter]
        total += value * factor

    if total.denominator != 1:
        raise ValueError("not a whole number of seconds")
    return int(total)

