from fractions import Fraction


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("duration must be a string")
    if not s.startswith("P"):
        raise ValueError("duration must start with P")

    body = s[1:]
    if body == "":
        raise ValueError("empty duration")

    # Split into date and time parts
    if "T" in body:
        if body.count("T") != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split("T")
        if time_part == "":
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Tokenize a part into (number_string, letter) pairs
    token_re = re.compile(r"(\d+(?:[.,]\d+)?)([A-Z])")

    def tokenize(part: str):
        tokens = []
        pos = 0
        while pos < len(part):
            m = token_re.match(part, pos)
            if not m:
                raise ValueError("invalid component")
            tokens.append((m.group(1), m.group(2)))
            pos = m.end()
        return tokens

    date_tokens = tokenize(date_part) if date_part else []
    time_tokens = tokenize(time_part) if time_part is not None else []

    if not date_tokens and not time_tokens:
        raise ValueError("no components")

    # Validate date part
    date_letters = [t[1] for t in date_tokens]
    if "W" in date_letters:
        if len(date_tokens) != 1 or date_tokens[0][1] != "W":
            raise ValueError("W must be alone")
        if time_tokens:
            raise ValueError("W cannot be combined with time")
    else:
        order = ["Y", "M", "D"]
        idx = -1
        for letter in date_letters:
            if letter not in order:
                raise ValueError("invalid date letter")
            i = order.index(letter)
            if i <= idx:
                raise ValueError("date components out of order or repeated")
            idx = i

    # Validate time part
    time_order = ["H", "M", "S"]
    idx = -1
    for letter in [t[1] for t in time_tokens]:
        if letter not in time_order:
            raise ValueError("invalid time letter")
        i = time_order.index(letter)
        if i <= idx:
            raise ValueError("time components out of order or repeated")
        idx = i

    # Combine tokens in order, fraction only allowed on last overall
    all_tokens = date_tokens + time_tokens
    for i, (num, _) in enumerate(all_tokens):
        has_frac = "." in num or "," in num
        if has_frac and i != len(all_tokens) - 1:
            raise ValueError("fraction only allowed on last component")

    # Conversion factors in seconds
    factors = {
        "Y": 365 * 86400,
        "M_date": 30 * 86400,
        "W": 7 * 86400,
        "D": 86400,
        "H": 3600,
        "M_time": 60,
        "S": 1,
    }

    total = Fraction(0)

    for num, letter in date_tokens:
        num = num.replace(",", ".")
        value = Fraction(num)
        if letter == "M":
            factor = factors["M_date"]
        else:
            factor = factors[letter]
        total += value * factor

    for num, letter in time_tokens:
        num = num.replace(",", ".")
        value = Fraction(num)
        if letter == "M":
            factor = factors["M_time"]
        else:
            factor = factors[letter]
        total += value * factor

    if total.denominator != 1:
        raise ValueError("duration is not a whole number of seconds")

    return int(total)

import re
from fractions import Fraction

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    if not s.startswith('P'):
        raise ValueError("must start with P")
    body = s[1:]
    if body == '':
        raise ValueError("empty duration")

    # Split date and time parts
    if 'T' in body:
        if body.count('T') != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split('T')
        if time_part == '':
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Regex for a component: number (with optional fraction) + letter
    num = r'(\d+(?:[.,]\d+)?)'
    date_re = re.compile(r'^' + num + r'([YMWD])')
    time_re = re.compile(r'^' + num + r'([HMS])')

    def parse_part(part, regex, allowed_letters, is_time):
        components = []
        pos = 0
        while pos < len(part):
            m = regex.match(part, pos)
            if not m:
                raise ValueError("invalid component")
            number_str, letter = m.group(1), m.group(2)
            if letter not in allowed_letters:
                raise ValueError("invalid letter")
            components.append((number_str, letter))
            pos = m.end()
        return components

    date_components = parse_part(date_part, date_re, 'YMWD', False) if date_part else []
    time_components = parse_part(time_part, time_re, 'HMS', True) if time_part is not None else []

    if not date_components and not time_components:
        raise ValueError("no components")

    # Check weeks rule
    letters = [c[1] for c in date_components]
    if 'W' in letters:
        if len(date_components) != 1 or time_components:
            raise ValueError("W must be alone")
        if letters != ['W']:
            raise ValueError("W must be alone")

    # Check order and uniqueness
    date_order = {'Y': 0, 'M': 1, 'W': 1, 'D': 2}
    time_order = {'H': 0, 'M': 1, 'S': 2}

    def check_order(components, order):
        seen = set()
        last = -1
        for _, letter in components:
            if letter in seen:
                raise ValueError("duplicate letter")
            seen.add(letter)
            idx = order[letter]
            if idx <= last:
                raise ValueError("wrong order")
            last = idx

    check_order(date_components, date_order)
    check_order(time_components, time_order)

    # Check fraction only on last component overall
    all_components = date_components + time_components
    for i, (num_str, _) in enumerate(all_components):
        has_frac = ('.' in num_str) or (',' in num_str)
        if has_frac and i != len(all_components) - 1:
            raise ValueError("fraction only allowed on last component")

    # Conversion factors in seconds
    factors = {
        'Y': 365 * 86400,
        'M': 30 * 86400,  # months in date part
        'W': 7 * 86400,
        'D': 86400,
        'H': 3600,
        'S': 1,
    }

    total = Fraction(0)
    for num_str, letter in date_components:
        if letter == 'M':
            factor = factors['M']
        else:
            factor = factors[letter]
        val = Fraction(num_str.replace(',', '.'))
        total += val * factor

    for num_str, letter in time_components:
        if letter == 'M':
            factor = 60
        elif letter == 'H':
            factor = 3600
        else:  # S
            factor = 1
        val = Fraction(num_str.replace(',', '.'))
        total += val * factor

    if total.denominator != 1:
        raise ValueError("not a whole number of seconds")
    return int(total)

