            return _to_int(val * 7 * 86400)
        # Parse components
        pos = 0
        last_letter_idx = -1
        comps = []
        while pos < len(date_part):
            m = re.match(r'(\d+(?:[.,]\d+)?)([YMD])', date_part[pos:])
            if not m:
                raise ValueError("invalid date component")
            num_str, letter = m.group(1), m.group(2)
            idx = date_order.index(letter)
            if idx <= last_letter_idx:
                raise ValueError("order or duplicate")
            last_letter_idx = idx
            comps.append((num_str, letter))
            pos += len(m.group(0))
        if pos != len(date_part):
            raise ValueError("trailing characters")
        # Check fraction only on last component
        for i, (num_str, letter) in enumerate(comps):
            if ('.' in num_str or ',' in num_str) and i != len(comps)-1:
                raise ValueError("fraction not last")
        for num_str, letter in comps:
            date_vals[letter] = _parse_number(num_str)

    # Parse time part
    time_units = {'H': 3600, 'M': 60, 'S': 1}
    time_order = ['H', 'M', 'S']
    time_vals = {}
    if time_part is not None:
        pos = 0
        last_letter_idx = -1
        comps = []
        while pos < len(time_part):
            m = re.match(r'(\d+(?:[.,]\d+)?)([HMS])', time_part[pos:])
            if not m:
                raise ValueError("invalid time component")
            num_str, letter = m.group(1), m.group(2)
            idx = time_order.index(letter)
            if idx <= last_letter_idx:
                raise ValueError("order or duplicate")
            last_letter_idx = idx
            comps.append((num_str, letter))
            pos += len(m.group(0))
        if pos != len(time_part):
            raise ValueError("trailing characters")
        for i, (num_str, letter) in enumerate(comps):
            if ('.' in num_str or ',' in num_str) and i != len(comps)-1:
                raise ValueError("fraction not last")
        for num_str, letter in comps:
            time_vals[letter] = _parse_number(num_str)

    # At least one component
    if not date_vals and not time_vals:
        raise ValueError("no components")

    # Compute total seconds
    total = Fraction(0)
    for letter, val in date_vals.items():
        total += val * date_units[letter]
    for letter, val in time_vals.items():
        total += val * time_units[letter]

    return _to_int(total)

def _parse_number(num_str: str) -> Fraction:
    # Replace comma with dot
    s = num_str.replace(',', '.')
    if s.count('.') > 1:
        raise ValueError("multiple decimal separators")
    if '.' in s:
        int_part, frac_part = s.split('.')
        if int_part == '' or frac_part == '':
            raise ValueError("invalid fraction")
        if not int_part.isdigit() or not frac_part.isdigit():
            raise ValueError("invalid digits")
        return Fraction(int(int_part) * (10**len(frac_part)) + int(frac_part), 10**len(frac_part))
    else:
        if not s.isdigit():
            raise ValueError("invalid digits")
        return Fraction(int(s))

def _to_int(val: Fraction) -> int:
    if val.denominator != 1:
        raise ValueError("not a whole number of seconds")
    return int(val)

import re
from fractions import Fraction

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    if not s.startswith('P'):
        raise ValueError("must start with P")
    body = s[1:]
    if body == '':
        raise ValueError("empty duration")

    # Split date and time
    if 'T' in body:
        if body.count('T') != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split('T')
        if time_part == '':
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Tokenize date part
    date_tokens = []
    if date_part:
        pos = 0
        while pos < len(date_part):
            m = re.match(r'(\d+(?:[.,]\d+)?)([YMWD])', date_part[pos:])
            if not m:
                raise ValueError("bad date component")
            num, letter = m.group(1), m.group(2)
            date_tokens.append((num, letter))
            pos += m.end()
        # check order and uniqueness
        order = {'Y': 0, 'M': 1, 'W': 2, 'D': 3}
        seen = set()
        last = -1
        for num, letter in date_tokens:
            if letter in seen:
                raise ValueError("duplicate letter")
            seen.add(letter)
            idx = order[letter]
            if idx <= last:
                raise ValueError("bad order")
            last = idx
        # weeks only alone
        if 'W' in seen and len(date_tokens) != 1:
            raise ValueError("W must be alone")

    # Tokenize time part
    time_tokens = []
    if time_part is not None:
        pos = 0
        while pos < len(time_part):
            m = re.match(r'(\d+(?:[.,]\d+)?)([HMS])', time_part[pos:])
            if not m:
                raise ValueError("bad time component")
            num, letter = m.group(1), m.group(2)
            time_tokens.append((num, letter))
            pos += m.end()
        order = {'H': 0, 'M': 1, 'S': 2}
        seen = set()
        last = -1
        for num, letter in time_tokens:
            if letter in seen:
                raise ValueError("duplicate letter")
            seen.add(letter)
            idx = order[letter]
            if idx <= last:
                raise ValueError("bad order")
            last = idx

    all_tokens = date_tokens + time_tokens
    if not all_tokens:
        raise ValueError("no components")

    # Fraction only allowed on last component
    for i, (num, letter) in enumerate(all_tokens):
        has_frac = ('.' in num) or (',' in num)
        if has_frac and i != len(all_tokens) - 1:
            raise ValueError("fraction only on last component")

    # Convert
    total = Fraction(0)
    for num, letter in all_tokens:
        num = num.replace(',', '.')
        val = Fraction(num)
        if letter == 'Y':
            total += val * 365 * 86400
        elif letter == 'M':
            # month if in date part, minute if in time part
            if (num, letter) in date_tokens:
                total += val * 30 * 86400
            else:
                total += val * 60
        elif letter == 'W':
            total += val * 7 * 86400
        elif letter == 'D':
            total += val * 86400
        elif letter == 'H':
            total += val * 3600
        elif letter == 'S':
            total += val

    if total.denominator != 1:
        raise ValueError("not whole seconds")
    return int(total)

import re
from fractions import Fraction


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("duration must be a string")
    if not s.startswith("P"):
        raise ValueError("duration must start with P")

    body = s[1:]
    if body == "":
        raise ValueError("empty duration")

    # Split into date and time parts.
    if "T" in body:
        if body.count("T") != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split("T")
        if time_part == "":
            raise ValueError("T must be followed by a component")
    else:
        date_part, time_part = body, None

    # Tokenize a part into (number_string, letter) pairs.
    token_re = re.compile(r"(\d+(?:[.,]\d+)?)([A-Z])")

    def tokenize(part: str):
        tokens = []
        pos = 0
        while pos < len(part):
            m = token_re.match(part, pos)
            if not m:
                raise ValueError("invalid component")
            tokens.append((m.group(1), m.group(2)))
            pos = m.end()
        return tokens

    date_tokens = tokenize(date_part) if date_part else []
    time_tokens = tokenize(time_part) if time_part is not None else []

    if not date_tokens and not time_tokens:
        raise ValueError("no components")

    # Validate date part.
    date_order = {"Y": 0, "M": 1, "D": 2}
    seen = set()
    last_index = -1
    for num, letter in date_tokens:
        if letter == "W":
            # Weeks only allowed alone.
            if len(date_tokens) != 1 or time_tokens:
                raise ValueError("W cannot be combined")
            if letter in seen:
                raise ValueError("duplicate component")
            seen.add(letter)
            continue
        if letter not in date_order:
            raise ValueError("invalid date component")
        if letter in seen:
            raise ValueError("duplicate component")
        idx = date_order[letter]
        if idx <= last_index:
            raise ValueError("date components out of order")
        last_index = idx
        seen.add(letter)

    # Validate time part.
    time_order = {"H": 0, "M": 1, "S": 2}
    seen_time = set()
    last_time_index = -1
    for num, letter in time_tokens:
        if letter not in time_order:
            raise ValueError("invalid time component")
        if letter in seen_time:
            raise ValueError("duplicate component")
        idx = time_order[letter]
        if idx <= last_time_index:
            raise ValueError("time components out of order")
        last_time_index = idx
        seen_time.add(letter)

    # Fraction only allowed on the very last component overall.
    all_tokens = date_tokens + time_tokens
    for i, (num, letter) in enumerate(all_tokens):
        has_frac = "." in num or "," in num
        if has_frac and i != len(all_tokens) - 1:
            raise ValueError("fraction only allowed on last component")

    # Compute seconds.
    def parse_number(num: str) -> Fraction:
        num = num.replace(",", ".")
        if "." in num:
            whole, frac = num.split(".")
            return Fraction(int(whole)) + Fraction(int(frac), 10 ** len(frac))
        return Fraction(int(num))

    total = Fraction(0)

    for num, letter in date_tokens:
        value = parse_number(num)
        if letter == "Y":
            total += value * 365 * 86400
        elif letter == "M":
            total += value * 30 * 86400
        elif letter == "W":
            total += value * 7 * 86400
        elif letter == "D":
            total += value * 86400

    for num, letter in time_tokens:
        value = parse_number(num)
        if letter == "H":
            total += value * 3600
        elif letter == "M":
            total += value * 60
        elif letter == "S":
            total += value

    if total.denominator != 1:
        raise ValueError("duration is not a whole number of seconds")

    return int(total)

import re
from fractions import Fraction

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    if not s.startswith('P'):
        raise ValueError("must start with P")
    body = s[1:]
    if body == '':
        raise ValueError("empty duration")

    # Split into date and time parts
    if 'T' in body:
        if body.count('T') != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split('T')
        if time_part == '':
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Parse a component sequence
    def parse_components(text, letters, allow_weeks=False):
        # returns list of (value, letter)
        if text == '':
            return []
        comps = []
        i = 0
        n = len(text)
        while i < n:
            # number
            j = i
            while j < n and text[j].isdigit():
                j += 1
            if j == i:
                raise ValueError("expected number")
            num_str = text[i:j]
            # optional fraction
            frac = None
            if j < n and text[j] in '.,':
                k = j + 1
                while k < n and text[k].isdigit():
                    k += 1
                if k == j + 1:
                    raise ValueError("fraction needs digits")
                frac = text[j+1:k]
                j = k
            # letter
            if j >= n:
                raise ValueError("missing unit")
            letter = text[j]
            if letter not in letters:
                raise ValueError("invalid unit")
            j += 1
            # check fraction only allowed on last component
            if frac is not None and j != n:
                raise ValueError("fraction only on last component")
            value = Fraction(int(num_str))
            if frac is not None:
                value += Fraction(int(frac), 10 ** len(frac))
            comps.append((value, letter))
            i = j
        # check order and uniqueness
        seen = set()
        last_idx = -1
        for val, letter in comps:
            idx = letters.index(letter)
            if idx <= last_idx:
                raise ValueError("order or duplicate")
            last_idx = idx
            seen.add(letter)
        return comps

    date_letters = ['Y', 'M', 'D']
    time_letters = ['H', 'M', 'S']

    # Weeks special case
    if 'W' in body:
        # W only allowed alone: PnW
        if not re.fullmatch(r'P\d+(?:[.,]\d+)?W', s):
            raise ValueError("W must be alone")
        m = re.fullmatch(r'P(\d+)(?:[.,](\d+))?W', s)
        if not m:
            raise ValueError("invalid week")
        val = Fraction(int(m.group(1)))
        if m.group(2):
            val += Fraction(int(m.group(2)), 10 ** len(m.group(2)))
        seconds = val * 7 * 86400
        if seconds.denominator != 1:
            raise ValueError("not whole seconds")
        return int(seconds)

    date_comps = parse_components(date_part, date_letters)
    time_comps = parse_components(time_part, time_letters) if time_part is not None else []

    if not date_comps and not time_comps:
        raise ValueError("no components")

    total = Fraction(0)
    for val, letter in date_comps:
        if letter == 'Y':
            total += val * 365 * 86400
        elif letter == 'M':
            total += val * 30 * 86400
        elif letter == 'D':
            total += val * 86400
    for val, letter in time_comps:
        if letter == 'H':
            total += val * 3600
        elif letter == 'M':
            total += val * 60
        elif letter == 'S':
            total += val

    if total.denominator != 1:
        raise ValueError("not whole seconds")
    return int(total)

