from fractions import Fraction


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    if not s.startswith("P"):
        raise ValueError("must start with P")
    body = s[1:]
    if body == "":
        raise ValueError("empty duration")

    # Split date and time parts
    if "T" in body:
        if body.count("T") != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split("T")
        if time_part == "":
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Tokenize a part into (number_string, letter) pairs
    token_re = re.compile(r"(\d+(?:[.,]\d+)?)([A-Z])")

    def tokenize(part, allowed_letters):
        tokens = []
        pos = 0
        while pos < len(part):
            m = token_re.match(part, pos)
            if not m:
                raise ValueError("invalid component")
            num, letter = m.group(1), m.group(2)
            if letter not in allowed_letters:
                raise ValueError("invalid letter")
            tokens.append((num, letter))
            pos = m.end()
        return tokens

    date_tokens = tokenize(date_part, set("YMWD")) if date_part else []
    time_tokens = tokenize(time_part, set("HMS")) if time_part is not None else []

    # Validate weeks: only alone, and only in date part
    if any(letter == "W" for _, letter in date_tokens):
        if len(date_tokens) != 1 or time_tokens:
            raise ValueError("W must be alone")
    if any(letter == "W" for _, letter in time_tokens):
        raise ValueError("W not allowed in time part")

    # Validate order and uniqueness
    date_order = {"Y": 0, "M": 1, "W": 2, "D": 3}
    time_order = {"H": 0, "M": 1, "S": 2}

    def check_order(tokens, order):
        seen = set()
        last = -1
        for _, letter in tokens:
            if letter in seen:
                raise ValueError("duplicate letter")
            seen.add(letter)
            idx = order[letter]
            if idx <= last:
                raise ValueError("wrong order")
            last = idx

    check_order(date_tokens, date_order)
    check_order(time_tokens, time_order)

    if not date_tokens and not time_tokens:
        raise ValueError("no components")

    # Combine tokens in sequence; only the very last may have a fraction
    all_tokens = date_tokens + time_tokens
    for i, (num, _) in enumerate(all_tokens):
        has_frac = "." in num or "," in num
        if has_frac and i != len(all_tokens) - 1:
            raise ValueError("fraction only allowed on last component")

    # Conversion factors to seconds
    factors = {
        "Y": 365 * 86400,
        "M_date": 30 * 86400,
        "W": 7 * 86400,
        "D": 86400,
        "H": 3600,
        "M_time": 60,
        "S": 1,
    }

    total = Fraction(0)
    for num, letter in date_tokens:
        num = num.replace(",", ".")
        factor = factors["M_date"] if letter == "M" else factors[letter]
        total += Fraction(num) * factor
    for num, letter in time_tokens:
        num = num.replace(",", ".")
        factor = factors["M_time"] if letter == "M" else factors[letter]
        total += Fraction(num) * factor

    if total.denominator != 1:
        raise ValueError("not a whole number of seconds")
    return int(total)

