    token_re = re.compile(r"(\d+(?:[.,]\d+)?)([A-Z])")

    def tokenize(part):
        tokens = []
        pos = 0
        while pos < len(part):
            m = token_re.match(part, pos)
            if not m:
                raise ValueError("invalid component")
            tokens.append((m.group(1), m.group(2)))
            pos = m.end()
        return tokens

    date_tokens = tokenize(date_part) if date_part else []
    time_tokens = tokenize(time_part) if time_part is not None else []

    # Validate date part
    date_letters = [t[1] for t in date_tokens]
    if "W" in date_letters:
        if len(date_tokens) != 1 or date_tokens[0][1] != "W":
            raise ValueError("W must be alone")
        if time_tokens:
            raise ValueError("W cannot combine with time")
    else:
        order = ["Y", "M", "D"]
        idx = -1
        for letter in date_letters:
            if letter not in order:
                raise ValueError("invalid date letter")
            j = order.index(letter)
            if j <= idx:
                raise ValueError("bad order or duplicate")
            idx = j

    # Validate time part
    time_order = ["H", "M", "S"]
    idx = -1
    for letter in [t[1] for t in time_tokens]:
        if letter not in time_order:
            raise ValueError("invalid time letter")
        j = time_order.index(letter)
        if j <= idx:
            raise ValueError("bad order or duplicate")
        idx = j

    all_tokens = date_tokens + time_tokens
    if not all_tokens:
        raise ValueError("no components")

    # Only last component may have a fraction
    for num, _ in all_tokens[:-1]:
        if "." in num or "," in num:
            raise ValueError("fraction not allowed here")

    # Convert to seconds
    factors = {
        "Y": Fraction(365 * 86400),
        "M_date": Fraction(30 * 86400),
        "W": Fraction(7 * 86400),
        "D": Fraction(86400),
        "H": Fraction(3600),
        "M_time": Fraction(60),
        "S": Fraction(1),
    }

    total = Fraction(0)
    for num, letter in date_tokens:
        num = num.replace(",", ".")
        if letter == "M":
            key = "M_date"
        else:
            key = letter
        total += Fraction(num) * factors[key]

    for num, letter in time_tokens:
        num = num.replace(",", ".")
        key = "M_time" if letter == "M" else letter
        total += Fraction(num) * factors[key]

    if total.denominator != 1:
        raise ValueError("not a whole number of seconds")
    return int(total)

import re
from fractions import Fraction

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    if not s.startswith('P'):
        raise ValueError("must start with P")
    body = s[1:]
    if body == '':
        raise ValueError("empty duration")

    # Split date and time parts
    if 'T' in body:
        if body.count('T') != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split('T')
        if time_part == '':
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Regex for a number: integer or last-component fraction
    num = r'\d+(?:[.,]\d+)?'

    # Parse date part
    date_units = []
    if date_part:
        # Weeks alone
        m = re.fullmatch(r'(\d+(?:[.,]\d+)?)W', date_part)
        if m:
            val = Fraction(m.group(1).replace(',', '.'))
            total = val * 7 * 86400
            if total.denominator != 1:
                raise ValueError("fractional seconds")
            return int(total)
        # Otherwise Y M D in order, no W
        pos = 0
        order = ['Y', 'M', 'D']
        idx = 0
        while pos < len(date_part):
            m = re.match(num, date_part[pos:])
            if not m:
                raise ValueError("bad number")
            number_str = m.group(0)
            pos += len(number_str)
            if pos >= len(date_part):
                raise ValueError("missing unit")
            unit = date_part[pos]
            pos += 1
            if unit not in order:
                raise ValueError("bad unit")
            uidx = order.index(unit)
            if uidx < idx:
                raise ValueError("order")
            if uidx == idx and date_units and date_units[-1][0] == unit:
                raise ValueError("duplicate")
            idx = uidx + 1
            date_units.append((unit, number_str))
        # Check duplicates
        seen = set()
        for u, _ in date_units:
            if u in seen:
                raise ValueError("duplicate")
            seen.add(u)

    # Parse time part
    time_units = []
    if time_part is not None:
        pos = 0
        order = ['H', 'M', 'S']
        idx = 0
        while pos < len(time_part):
            m = re.match(num, time_part[pos:])
            if not m:
                raise ValueError("bad number")
            number_str = m.group(0)
            pos += len(number_str)
            if pos >= len(time_part):
                raise ValueError("missing unit")
            unit = time_part[pos]
            pos += 1
            if unit not in order:
                raise ValueError("bad unit")
            uidx = order.index(unit)
            if uidx < idx:
                raise ValueError("order")
            idx = uidx + 1
            time_units.append((unit, number_str))
        seen = set()
        for u, _ in time_units:
            if u in seen:
                raise ValueError("duplicate")
            seen.add(u)

    # At least one component
    if not date_units and not time_units:
        raise ValueError("no components")

    # Determine last component overall
    all_units = date_units + time_units
    last_unit = all_units[-1][0]

    # Check fraction only on last
    for i, (u, nstr) in enumerate(all_units):
        has_frac = ('.' in nstr or ',' in nstr)
        if has_frac and i != len(all_units) - 1:
            raise ValueError("fraction not last")

    # Compute total seconds
    total = Fraction(0)
    for u, nstr in all_units:
        val = Fraction(nstr.replace(',', '.'))
        if u == 'Y':
            total += val * 365 * 86400
        elif u == 'M' and u in [x[0] for x in date_units]:
            total += val * 30 * 86400
        elif u == 'D':
            total += val * 86400
        elif u == 'H':
            total += val * 3600
        elif u == 'M' and u in [x[0] for x in time_units]:
            total += val * 60
        elif u == 'S':
            total += val
        else:
            raise ValueError("unknown unit")

    if total.denominator != 1:
        raise ValueError("not whole seconds")
    return int(total)

