def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    if not s.startswith('P'):
        raise ValueError("must start with P")
    body = s[1:]
    if not body:
        raise ValueError("empty duration")

    # Split date and time parts
    if 'T' in body:
        if body.count('T') != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split('T')
        if not time_part:
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Tokenize a part into (number_string, letter) pairs
    def tokenize(part, allowed_letters):
        tokens = []
        i = 0
        n = len(part)
        while i < n:
            # parse number
            start = i
            while i < n and part[i].isdigit():
                i += 1
            if i == start:
                raise ValueError("expected number")
            num_str = part[start:i]
            # optional fraction
            if i < n and part[i] in '.,':
                sep = part[i]
                i += 1
                frac_start = i
                while i < n and part[i].isdigit():
                    i += 1
                if i == frac_start:
                    raise ValueError("fraction needs digits after separator")
                num_str += '.' + part[frac_start:i]
            if i >= n:
                raise ValueError("missing unit letter")
            letter = part[i]
            i += 1
            if letter not in allowed_letters:
                raise ValueError("invalid unit letter")
            tokens.append((num_str, letter))
        return tokens

    date_letters = 'YMWD'  # W handled specially
    time_letters = 'HMS'

    date_tokens = tokenize(date_part, date_letters) if date_part else []
    time_tokens = tokenize(time_part, time_letters) if time_part is not None else []

    # Validate date part
    if date_tokens:
        letters = [t[1] for t in date_tokens]
        if 'W' in letters:
            if len(date_tokens) != 1 or letters[0] != 'W':
                raise ValueError("W must be alone")
        else:
            order = {'Y': 0, 'M': 1, 'D': 2}
            prev = -1
            for _, l in date_tokens:
                idx = order[l]
                if idx <= prev:
                    raise ValueError("date components out of order or repeated")
                prev = idx

    # Validate time part
    if time_tokens:
        order = {'H': 0, 'M': 1, 'S': 2}
        prev = -1
        for _, l in time_tokens:
            idx = order[l]
            if idx <= prev:
                raise ValueError("time components out of order or repeated")
            prev = idx

    if not date_tokens and not time_tokens:
        raise ValueError("no components")

    # Check fraction only on last component overall
    all_tokens = date_tokens + time_tokens
    for idx, (num_str, _) in enumerate(all_tokens):
        has_frac = ('.' in num_str)
        if has_frac and idx != len(all_tokens) - 1:
            raise ValueError("fraction only allowed on last component")

    # Compute seconds
    factors = {
        'Y': 365 * 86400,
        'M_date': 30 * 86400,
        'W': 7 * 86400,
        'D': 86400,
        'H': 3600,
        'M_time': 60,
        'S': 1,
    }

    total = Fraction(0)
    for num_str, letter in date_tokens:
        if letter == 'M':
            factor = factors['M_date']
        else:
            factor = factors[letter]
        total += Fraction(num_str) * factor

    for num_str, letter in time_tokens:
        if letter == 'M':
            factor = factors['M_time']
        else:
            factor = factors[letter]
        total += Fraction(num_str) * factor

    if total.denominator != 1:
        raise ValueError("result is not a whole number of seconds")
    return int(total)

