            pos = m.end()
        return tokens

    date_tokens = tokenize(date_part) if date_part else []
    time_tokens = tokenize(time_part) if time_part is not None else []

    # Validate date part
    date_units = {'Y': 365 * 86400, 'M': 30 * 86400, 'D': 86400}
    date_order = ['Y', 'M', 'D']
    if date_tokens:
        letters = [t[1] for t in date_tokens]
        if 'W' in letters:
            if len(date_tokens) != 1 or letters[0] != 'W':
                raise ValueError("W must be alone")
        else:
            idx = -1
            for letter in letters:
                if letter not in date_order:
                    raise ValueError("invalid date unit")
                i = date_order.index(letter)
                if i <= idx:
                    raise ValueError("date components out of order or repeated")
                idx = i

    # Validate time part
    time_units = {'H': 3600, 'M': 60, 'S': 1}
    time_order = ['H', 'M', 'S']
    if time_tokens:
        idx = -1
        for _, letter in time_tokens:
            if letter not in time_order:
                raise ValueError("invalid time unit")
            i = time_order.index(letter)
            if i <= idx:
                raise ValueError("time components out of order or repeated")
            idx = i

    # Combine with unit info: (num, letter, unit_seconds)
    all_tokens = []
    for num, letter in date_tokens:
        if letter == 'W':
            unit = 7 * 86400
        else:
            unit = date_units[letter]
        all_tokens.append((num, letter, unit))
    for num, letter in time_tokens:
        all_tokens.append((num, letter, time_units[letter]))

    if not all_tokens:
        raise ValueError("no components")

    # Fraction only on last component
    for i, (num, _, _) in enumerate(all_tokens):
        has_frac = ('.' in num) or (',' in num)
        if has_frac and i != len(all_tokens) - 1:
            raise ValueError("fraction only allowed on last component")

    total = Fraction(0)
    for num, _, unit in all_tokens:
        value = Fraction(num.replace(',', '.'))
        total += value * unit

    if total.denominator != 1:
        raise ValueError("not a whole number of seconds")
    return int(total)

import re

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str) or not s.startswith('P'):
        raise ValueError("Invalid ISO 8601 duration")
    body = s[1:]
    if not body:
        raise ValueError("Invalid ISO 8601 duration")

    # Split date and time parts
    if 'T' in body:
        if body.count('T') != 1:
            raise ValueError("Invalid ISO 8601 duration")
        date_part, time_part = body.split('T')
        if not time_part:
            raise ValueError("Invalid ISO 8601 duration")
    else:
        date_part, time_part = body, None

    # Tokenize a part into (number, letter) pairs
    def tokenize(part, allowed_letters):
        tokens = []
        i = 0
        n = len(part)
        while i < n:
            # parse number
            start = i
            while i < n and part[i].isdigit():
                i += 1
            if i == start:
                raise ValueError("Invalid ISO 8601 duration")
            num_str = part[start:i]
            # optional fraction
            frac_str = None
            if i < n and part[i] in '.,':
                sep = part[i]
                i += 1
                fstart = i
                while i < n and part[i].isdigit():
                    i += 1
                if i == fstart:
                    raise ValueError("Invalid ISO 8601 duration")
                frac_str = part[fstart:i]
            # letter
            if i >= n:
                raise ValueError("Invalid ISO 8601 duration")
            letter = part[i]
            i += 1
            if letter not in allowed_letters:
                raise ValueError("Invalid ISO 8601 duration")
            tokens.append((num_str, frac_str, letter))
        return tokens

    # Validate date part
    date_tokens = []
    if date_part:
        date_tokens = tokenize(date_part, set('YMWD'))
        # Check order and uniqueness
        order = {'Y': 0, 'M': 1, 'W': 2, 'D': 3}
        seen = set()
        last_order = -1
        for _, _, letter in date_tokens:
            if letter in seen:
                raise ValueError("Invalid ISO 8601 duration")
            seen.add(letter)
            if order[letter] <= last_order:
                raise ValueError("Invalid ISO 8601 duration")
            last_order = order[letter]
        # Weeks only alone
        if 'W' in seen and len(date_tokens) > 1:
            raise ValueError("Invalid ISO 8601 duration")
        # Fraction only allowed on last component overall
        if time_part is not None:
            for _, frac, _ in date_tokens:
                if frac is not None:
                    raise ValueError("Invalid ISO 8601 duration")
        else:
            for idx, (_, frac, _) in enumerate(date_tokens):
                if frac is not None and idx != len(date_tokens) - 1:
                    raise ValueError("Invalid ISO 8601 duration")

    # Validate time part
    time_tokens = []
    if time_part is not None:
        time_tokens = tokenize(time_part, set('HMS'))
        order = {'H': 0, 'M': 1, 'S': 2}
        seen = set()
        last_order = -1
        for _, _, letter in time_tokens:
            if letter in seen:
                raise ValueError("Invalid ISO 8601 duration")
            seen.add(letter)
            if order[letter] <= last_order:
                raise ValueError("Invalid ISO 8601 duration")
            last_order = order[letter]
        # Fraction only on last component
        for idx, (_, frac, _) in enumerate(time_tokens):
            if frac is not None and idx != len(time_tokens) - 1:
                raise ValueError("Invalid ISO 8601 duration")

    if not date_tokens and not time_tokens:
        raise ValueError("Invalid ISO 8601 duration")

    # Compute total seconds
    total = 0.0
    # Date part
    for num_str, frac_str, letter in date_tokens:
        value = int(num_str)
        if frac_str is not None:
            value += float('0.' + frac_str)
        if letter == 'Y':
            total += value * 365 * 86400
        elif letter == 'M':
            total += value * 30 * 86400
        elif letter == 'W':
            total += value * 7 * 86400
        elif letter == 'D':
            total += value * 86400
    # Time part
    for num_str, frac_str, letter in time_tokens:
        value = int(num_str)
        if frac_str is not None:
            value += float('0.' + frac_str)
        if letter == 'H':
            total += value * 3600
        elif letter == 'M':
            total += value * 60
        elif letter == 'S':
            total += value

    # Inputs with fraction always come to whole seconds
    if abs(total - round(total)) > 1e-9:
        raise ValueError("Invalid ISO 8601 duration")
    return int(round(total))

import re

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str) or not s.startswith('P'):
        raise ValueError("Invalid ISO 8601 duration")

    # Regex for the whole duration
    # Date part: optional Y, M, D in order, or W alone
    # Time part: optional T followed by H, M, S in order
    pattern = re.compile(
        r'^P'
        r'(?:'
            r'(?:(?P<years>\d+)Y)?'
            r'(?:(?P<months>\d+)M)?'
            r'(?:(?P<days>\d+)D)?'
            r'|'
            r'(?P<weeks>\d+)W'
        r')'
        r'(?:T'
            r'(?:(?P<hours>\d+(?:[.,]\d+)?)H)?'
            r'(?:(?P<minutes>\d+(?:[.,]\d+)?)M)?'
            r'(?:(?P<seconds>\d+(?:[.,]\d+)?)S)?'
        r')?'
        r'$'
    )

    m = pattern.match(s)
    if not m:
        raise ValueError("Invalid ISO 8601 duration")

    # Check that at least one component is present
    groups = m.groupdict()
    if all(v is None for v in groups.values()):
        raise ValueError("No components present")

    # If T is present, it must be followed by at least one component
    if 'T' in s:
        # Find the T and check there's something after it
        t_index = s.index('T')
        if t_index == len(s) - 1:
            raise ValueError("T must be followed by at least one component")
        # Also ensure at least one time component matched
        if groups['hours'] is None and groups['minutes'] is None and groups['seconds'] is None:
            raise ValueError("T must be followed by at least one component")

    # Weeks cannot be combined with anything else
    if groups['weeks'] is not None:
        # Ensure no other components
        if any(groups[k] is not None for k in ['years', 'months', 'days', 'hours', 'minutes', 'seconds']):
            raise ValueError("Weeks cannot be combined with other components")

    # Validate fractional part: only last component may have fraction
    # Determine which components are present in order
    components = []
    if groups['years'] is not None:
        components.append(('years', groups['years']))
    if groups['months'] is not None:
        components.append(('months', groups['months']))
    if groups['days'] is not None:
        components.append(('days', groups['days']))
    if groups['weeks'] is not None:
        components.append(('weeks', groups['weeks']))
    if groups['hours'] is not None:
        components.append(('hours', groups['hours']))
    if groups['minutes'] is not None:
        components.append(('minutes', groups['minutes']))
    if groups['seconds'] is not None:
        components.append(('seconds', groups['seconds']))

    # Check fraction only on last component
    for i, (name, val) in enumerate(components):
        if '.' in val or ',' in val:
            if i != len(components) - 1:
                raise ValueError("Fraction only allowed on last component")
            # Validate fraction format: at least one digit on each side
            if not re.match(r'^\d+[.,]\d+$', val):
                raise ValueError("Invalid fractional format")

    # Convert to seconds
    total = 0.0

    def parse_num(val):
        if val is None:
            return 0.0
        return float(val.replace(',', '.'))

    if groups['weeks'] is not None:
        total += parse_num(groups['weeks']) * 7 * 86400
    else:
        total += parse_num(groups['years']) * 365 * 86400
        total += parse_num(groups['months']) * 30 * 86400
        total += parse_num(groups['days']) * 86400

    total += parse_num(groups['hours']) * 3600
    total += parse_num(groups['minutes']) * 60
    total += parse_num(groups['seconds'])

    # Inputs with fraction always come to whole seconds
    if abs(total - round(total)) > 1e-9:
        raise ValueError("Fractional seconds do not result in whole seconds")

    return int(round(total))

