        while pos < len(part):
            m = token_re.match(part, pos)
            if not m:
                raise ValueError("invalid component")
            tokens.append((m.group(1), m.group(2)))
            pos = m.end()
        return tokens

    date_tokens = tokenize(date_part) if date_part else []
    time_tokens = tokenize(time_part) if time_part is not None else []

    if not date_tokens and not time_tokens:
        raise ValueError("no components")

