    date_letters = [l for _, l in date_tokens]
    if 'W' in date_letters:
        if len(date_tokens) != 1 or date_tokens[0][1] != 'W':
            raise ValueError("W must be alone")
        if time_tokens:
            raise ValueError("W cannot combine with time")
    else:
        order = ['Y', 'M', 'D']
        idx = -1
        for _, l in date_tokens:
            if l not in order:
                raise ValueError("invalid date letter")
            i = order.index(l)
            if i <= idx:
                raise ValueError("date order/duplicate")
            idx = i

    # Validate time part
    order_t = ['H', 'M', 'S']
    idx = -1
    for _, l in time_tokens:
        if l not in order_t:
            raise ValueError("invalid time letter")
        i = order_t.index(l)
        if i <= idx:
            raise ValueError("time order/duplicate")
        idx = i

    # Fraction only allowed on last component overall
    all_tokens = date_tokens + time_tokens
    for i, (num, _) in enumerate(all_tokens):
        has_frac = ('.' in num) or (',' in num)
        if has_frac and i != len(all_tokens) - 1:
            raise ValueError("fraction only on last component")

    # Compute seconds
    factors = {
        'Y': 365 * 86400,
        'M': 30 * 86400,   # months in date part
        'W': 7 * 86400,
        'D': 86400,
        'H': 3600,
        'M_t': 60,         # minutes in time part
        'S': 1,
    }

    total = Fraction(0)
    for num, letter in date_tokens:
        num = num.replace(',', '.')
        val = Fraction(num)
        if letter == 'W':
            total += val * factors['W']
        else:
            total += val * factors[letter]

    for num, letter in time_tokens:
        num = num.replace(',', '.')
        val = Fraction(num)
        if letter == 'H':
            total += val * factors['H']
        elif letter == 'M':
            total += val * factors['M_t']
        else:  # S
            total += val * factors['S']

    if total.denominator != 1:
        raise ValueError("not a whole number of seconds")
    return int(total)

