                if k == j + 1:
                    raise ValueError("fraction needs digits after separator")
                num_str += '.' + part[j+1:k]
                j = k
            if j >= n:
                raise ValueError("missing unit letter")
            letter = part[j]
            if letter not in allowed_letters:
                raise ValueError("invalid unit letter")
            tokens.append((num_str, letter))
            i = j + 1
        return tokens

    date_letters = set('YMWD')
    time_letters = set('HMS')

    date_tokens = tokenize(date_part, date_letters) if date_part else []
    time_tokens = tokenize(time_part, time_letters) if time_part is not None else []

    if not date_tokens and not time_tokens:
        raise ValueError("no components")

    # Check ordering and uniqueness
    def check_order(tokens, order):
        seen = set()
        last_idx = -1
        for _, letter in tokens:
            if letter in seen:
                raise ValueError("duplicate letter")
            seen.add(letter)
            idx = order.index(letter)
            if idx <= last_idx:
                raise ValueError("wrong order")
            last_idx = idx

    check_order(date_tokens, ['Y', 'M', 'W', 'D'])
    check_order(time_tokens, ['H', 'M', 'S'])

    # Weeks only on their own
    if any(l == 'W' for _, l in date_tokens):
        if len(date_tokens) != 1 or time_tokens:
            raise ValueError("W must be alone")

    # Fraction only on last component overall
    all_tokens = date_tokens + time_tokens
    for idx, (num_str, _) in enumerate(all_tokens):
        has_frac = ('.' in num_str)
        if has_frac and idx != len(all_tokens) - 1:
            raise ValueError("fraction only allowed on last component")

    # Compute seconds
    factors = {
        'Y': 365 * 86400,
        'M': 30 * 86400,  # months in date part
        'W': 7 * 86400,
        'D': 86400,
        'H': 3600,
        'S': 1,
    }

    total = Fraction(0)
    for num_str, letter in date_tokens:
        if letter == 'M':
            factor = 30 * 86400
        else:
            factor = factors[letter]
        total += Fraction(num_str) * factor

    for num_str, letter in time_tokens:
        if letter == 'M':
            factor = 60
        else:
            factor = factors[letter]
        total += Fraction(num_str) * factor

    if total.denominator != 1:
        raise ValueError("not a whole number of seconds")
    return int(total)

import re
from fractions import Fraction

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    if not s.startswith('P'):
        raise ValueError("must start with P")
    body = s[1:]
    if body == '':
        raise ValueError("empty duration")

    # Split date and time parts
    if 'T' in body:
        if body.count('T') != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split('T')
        if time_part == '':
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Tokenize a part into (number_string, letter) pairs
    def tokenize(part, allowed_letters):
        tokens = []
        i = 0
        n = len(part)
        while i < n:
            # parse number
            start = i
            while i < n and part[i].isdigit():
                i += 1
            if i == start:
                raise ValueError("expected number")
            num = part[start:i]
            # optional fraction
            frac = None
            if i < n and part[i] in '.,':
                sep = part[i]
                i += 1
                fstart = i
                while i < n and part[i].isdigit():
                    i += 1
                if i == fstart:
                    raise ValueError("fraction needs digits")
                frac = part[fstart:i]
                # fraction only allowed on last component; check later
            if i >= n:
                raise ValueError("missing unit letter")
            letter = part[i]
            i += 1
            if letter not in allowed_letters:
                raise ValueError("invalid letter")
            tokens.append((num, frac, letter))
        return tokens

    date_letters = 'YMWD'
    time_letters = 'HMS'

    date_tokens = tokenize(date_part, date_letters) if date_part else []
    time_tokens = tokenize(time_part, time_letters) if time_part is not None else []

    # Validate order and uniqueness
    def validate_order(tokens, order):
        seen = set()
        last_idx = -1
        for _, _, letter in tokens:
            idx = order.index(letter)
            if idx <= last_idx:
                raise ValueError("bad order")
            if letter in seen:
                raise ValueError("duplicate")
            seen.add(letter)
            last_idx = idx

    validate_order(date_tokens, 'YMWD')
    validate_order(time_tokens, 'HMS')

    # Weeks only alone
    if any(l == 'W' for _, _, l in date_tokens):
        if len(date_tokens) != 1 or time_tokens:
            raise ValueError("W must be alone")

    # At least one component
    if not date_tokens and not time_tokens:
        raise ValueError("no components")

    # Fraction only on last component overall
    all_tokens = date_tokens + time_tokens
    for idx, (_, frac, _) in enumerate(all_tokens):
        if frac is not None and idx != len(all_tokens) - 1:
            raise ValueError("fraction only on last component")

    # Compute seconds
    unit_seconds = {
        'Y': 365 * 86400,
        'M': 30 * 86400,   # months in date part
        'W': 7 * 86400,
        'D': 86400,
        'H': 3600,
        'm': 60,           # minutes in time part (lowercase marker)
        'S': 1,
    }

    total = Fraction(0)
    for num, frac, letter in date_tokens:
        key = letter
        val = Fraction(int(num))
        if frac is not None:
            val += Fraction(int(frac), 10 ** len(frac))
        total += val * unit_seconds[key]

    for num, frac, letter in time_tokens:
        key = 'm' if letter == 'M' else letter
        val = Fraction(int(num))
        if frac is not None:
            val += Fraction(int(frac), 10 ** len(frac))
        total += val * unit_seconds[key]

    if total.denominator != 1:
        raise ValueError("not whole seconds")
    return int(total)

import re
from fractions import Fraction

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str) or not s.startswith('P'):
        raise ValueError("Invalid ISO 8601 duration")
    body = s[1:]
    if not body:
        raise ValueError("Empty duration")

    # Split date and time parts
    if 'T' in body:
        if body.count('T') != 1:
            raise ValueError("Multiple T")
        date_part, time_part = body.split('T')
        if not time_part:
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Parse date part
    date_components = []
    if date_part:
        # Weeks only on their own
        if 'W' in date_part:
            if date_part != date_part:  # placeholder
                pass
            m = re.fullmatch(r'(\d+(?:[.,]\d+)?)W', date_part)
            if not m:
                raise ValueError("Invalid week component")
            # Week cannot be combined with anything else
            # Since date_part is only this, and time_part must be None
            if time_part is not None:
                raise ValueError("Week cannot be combined with time")
            num = _parse_number(m.group(1))
            return _to_int_seconds(num * 7 * 86400)
        # Otherwise parse Y M D in order
        pos = 0
        order = ['Y', 'M', 'D']
        idx = 0
        while pos < len(date_part):
            # Find next letter
            m = re.match(r'(\d+(?:[.,]\d+)?)([YMD])', date_part[pos:])
            if not m:
                raise ValueError("Invalid date component")
            num_str, letter = m.group(1), m.group(2)
            # Check order
            if letter not in order[idx:]:
                raise ValueError("Date components out of order or repeated")
            idx = order.index(letter) + 1
            # Check if this is the last component overall
            is_last = (pos + m.end() == len(date_part)) and (time_part is None)
            num = _parse_number(num_str, allow_fraction=is_last)
            date_components.append((letter, num))
            pos += m.end()
        # Check no duplicate letters (already ensured by order)
        # Check at least one component
        if not date_components:
            raise ValueError("No date components")

    # Parse time part
    time_components = []
    if time_part is not None:
        pos = 0
        order = ['H', 'M', 'S']
        idx = 0
        while pos < len(time_part):
            m = re.match(r'(\d+(?:[.,]\d+)?)([HMS])', time_part[pos:])
            if not m:
                raise ValueError("Invalid time component")
            num_str, letter = m.group(1), m.group(2)
            if letter not in order[idx:]:
                raise ValueError("Time components out of order or repeated")
            idx = order.index(letter) + 1
            is_last = (pos + m.end() == len(time_part))
            num = _parse_number(num_str, allow_fraction=is_last)
            time_components.append((letter, num))
            pos += m.end()
        if not time_components:
            raise ValueError("No time components")

    # Compute total seconds
    total = Fraction(0)
    for letter, num in date_components:
        if letter == 'Y':
            total += num * 365 * 86400
        elif letter == 'M':
            total += num * 30 * 86400
        elif letter == 'D':
            total += num * 86400
    for letter, num in time_components:
        if letter == 'H':
            total += num * 3600
        elif letter == 'M':
            total += num * 60
        elif letter == 'S':
            total += num

    return _to_int_seconds(total)


def _parse_number(s: str, allow_fraction: bool = True) -> Fraction:
    if '.' in s or ',' in s:
        if not allow_fraction:
            raise ValueError("Fraction not allowed here")
        # Replace comma with dot
        s = s.replace(',', '.')
        if s.count('.') != 1:
            raise ValueError("Invalid fraction")
        int_part, frac_part = s.split('.')
        if not int_part or not frac_part:
            raise ValueError("Invalid fraction")
        if not int_part.isdigit() or not frac_part.isdigit():
            raise ValueError("Invalid digits")
        return Fraction(int(int_part) * 10**len(frac_part) + int(frac_part), 10**len(frac_part))
    else:
        if not s.isdigit():
            raise ValueError("Invalid number")
        return Fraction(int(s))


def _to_int_seconds(value: Fraction) -> int:
    if value.denominator != 1:
        raise ValueError("Duration does not resolve to whole seconds")
    return int(value)

import re
from fractions import Fraction

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str) or not s.startswith('P'):
        raise ValueError("Invalid ISO 8601 duration")

    # Quick character validation
    if not re.fullmatch(r'[0-9PTYMWDHS.,]+', s):
        raise ValueError("Invalid characters")

    body = s[1:]
    if not body:
        raise ValueError("Empty duration")

    # Split date and time parts
    if 'T' in body:
        if body.count('T') > 1:
            raise ValueError("Multiple T")
        date_part, time_part = body.split('T', 1)
        if not time_part:
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Parse date part
    date_components = []
    if date_part:
        # Check for weeks
        if 'W' in date_part:
            if date_part != date_part:  # placeholder
                pass
            # Weeks must be alone
            m = re.fullmatch(r'(\d+(?:[.,]\d+)?)W', date_part)
            if not m:
                raise ValueError("Invalid week format")
            # Week cannot be fractional? Actually last component may be fractional.
            # But if W is alone, it's the last component, so fraction allowed.
            val = parse_number(m.group(1))
            date_components.append(('W', val))
        else:
            # Parse Y, M, D in order
            pos = 0
            order = ['Y', 'M', 'D']
            idx = 0
            while pos < len(date_part):
                # Find next letter
                m = re.match(r'(\d+(?:[.,]\d+)?)([YMD])', date_part[pos:])
                if not m:
                    raise ValueError("Invalid date component")
                num_str, letter = m.group(1), m.group(2)
                # Check order
                if letter not in order[idx:]:
                    raise ValueError("Invalid order")
                idx = order.index(letter) + 1
                val = parse_number(num_str)
                date_components.append((letter, val))
                pos += m.end()

    # Parse time part
    time_components = []
    if time_part is not None:
        pos = 0
        order = ['H', 'M', 'S']
        idx = 0
        while pos < len(time_part):
            m = re.match(r'(\d+(?:[.,]\d+)?)([HMS])', time_part[pos:])
            if not m:
                raise ValueError("Invalid time component")
            num_str, letter = m.group(1), m.group(2)
            if letter not in order[idx:]:
                raise ValueError("Invalid order")
            idx = order.index(letter) + 1
            val = parse_number(num_str)
            time_components.append((letter, val))
            pos += m.end()

    # Check at least one component
    if not date_components and not time_components:
        raise ValueError("No components")

    # Check fraction only on last component
    all_components = date_components + time_components
    for i, (letter, val) in enumerate(all_components):
        is_fractional = val.denominator != 1
        if is_fractional and i != len(all_components) - 1:
            raise ValueError("Fraction only allowed on last component")

    # Check weeks not combined
    if any(l == 'W' for l, _ in date_components):
        if len(date_components) > 1 or time_components:
            raise ValueError("Weeks cannot be combined")

    # Calculate total seconds
    total = Fraction(0)
    for letter, val in date_components:
        if letter == 'Y':
            total += val * 365 * 86400
        elif letter == 'M':
            total += val * 30 * 86400
        elif letter == 'W':
            total += val * 7 * 86400
        elif letter == 'D':
            total += val * 86400

    for letter, val in time_components:
        if letter == 'H':
            total += val * 3600
        elif letter == 'M':
            total += val * 60
        elif letter == 'S':
            total += val

    if total.denominator != 1:
        raise ValueError("Result is not a whole number of seconds")

    return int(total)

def parse_number(s: str) -> Fraction:
    # Replace comma with dot
    s = s.replace(',', '.')
    if '.' in s:
        # Must have at least one digit on each side
        parts = s.split('.')
        if len(parts) != 2 or not parts[0] or not parts[1]:
            raise ValueError("Invalid fraction")
        if not parts[0].isdigit() or not parts[1].isdigit():
            raise ValueError("Invalid digits")
        return Fraction(int(parts[0] + parts[1]), 10 ** len(parts[1]))
    else:
        if not s.isdigit():
            raise ValueError("Invalid number")
        return Fraction(int(s))

import re
from fractions import Fraction

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    if not s.startswith('P'):
        raise ValueError("must start with P")
    body = s[1:]
    if body == '':
        raise ValueError("empty duration")

    # Split date and time parts
    if 'T' in body:
        if body.count('T') != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split('T')
        if time_part == '':
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Parse date part
    date_components = []  # list of (number_str, letter)
    if date_part:
        # Weeks only on their own
        if 'W' in date_part:
            if not re.fullmatch(r'\d+(?:[.,]\d+)?W', date_part):
                raise ValueError("invalid week component")
            num = date_part[:-1]
            date_components.append((num, 'W'))
        else:
            pos = 0
            for letter in 'YMD':
                m = re.match(r'(\d+(?:[.,]\d+)?)' + letter, date_part[pos:])
                if m:
                    date_components.append((m.group(1), letter))
                    pos += m.end()
            if pos != len(date_part):
                raise ValueError("invalid date part")

    # Parse time part
    time_components = []
    if time_part is not None:
        pos = 0
        for letter in 'HMS':
            m = re.match(r'(\d+(?:[.,]\d+)?)' + letter, time_part[pos:])
            if m:
                time_components.append((m.group(1), letter))
                pos += m.end()
        if pos != len(time_part):
            raise ValueError("invalid time part")
        if not time_components:
            raise ValueError("T must be followed by components")

    all_components = date_components + time_components
    if not all_components:
        raise ValueError("no components")

    # Check letters unique (already ensured by order parsing, but be safe)
    letters = [c[1] for c in all_components]
    if len(letters) != len(set(letters)):
        raise ValueError("duplicate component")

    # Fraction only allowed on last component
    for i, (num, letter) in enumerate(all_components):
        has_frac = ('.' in num) or (',' in num)
        if has_frac and i != len(all_components) - 1:
            raise ValueError("fraction only allowed on last component")
        if has_frac:
            # validate format: digits [.,] digits
            if not re.fullmatch(r'\d+[.,]\d+', num):
                raise ValueError("invalid fractional number")

    # Conversion factors to seconds
    factors = {
        'Y': 365 * 86400,
        'M': 30 * 86400,   # months in date part
        'W': 7 * 86400,
        'D': 86400,
        'H': 3600,
        'S': 1,
    }

    total = Fraction(0)
    for num, letter in all_components:
        # Determine factor: M in time part means minutes
        if letter == 'M' and (num, letter) in time_components:
            factor = 60
        else:
            factor = factors[letter]
        # Normalize decimal separator
        num_norm = num.replace(',', '.')
        total += Fraction(num_norm) * factor

    if total.denominator != 1:
        raise ValueError("not a whole number of seconds")
    return int(total)

import re
from fractions import Fraction

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str) or not s.startswith('P'):
        raise ValueError("Invalid ISO 8601 duration")

    # Regex for the whole duration
    # Date part: optional, components Y M D or W alone
    # Time part: optional T followed by H M S
    pattern = re.compile(
        r'^P'
        r'(?:(?P<weeks>\d+(?:[.,]\d+)?)W|'
        r'(?:(?P<years>\d+(?:[.,]\d+)?)Y)?'
        r'(?:(?P<months>\d+(?:[.,]\d+)?)M)?'
        r'(?:(?P<days>\d+(?:[.,]\d+)?)D)?'
        r')?'
        r'(?:T'
        r'(?:(?P<hours>\d+(?:[.,]\d+)?)H)?'
        r'(?:(?P<minutes>\d+(?:[.,]\d+)?)M)?'
        r'(?:(?P<seconds>\d+(?:[.,]\d+)?)S)?'
        r')?'
        r'$'
    )

    m = pattern.match(s)
    if not m:
        raise ValueError("Invalid ISO 8601 duration")

    groups = m.groupdict()

    # Check at least one component present
    if all(v is None for v in groups.values()):
        raise ValueError("No components")

    # Check T followed by at least one component
    if 'T' in s:
        # Find position of T
        t_pos = s.index('T')
        # After T must have at least one component
        after_t = s[t_pos+1:]
        if not after_t:
            raise ValueError("T must be followed by at least one component")
        # Check that after_t contains at least one letter
        if not re.search(r'[HMS]', after_t):
            raise ValueError("T must be followed by at least one component")

    # Check weeks cannot be combined
    if groups['weeks'] is not None:
        # If weeks present, no other components allowed
        others = ['years', 'months', 'days', 'hours', 'minutes', 'seconds']
        if any(groups[k] is not None for k in others):
            raise ValueError("Weeks cannot be combined with other components")

    # Check fractional part only on last component
    # Find all components in order
    components = []
    for name in ['weeks', 'years', 'months', 'days', 'hours', 'minutes', 'seconds']:
        if groups[name] is not None:
            components.append((name, groups[name]))

    # Check that only last component has fraction
    for i, (name, val) in enumerate(components):
        has_frac = '.' in val or ',' in val
        if has_frac and i != len(components) - 1:
            raise ValueError("Only last component may have fractional part")

    # Convert to seconds
    total = Fraction(0)

    def parse_num(val):
        if val is None:
            return Fraction(0)
        val = val.replace(',', '.')
        return Fraction(val)

    if groups['weeks'] is not None:
        total += parse_num(groups['weeks']) * 7 * 86400
    else:
        if groups['years'] is not None:
            total += parse_num(groups['years']) * 365 * 86400
        if groups['months'] is not None:
            total += parse_num(groups['months']) * 30 * 86400
        if groups['days'] is not None:
            total += parse_num(groups['days']) * 86400

    if groups['hours'] is not None:
        total += parse_num(groups['hours']) * 3600
    if groups['minutes'] is not None:
        total += parse_num(groups['minutes']) * 60
    if groups['seconds'] is not None:
        total += parse_num(groups['seconds'])

    # Must be whole number of seconds
    if total.denominator != 1:
        raise ValueError("Duration does not resolve to whole seconds")

    return int(total)

import re
from fractions import Fraction


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("input must be a string")
    if not s.startswith("P"):
        raise ValueError("duration must start with P")

    body = s[1:]
    if body == "":
        raise ValueError("empty duration")

    # Split date and time parts
    if "T" in body:
        if body.count("T") != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split("T")
        if time_part == "":
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Tokenize a part into (number_string, letter) pairs
    token_re = re.compile(r"(\d+(?:[.,]\d+)?)([A-Z])")

    def tokenize(part: str):
        tokens = []
        pos = 0
        while pos < len(part):
            m = token_re.match(part, pos)
            if not m:
                raise ValueError("invalid component")
            tokens.append((m.group(1), m.group(2)))
            pos = m.end()
        return tokens

    date_tokens = tokenize(date_part) if date_part else []
    time_tokens = tokenize(time_part) if time_part is not None else []

    if not date_tokens and not time_tokens:
        raise ValueError("no components")

    # Validate date part
    date_letters = [t[1] for t in date_tokens]
    if "W" in date_letters:
        if len(date_tokens) != 1 or date_letters != ["W"]:
            raise ValueError("W must be alone")
        if time_tokens:
            raise ValueError("W cannot be combined with time")
    else:
        order = ["Y", "M", "D"]
        idx = 0
        for letter in date_letters:
            if letter not in order:
                raise ValueError("invalid date letter")
            i = order.index(letter)
            if i < idx:
                raise ValueError("date components out of order")
            idx = i + 1

    # Validate time part
    time_order = ["H", "M", "S"]
    idx = 0
    for letter in [t[1] for t in time_tokens]:
        if letter not in time_order:
            raise ValueError("invalid time letter")
        i = time_order.index(letter)
        if i < idx:
            raise ValueError("time components out of order")
        idx = i + 1

    # Combine tokens in order: date then time
    all_tokens = date_tokens + time_tokens

    # Only the last component may have a fraction
    for num, _ in all_tokens[:-1]:
        if "." in num or "," in num:
            raise ValueError("fraction only allowed on last component")

    # Convert to seconds
    factors = {
        "Y": 365 * 86400,
        "M_date": 30 * 86400,
        "W": 7 * 86400,
        "D": 86400,
        "H": 3600,
        "M_time": 60,
        "S": 1,
    }

    total = Fraction(0)
    for i, (num, letter) in enumerate(all_tokens):
        num = num.replace(",", ".")
        value = Fraction(num)
        if letter == "M":
            key = "M_date" if i < len(date_tokens) else "M_time"
        else:
            key = letter
        total += value * factors[key]

    if total.denominator != 1:
        raise ValueError("duration is not a whole number of seconds")
    return int(total)

