        date_part, time_part = body.split('T')
        if time_part == '':
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Regex for a single component: number + letter
    # number: digits, optionally fraction on last component only
    comp_re = re.compile(r'^(\d+)(?:[.,](\d+))?([YMWDHS])$')

    def parse_components(part, allowed_letters, is_time):
        """Parse a sequence of components. Returns list of (value, letter)."""
        if part == '':
            return []
        comps = []
        i = 0
        n = len(part)
        while i < n:
            # find next letter
            j = i
            while j < n and part[j].isdigit():
                j += 1
            if j == i:
                raise ValueError("expected number")
            # check for fraction
            frac = None
            if j < n and part[j] in '.,':
                k = j + 1
                while k < n and part[k].isdigit():
                    k += 1
                if k == j + 1:
                    raise ValueError("fraction needs digits")
                frac = part[j+1:k]
                j = k
            if j >= n:
                raise ValueError("missing letter")
            letter = part[j]
            if letter not in allowed_letters:
                raise ValueError("invalid letter")
            num_str = part[i:j]
            # num_str may include fraction
            if frac is not None:
                # ensure fraction only on last component
                if j + 1 != n:
                    raise ValueError("fraction only on last component")
                # parse number with fraction
                # num_str is like "1.5" or "1,5"
                # Actually num_str includes the fraction part because we set j after fraction
                # Let's re-extract properly
                # We need to reconstruct: integer part + fraction
                # Find the dot/comma position
                m = re.match(r'^(\d+)(?:[.,](\d+))?$', num_str)
                if not m:
                    raise ValueError("bad number")
                int_part = m.group(1)
                frac_part = m.group(2)
                if frac_part is None:
                    # shouldn't happen
                    raise ValueError("bad fraction")
                value = Fraction(int(int_part) * 10**len(frac_part) + int(frac_part), 10**len(frac_part))
            else:
                value = Fraction(int(num_str))
            comps.append((value, letter))
            i = j + 1
        return comps

    # Validate date part
    date_letters = 'YMWD'
    date_comps = parse_components(date_part, date_letters, False)

    # Check weeks rule
    if any(l == 'W' for _, l in date_comps):
        if len(date_comps) != 1:
            raise ValueError("W cannot be combined")
        if time_part is not None:
            raise ValueError("W cannot be combined with time")

    # Check order and uniqueness for date
    order = {'Y': 0, 'M': 1, 'W': 2, 'D': 3}
    seen = set()
    last_order = -1
    for val, letter in date_comps:
        if letter in seen:
            raise ValueError("duplicate letter")
        seen.add(letter)
        o = order[letter]
        if o <= last_order:
            raise ValueError("wrong order")
        last_order = o

    # Validate time part
    time_comps = []
    if time_part is not None:
        time_letters = 'HMS'
        time_comps = parse_components(time_part, time_letters, True)
        order_t = {'H': 0, 'M': 1, 'S': 2}
        seen_t = set()
        last_order_t = -1
        for val, letter in time_comps:
            if letter in seen_t:
                raise ValueError("duplicate letter")
            seen_t.add(letter)
            o = order_t[letter]
            if o <= last_order_t:
                raise ValueError("wrong order")
            last_order_t = o

    # At least one component total
    if not date_comps and not time_comps:
        raise ValueError("no components")

    # Check fraction only on last component overall
    all_comps = date_comps + time_comps
    for idx, (val, letter) in enumerate(all_comps):
        # Check if this value has a fractional part
        if val.denominator != 1:
            if idx != len(all_comps) - 1:
                raise ValueError("fraction only on last component")

    # Compute total seconds
    total = Fraction(0)
    for val, letter in date_comps:
        if letter == 'Y':
            total += val * 365 * 86400
        elif letter == 'M':
            total += val * 30 * 86400
        elif letter == 'W':
            total += val * 7 * 86400
        elif letter == 'D':
            total += val * 86400
    for val, letter in time_comps:
        if letter == 'H':
            total += val * 3600
        elif letter == 'M':
            total += val * 60
        elif letter == 'S':
            total += val

    if total.denominator != 1:
        raise ValueError("not whole seconds")
    return int(total)

import re
from fractions import Fraction


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    if not s.startswith('P'):
        raise ValueError("must start with P")
    body = s[1:]
    if body == '':
        raise ValueError("empty duration")

    # Split date and time parts
    if 'T' in body:
        if body.count('T') != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split('T')
        if time_part == '':
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Tokenize a part into (number, letter) pairs
    token_re = re.compile(r'(\d+(?:[.,]\d+)?)([A-Z])')

    def tokenize(part):
        tokens = []
        pos = 0
        while pos < len(part):
            m = token_re.match(part, pos)
            if not m:
                raise ValueError("invalid token")
            tokens.append((m.group(1), m.group(2)))
            pos = m.end()
        return tokens

    date_tokens = tokenize(date_part) if date_part else []
    time_tokens = tokenize(time_part) if time_part is not None else []

    # Validate date part
    date_letters = [t[1] for t in date_tokens]
    if 'W' in date_letters:
        if len(date_tokens) != 1 or date_tokens[0][1] != 'W':
            raise ValueError("W must be alone")
        if time_tokens:
            raise ValueError("W cannot combine with time")
    else:
        order = ['Y', 'M', 'D']
        idx = -1
        for letter in date_letters:
            if letter not in order:
                raise ValueError("invalid date letter")
            j = order.index(letter)
            if j <= idx:
                raise ValueError("date order/duplicate")
            idx = j

    # Validate time part
    time_order = ['H', 'M', 'S']
    idx = -1
    for letter in [t[1] for t in time_tokens]:
        if letter not in time_order:
            raise ValueError("invalid time letter")
        j = time_order.index(letter)
        if j <= idx:
            raise ValueError("time order/duplicate")
        idx = j

    # At least one component
    if not date_tokens and not time_tokens:
        raise ValueError("no components")

    # Fraction only allowed on the very last component overall
    all_tokens = date_tokens + time_tokens
    for i, (num, _) in enumerate(all_tokens):
        has_frac = ('.' in num) or (',' in num)
        if has_frac and i != len(all_tokens) - 1:
            raise ValueError("fraction only on last component")

    # Compute seconds
    factors = {
        'Y': 365 * 86400,
        'M_date': 30 * 86400,
        'W': 7 * 86400,
        'D': 86400,
        'H': 3600,
        'M_time': 60,
        'S': 1,
    }

    total = Fraction(0)
    for num, letter in date_tokens:
        val = Fraction(num.replace(',', '.'))
        if letter == 'Y':
            total += val * factors['Y']
        elif letter == 'M':
            total += val * factors['M_date']
        elif letter == 'W':
            total += val * factors['W']
        elif letter == 'D':
            total += val * factors['D']
        else:
            raise ValueError("bad date letter")

    for num, letter in time_tokens:
        val = Fraction(num.replace(',', '.'))
        if letter == 'H':
            total += val * factors['H']
        elif letter == 'M':
            total += val * factors['M_time']
        elif letter == 'S':
            total += val * factors['S']
        else:
            raise ValueError("bad time letter")

    # Truncate toward zero to a whole number of seconds
    return int(total)

import re
from fractions import Fraction

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    if not s.startswith('P'):
        raise ValueError("must start with P")
    body = s[1:]
    if body == '':
        raise ValueError("empty duration")

    # Split date and time parts
    if 'T' in body:
        if body.count('T') != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split('T')
        if time_part == '':
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Tokenize a part into (number_string, letter) pairs
    def tokenize(part, allowed_letters):
        tokens = []
        i = 0
        n = len(part)
        while i < n:
            # parse number
            j = i
            while j < n and part[j].isdigit():
                j += 1
            if j == i:
                raise ValueError("expected number")
            num_str = part[i:j]
            # optional fraction
            if j < n and part[j] in '.,':
                sep = part[j]
                k = j + 1
                while k < n and part[k].isdigit():
                    k += 1
                if k == j + 1:
                    raise ValueError("fraction needs digits")
                num_str += '.' + part[j+1:k]
                j = k
            if j >= n:
                raise ValueError("missing unit letter")
            letter = part[j]
            if letter not in allowed_letters:
                raise ValueError("invalid unit")
            tokens.append((num_str, letter))
            i = j + 1
        return tokens

    # Validate date part
    date_tokens = []
    if date_part:
        # Check for weeks: W only allowed alone
        if 'W' in date_part:
            # must be exactly one component, a number followed by W
            m = re.fullmatch(r'(\d+(?:[.,]\d+)?)W', date_part)
            if not m:
                raise ValueError("invalid week usage")
            # weeks cannot be combined
            date_tokens = [(m.group(1), 'W')]
        else:
            date_tokens = tokenize(date_part, set('YMD'))
            # check order and uniqueness
            order = {'Y': 0, 'M': 1, 'D': 2}
            last = -1
            seen = set()
            for _, letter in date_tokens:
                if letter in seen:
                    raise ValueError("duplicate unit")
                seen.add(letter)
                idx = order[letter]
                if idx <= last:
                    raise ValueError("wrong order")
                last = idx

    # Validate time part
    time_tokens = []
    if time_part is not None:
        time_tokens = tokenize(time_part, set('HMS'))
        order = {'H': 0, 'M': 1, 'S': 2}
        last = -1
        seen = set()
        for _, letter in time_tokens:
            if letter in seen:
                raise ValueError("duplicate unit")
            seen.add(letter)
            idx = order[letter]
            if idx <= last:
                raise ValueError("wrong order")
            last = idx

    # At least one component overall
    if not date_tokens and not time_tokens:
        raise ValueError("no components")

    # Check fraction: only last component overall may have fraction
    all_tokens = date_tokens + time_tokens
    for idx, (num_str, _) in enumerate(all_tokens):
        has_frac = ('.' in num_str)
        if has_frac and idx != len(all_tokens) - 1:
            raise ValueError("fraction only allowed on last component")

    # Compute seconds
    # Conversion factors to seconds
    factors = {
        'Y': 365 * 86400,
        'M': 30 * 86400,   # month in date part
        'W': 7 * 86400,
        'D': 86400,
        'H': 3600,
        'm': 60,           # minutes (we'll use 'm' internally for time M)
        'S': 1,
    }

    total = Fraction(0)
    for num_str, letter in date_tokens:
        if letter == 'M':
            factor = factors['M']
        else:
            factor = factors[letter]
        total += Fraction(num_str) * factor

    for num_str, letter in time_tokens:
        if letter == 'M':
            factor = 60
        else:
            factor = factors[letter]
        total += Fraction(num_str) * factor

    if total.denominator != 1:
        raise ValueError("not a whole number of seconds")
    return int(total)

import re
from fractions import Fraction

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    if not s.startswith('P'):
        raise ValueError("must start with P")
    body = s[1:]
    if body == '':
        raise ValueError("empty duration")

    # Split date and time parts
    if 'T' in body:
        if body.count('T') != 1:
            raise ValueError("multiple T")
        date_part, time_part = body.split('T')
        if time_part == '':
            raise ValueError("T must be followed by components")
    else:
        date_part, time_part = body, None

    # Parse date part
    date_units = {'Y': 365*86400, 'M': 30*86400, 'D': 86400}
    date_order = ['Y', 'M', 'D']
    time_units = {'H': 3600, 'M': 60, 'S': 1}
    time_order = ['H', 'M', 'S']

    def parse_components(part, order, units, allow_week=False):
        # returns list of (value_str, letter)
        comps = []
        i = 0
        n = len(part)
        while i < n:
            # parse number
            j = i
            while j < n and part[j].isdigit():
                j += 1
            if j == i:
                raise ValueError("expected number")
            num_str = part[i:j]
            # optional fraction
            if j < n and part[j] in '.,':
                k = j + 1
                while k < n and part[k].isdigit():
                    k += 1
                if k == j + 1:
                    raise ValueError("fraction needs digits")
                num_str = part[i:k]
                j = k
            if j >= n:
                raise ValueError("missing unit letter")
            letter = part[j]
            if letter not in units and not (allow_week and letter == 'W'):
                raise ValueError("invalid unit")
            comps.append((num_str, letter))
            i = j + 1
        return comps

    total = Fraction(0)

    if date_part:
        comps = parse_components(date_part, date_order, date_units, allow_week=True)
        if not comps:
            raise ValueError("empty date part")
        # check weeks
        letters = [c[1] for c in comps]
        if 'W' in letters:
            if len(comps) != 1:
                raise ValueError("W must be alone")
            num_str = comps[0][0]
            val = parse_number(num_str)
            total += val * 7 * 86400
        else:
            # check order and uniqueness
            last_idx = -1
            seen = set()
            for num_str, letter in comps:
                if letter in seen:
                    raise ValueError("duplicate unit")
                seen.add(letter)
                idx = date_order.index(letter)
                if idx <= last_idx:
                    raise ValueError("wrong order")
                last_idx = idx
            # fraction only on last component overall
            for idx, (num_str, letter) in enumerate(comps):
                val = parse_number(num_str)
                total += val * date_units[letter]

    if time_part is not None:
        comps = parse_components(time_part, time_order, time_units)
        if not comps:
            raise ValueError("empty time part")
        last_idx = -1
        seen = set()
        for num_str, letter in comps:
            if letter in seen:
                raise ValueError("duplicate unit")
            seen.add(letter)
            idx = time_order.index(letter)
            if idx <= last_idx:
                raise ValueError("wrong order")
            last_idx = idx
        for num_str, letter in comps:
            val = parse_number(num_str)
            total += val * time_units[letter]

    # Check fraction only on last component overall
    # We need to know which component is last in the whole string
    # Re-parse to find last component's number string
    # Simpler: check that only the last component in the entire string has a fraction
    # We'll reconstruct by checking each part
    all_comps = []
    if date_part:
        all_comps.extend(parse_components(date_part, date_order, date_units, allow_week=True))
    if time_part is not None:
        all_comps.extend(parse_components(time_part, time_order, time_units))
    for idx, (num_str, letter) in enumerate(all_comps):
        has_frac = ('.' in num_str or ',' in num_str)
        if has_frac and idx != len(all_comps) - 1:
            raise ValueError("fraction only allowed on last component")

    if total.denominator != 1:
        raise ValueError("not whole seconds")
    return int(total)

def parse_number(num_str: str) -> Fraction:
    if '.' in num_str or ',' in num_str:
        # replace comma with dot
        s = num_str.replace(',', '.')
        if s.count('.') != 1:
            raise ValueError("invalid fraction")
        int_part, frac_part = s.split('.')
        if not int_part.isdigit() or not frac_part.isdigit():
            raise ValueError("invalid number")
        return Fraction(int(int_part) * (10**len(frac_part)) + int(frac_part), 10**len(frac_part))
    else:
        if not num_str.isdigit():
            raise ValueError("invalid number")
        return Fraction(int(num_str))

def parse_roman(s: str) -> int:
    if not s:
        raise ValueError("empty string is not a Roman numeral")

    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    # Validate characters
    for ch in s:
        if ch not in values:
            raise ValueError(f"invalid character: {ch!r}")

    # Build the canonical representation for every number 1..3999
    def to_roman(n: int) -> str:
        thousands = ["", "M", "MM", "MMM"]
        hundreds = ["", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"]
        tens = ["", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"]
        units = ["", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"]
        return (
            thousands[n // 1000]
            + hundreds[(n // 100) % 10]
            + tens[(n // 10) % 10]
            + units[n % 10]
        )

    # Direct validation against canonical forms
    for n in range(1, 4000):
        if to_roman(n) == s:
            return n

    raise ValueError(f"invalid Roman numeral: {s!r}")

def parse_roman(s: str) -> int:
    if not s or not isinstance(s, str):
        raise ValueError("Invalid Roman numeral")
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    if any(ch not in values for ch in s):
        raise ValueError("Invalid Roman numeral")
    total = 0
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if i + 1 < n:
            pair = s[i:i+2]
            if pair in ('IV', 'IX', 'XL', 'XC', 'CD', 'CM'):
                total += values[s[i+1]] - values[ch]
                i += 2
                continue
        total += values[ch]
        i += 1
    # Verify canonical form by re-encoding
    if to_roman(total) != s:
        raise ValueError("Invalid Roman numeral")
    return total


def to_roman(num: int) -> str:
    if not (1 <= num <= 3999):
        raise ValueError("Out of range")
    table = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]
    result = []
    for value, symbol in table:
        while num >= value:
            result.append(symbol)
            num -= value
    return ''.join(result)

def parse_roman(s: str) -> int:
    if not isinstance(s, str) or not s:
        raise ValueError("empty or non-string input")
    if any(c not in "IVXLCDM" for c in s):
        raise ValueError("invalid character")

    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}

    # Build the canonical representation for every value 1..3999.
    def to_roman(n: int) -> str:
        table = [
            (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
            (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
            (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
        ]
        out = []
        for v, sym in table:
            while n >= v:
                out.append(sym)
                n -= v
        return "".join(out)

    # Compute the value using the standard subtractive rule.
    total = 0
    i = 0
    n = len(s)
    while i < n:
        cur = values[s[i]]
        if i + 1 < n and values[s[i + 1]] > cur:
            total += values[s[i + 1]] - cur
            i += 2
        else:
            total += cur
            i += 1

    if total < 1 or total > 3999:
        raise ValueError("out of range")
    if to_roman(total) != s:
        raise ValueError("not a canonical Roman numeral")
    return total

