                i += 2
                continue
        total += values[ch]
        i += 1

    if not (1 <= total <= 3999):
        raise ValueError("Invalid Roman numeral")

    # Canonical check: rebuild the numeral from the integer.
    def to_roman(num: int) -> str:
        table = [
            (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
            (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
            (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
        ]
        out = []
        for val, sym in table:
            while num >= val:
                out.append(sym)
                num -= val
        return "".join(out)

    if to_roman(total) != s:
        raise ValueError("Invalid Roman numeral")

    return total

def parse_roman(s: str) -> int:
    if not s:
        raise ValueError("empty string")
    if any(c not in "IVXLCDM" for c in s):
        raise ValueError("invalid characters")

    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}

    # Validate structure with a regex-like manual check.
    # Thousands: M{1,3}
    i = 0
    n = len(s)
    while i < n and s[i] == "M":
        i += 1
    if i > 3:
        raise ValueError("too many M")

    def parse_part(seq, one, five, ten):
        # seq is the remaining string starting at current position
        # returns (value, consumed)
        if seq.startswith(one + ten):
            return 9, 2
        if seq.startswith(one + five):
            return 4, 2
        if seq.startswith(five):
            # V, VI, VII, VIII
            j = 1
            while j < len(seq) and j <= 3 and seq[j] == one:
                j += 1
            return 5 + (j - 1), j
        if seq.startswith(one):
            j = 1
            while j < len(seq) and j < 3 and seq[j] == one:
                j += 1
            return j, j
        return 0, 0

    total = i * 1000
    rest = s[i:]

    for one, five, ten in (("C", "D", "M"), ("X", "L", "C"), ("I", "V", "X")):
        val, used = parse_part(rest, one, five, ten)
        total += val
        rest = rest[used:]

    if rest:
        raise ValueError("invalid numeral")

    # Final sanity: canonical form check
    def to_roman(num):
        table = [
            (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
            (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
            (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
        ]
        out = []
        for v, sym in table:
            while num >= v:
                out.append(sym)
                num -= v
        return "".join(out)

    if not (1 <= total <= 3999) or to_roman(total) != s:
        raise ValueError("invalid numeral")

    return total

def parse_roman(s: str) -> int:
    if not isinstance(s, str) or not s:
