import re

def parse_roman(s: str) -> int:
    if not isinstance(s, str) or not s:
        raise ValueError("empty or non-string input")
    pattern = re.compile(
        r'^(M{0,3})'
        r'(CM|CD|D?C{0,3})'
        r'(XC|XL|L?X{0,3})'
        r'(IX|IV|V?I{0,3})$'
    )
    m = pattern.match(s)
    if not m:
        raise ValueError(f"invalid Roman numeral: {s!r}")
    values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000,
    }
    total = 0
    prev = 0
    for ch in reversed(s):
        v = values[ch]
        if v < prev:
            total -= v
        else:
            total += v
            prev = v
    if not (1 <= total <= 3999):
        raise ValueError(f"out of range: {s!r}")
    return total

def parse_roman(s: str) -> int:
    if not s:
        raise ValueError("empty string is not a Roman numeral")

    values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000,
    }

    # Validate characters
    for ch in s:
        if ch not in values:
            raise ValueError(f"invalid character: {ch!r}")

    # Validate structure using a strict grammar:
    # thousands: M{0,3}
    # hundreds: (C{0,3}|CD|CM|D?C{0,3}) but must be one of the canonical forms
    # tens:     (X{0,3}|XL|XC|L?X{0,3})
    # units:    (I{0,3}|IV|IX|V?I{0,3})
    #
    # We'll match greedily with a small parser.

    i = 0
    n = len(s)

    def match_count(ch, max_count):
        nonlocal i
        count = 0
        while i < n and s[i] == ch and count < max_count:
            i += 1
            count += 1
        return count

    # Thousands
    thousands = match_count('M', 3)

    # Hundreds
    hundreds = 0
    if i < n:
        if s.startswith('CM', i):
            hundreds = 900
            i += 2
        elif s.startswith('CD', i):
            hundreds = 400
            i += 2
        elif i < n and s[i] == 'D':
            hundreds = 500
            i += 1
            c = match_count('C', 3)
            hundreds += c * 100
        else:
            c = match_count('C', 3)
            hundreds = c * 100

    # Tens
    tens = 0
    if i < n:
        if s.startswith('XC', i):
            tens = 90
            i += 2
        elif s.startswith('XL', i):
            tens = 40
            i += 2
        elif i < n and s[i] == 'L':
            tens = 50
            i += 1
            x = match_count('X', 3)
            tens += x * 10
        else:
            x = match_count('X', 3)
            tens = x * 10

    # Units
    units = 0
    if i < n:
        if s.startswith('IX', i):
            units = 9
            i += 2
        elif s.startswith('IV', i):
            units = 4
            i += 2
        elif i < n and s[i] == 'V':
            units = 5
            i += 1
            i_count = match_count('I', 3)
            units += i_count
        else:
            i_count = match_count('I', 3)
            units = i_count

    if i != n:
        raise ValueError(f"invalid Roman numeral: {s!r}")

    total = thousands * 1000 + hundreds + tens + units
    if total < 1 or total > 3999:
        raise ValueError(f"Roman numeral out of range: {s!r}")

    return total

