def parse_roman(s: str) -> int:
    if not s:
        raise ValueError("empty string is not a Roman numeral")

    values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000,
    }

    # Validate characters
    for ch in s:
        if ch not in values:
            raise ValueError(f"invalid character: {ch!r}")

    # Build the canonical forms for each place value.
    ones = ["", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"]
    tens = ["", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"]
    hundreds = ["", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"]
    thousands = ["", "M", "MM", "MMM"]

    # Try all numbers 1..3999 and see if the canonical form matches.
    for n in range(1, 4000):
        t, rem = divmod(n, 1000)
        h, rem = divmod(rem, 100)
        te, u = divmod(rem, 10)
        canonical = thousands[t] + hundreds[h] + tens[te] + ones[u]
        if canonical == s:
            return n

    raise ValueError(f"invalid Roman numeral: {s!r}")

