def parse_csv_line(line: str) -> list[str]:
    fields = []
    i = 0
    n = len(line)

    while True:
        if i < n and line[i] == '"':
            # Quoted field
            i += 1
            chars = []
            while True:
                if i >= n:
                    raise ValueError("unclosed quoted field")
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    chars.append(c)
                    i += 1
            fields.append(''.join(chars))
            if i < n:
                if line[i] != ',':
                    raise ValueError("expected comma after closing quote")
                i += 1
                if i == n:
                    fields.append('')
                    break
            else:
                break
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',':
                if line[i] == '"':
                    raise ValueError("quote in unquoted field")
                i += 1
            fields.append(line[start:i])
            if i < n:
                i += 1
                if i == n:
                    fields.append('')
                    break
            else:
                break

    return fields

