def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # dp[i][j] = LCS length of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    # Precompute next occurrence arrays
    # next_a[i][c] = smallest index >= i where a[index] == c, else -1
    next_a = [[-1] * 26 for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for c in range(26):
            next_a[i][c] = next_a[i + 1][c]
        next_a[i][ord(a[i]) - 97] = i

    next_b = [[-1] * 26 for _ in range(m + 1)]
    for j in range(m - 1, -1, -1):
        for c in range(26):
            next_b[j][c] = next_b[j + 1][c]
        next_b[j][ord(b[j]) - 97] = j

    # Reconstruct lexicographically smallest LCS
    res = []
    i = j = 0
    while dp[i][j] > 0:
        for c in range(26):
            i2 = next_a[i][c]
            if i2 == -1:
                continue
            j2 = next_b[j][c]
            if j2 == -1:
                continue
            if 1 + dp[i2 + 1][j2 + 1] == dp[i][j]:
                res.append(chr(c + 97))
                i = i2 + 1
                j = j2 + 1
                break

    return "".join(res)

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # dp[i][j] = LCS length of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    # Precompute next occurrence for each char in a and b
    # next_a[i][c] = smallest index >= i where a[index] == c, or n if none
    next_a = [[n] * 26 for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for c in range(26):
            next_a[i][c] = next_a[i + 1][c]
