def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # next_row[j] = best LCS of a[i+1:] and b[j:]
    # curr_row[j] = best LCS of a[i:]   and b[j:]
    next_row = [""] * (m + 1)

    for i in range(n - 1, -1, -1):
        curr_row = [""] * (m + 1)
        ai = a[i]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                len1 = 1 + len(next_row[j + 1])
            else:
                len1 = -1
            len2 = len(next_row[j])
            len3 = len(curr_row[j + 1])

            max_len = len1
            if len2 > max_len:
                max_len = len2
            if len3 > max_len:
                max_len = len3

            # Fast paths when only one candidate achieves the max length.
            if len1 == max_len and len2 < max_len and len3 < max_len:
                curr_row[j] = ai + next_row[j + 1]
            elif len2 == max_len and len1 < max_len and len3 < max_len:
                curr_row[j] = next_row[j]
            elif len3 == max_len and len1 < max_len and len2 < max_len:
                curr_row[j] = curr_row[j + 1]
            else:
                # Tie: compare the actual strings.
                best = None
                if len1 == max_len:
                    best = ai + next_row[j + 1]
                if len2 == max_len:
                    cand = next_row[j]
                    if best is None or cand < best:
                        best = cand
                if len3 == max_len:
                    cand = curr_row[j + 1]
                    if best is None or cand < best:
                        best = cand
                curr_row[j] = best
        next_row = curr_row

    return next_row[0]

