def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # suf[i][j] = LCS length of a[i:] and b[j:]
    suf = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                suf[i][j] = suf[i+1][j+1] + 1
            else:
                suf[i][j] = max(suf[i+1][j], suf[i][j+1])

    L = suf[0][0]
    if L == 0:
        return ""

    # next occurrence arrays
    next_a = [[n] * 26 for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for c in range(26):
            next_a[i][c] = next_a[i+1][c]
        next_a[i][ord(a[i]) - ord('a')] = i

    next_b = [[m] * 26 for _ in range(m + 1)]
    for j in range(m - 1, -1, -1):
        for c in range(26):
            next_b[j][c] = next_b[j+1][c]
        next_b[j][ord(b[j]) - ord('a')] = j

    i = j = 0
    res = []
    remaining = L
    while remaining > 0:
        for c in range(26):
            ni = next_a[i][c]
            nj = next_b[j][c]
            if ni < n and nj < m:
                if 1 + suf[ni+1][nj+1] >= remaining:
                    res.append(chr(c + ord('a')))
                    i = ni + 1
                    j = nj + 1
                    remaining -= 1
                    break
    return "".join(res)

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # dp[i][j] = LCS length of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    if dp[0][0] == 0:
        return ""

    # Precompute next occurrence of each character
    # next_a[i][c] = smallest index >= i where a[index] == c, or n if none
    # We'll use dict for characters present, but for lexicographic order we need sorted unique chars
    chars = sorted(set(a) & set(b))
    if not chars:
        return ""

    # Map char to index for quick lookup
    char_to_idx = {c: idx for idx, c in enumerate(chars)}
    k = len(chars)

    next_a = [[n] * k for _ in range(n + 1)]
    next_b = [[m] * k for _ in range(m + 1)]

    # Fill from the end
    for i in range(n - 1, -1, -1):
        for ci in range(k):
            next_a[i][ci] = next_a[i + 1][ci]
        if a[i] in char_to_idx:
            next_a[i][char_to_idx[a[i]]] = i

    for j in range(m - 1, -1, -1):
        for ci in range(k):
            next_b[j][ci] = next_b[j + 1][ci]
        if b[j] in char_to_idx:
            next_b[j][char_to_idx[b[j]]] = j

    # Reconstruct
    res = []
    i, j = 0, 0
    while i < n and j < m and dp[i][j] > 0:
        for ci in range(k):
            ia = next_a[i][ci]
            jb = next_b[j][ci]
            if ia < n and jb < m:
                if 1 + dp[ia + 1][jb + 1] == dp[i][j]:
                    res.append(chars[ci])
                    i = ia + 1
                    j = jb + 1
                    break
        else:
            # Should not happen if dp[i][j] > 0
            break

    return "".join(res)

