                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    if dp[0][0] == 0:
        return ""

    # Precompute next occurrence for each char in a and b
    # Using 26 lowercase letters; if other chars possible, adjust.
    # But problem likely lowercase; to be safe, we can use dict.
    # We'll use dict for generality.

    # next_a[i] = dict char -> smallest index >= i where char occurs
    next_a = [dict() for _ in range(n + 1)]
    last = {}
    for i in range(n - 1, -1, -1):
        last[a[i]] = i
        next_a[i] = last.copy()
    # next_a[n] = empty dict (no chars after end)

    next_b = [dict() for _ in range(m + 1)]
    last = {}
    for j in range(m - 1, -1, -1):
        last[b[j]] = j
        next_b[j] = last.copy()

    # Reconstruct
    i = j = 0
    res = []
    while i < n and j < m and dp[i][j] > 0:
        # Try all possible next characters in sorted order
        # Collect possible chars from both suffixes
        candidates = set(next_a[i].keys()) & set(next_b[j].keys())
        for c in sorted(candidates):
            ia = next_a[i][c]
            ib = next_b[j][c]
            if 1 + dp[ia + 1][ib + 1] == dp[i][j]:
                res.append(c)
                i = ia + 1
                j = ib + 1
                break
        else:
            # Should not happen if dp[i][j] > 0
