                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    # next_a[i][c] = smallest index >= i where a[index] == c, else n
    next_a = [[n] * 26 for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for c in range(26):
            next_a[i][c] = next_a[i + 1][c]
        next_a[i][ord(a[i]) - 97] = i

    next_b = [[m] * 26 for _ in range(m + 1)]
    for j in range(m - 1, -1, -1):
        for c in range(26):
            next_b[j][c] = next_b[j + 1][c]
        next_b[j][ord(b[j]) - 97] = j

    # memo[i][j] = lexicographically smallest LCS of a[i:] and b[j:]
    memo = {}

    def solve(i, j):
        if dp[i][j] == 0:
            return ""
        key = (i, j)
        if key in memo:
            return memo[key]

        best = None
        for c in range(26):
            ni = next_a[i][c]
            nj = next_b[j][c]
            if ni < n and nj < m and 1 + dp[ni + 1][nj + 1] == dp[i][j]:
                cand = chr(c + 97) + solve(ni + 1, nj + 1)
                if best is None or cand < best:
                    best = cand

        memo[key] = best
        return best

    return solve(0, 0)

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # dp[i][j] = LCS length of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    L = dp[0][0]
    if L == 0:
        return ""

    # next_a[i][c] = smallest index >= i where a[index] == c, or n if none
    # Use dict per position for characters present in a
    next_a = [dict() for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        next_a[i] = dict(next_a[i + 1])
        next_a[i][a[i]] = i

    next_b = [dict() for _ in range(m + 1)]
    for j in range(m - 1, -1, -1):
        next_b[j] = dict(next_b[j + 1])
        next_b[j][b[j]] = j

    res = []
    i, j = 0, 0
    remaining = L

    while remaining > 0:
        # Try characters in lexicographic order
        for c in sorted(set(a) & set(b)):
            ni = next_a[i].get(c, n)
            nj = next_b[j].get(c, m)
            if ni < n and nj < m:
                # After choosing c at ni, nj, we need LCS of a[ni+1:], b[nj+1:] == remaining-1
                if dp[ni + 1][nj + 1] == remaining - 1:
                    res.append(c)
                    i = ni + 1
                    j = nj + 1
                    remaining -= 1
                    break

    return ''.join(res)

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)
    # dp[i][j] = LCS length of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
