                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    # Greedily build the lexicographically smallest LCS.
    res = []
    i = j = 0
    while i < n and j < m and dp[i][j] > 0:
        target = dp[i][j]
        # Find the smallest character c such that we can achieve an LCS
        # of length target starting with c.
        best_c = None
        best_ni = best_nj = -1
        for c in sorted(set(a[i:]) & set(b[j:])):
