        res.append(best_c)
        i = best_ni + 1
        j = best_nj + 1

    return "".join(res)

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # dp[i][j] = LCS length of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    # best[i][j] = lexicographically smallest LCS of a[i:] and b[j:]
    # We compute it lazily with memoization to avoid O(n*m*L) memory blowup.
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def best(i, j):
        if i >= n or j >= m or dp[i][j] == 0:
            return ""
        target = dp[i][j]
        # Find the smallest character c such that some occurrence pair
        # (ni, nj) with a[ni]==b[nj]==c and 1+dp[ni+1][nj+1]==target exists.
        # Among occurrences of that c, pick the one minimizing best(ni+1, nj+1).
        best_char = None
        best_suffix = None
        # Collect candidate characters
        # To be efficient, iterate over distinct chars in a[i:] and b[j:]
        # but we can just scan positions.
        # For each character c, find all occurrence pairs and evaluate.
        # Since alphabet is small in practice, we scan.
        seen_chars = set()
        for ni in range(i, n):
            c = a[ni]
            if c in seen_chars:
                continue
            seen_chars.add(c)
            if best_char is not None and c > best_char:
                continue
            # find occurrences of c in b[j:]
            for nj in range(j, m):
                if b[nj] == c and 1 + dp[ni + 1][nj + 1] == target:
                    if best_char is None or c < best_char:
                        best_char = c
                        best_suffix = best(ni + 1, nj + 1)
                    elif c == best_char:
                        suf = best(ni + 1, nj + 1)
                        if suf < best_suffix:
                            best_suffix = suf
                    break  # first occurrence in b is enough? No—need all.
            # Actually we need all nj, so redo without break:
        # The above loop with break is wrong; redo properly below.
        return _best(i, j)

    # Simpler correct approach: iterative DP storing strings is too heavy.
    # Use the greedy with full search over occurrence pairs for the smallest char.
    def solve():
        res = []
        i, j = 0, 0
        while i < n and j < m and dp[i][j] > 0:
            target = dp[i][j]
            # Find smallest character c that can be used
            best_char = None
            for ni in range(i, n):
                c = a[ni]
                if best_char is not None and c >= best_char:
                    continue
                # check if c can start an LCS
                ok = False
                for nj in range(j, m):
                    if b[nj] == c and 1 + dp[ni + 1][nj + 1] == target:
                        ok = True
                        break
                if ok:
                    best_char = c
            # Now among all occurrence pairs of best_char, pick the one
            # that minimizes the continuation.
            best_ni = best_nj = None
            best_cont = None
            for ni in range(i, n):
                if a[ni] != best_char:
                    continue
                for nj in range(j, m):
                    if b[nj] == best_char and 1 + dp[ni + 1][nj + 1] == target:
                        cont = best(ni + 1, nj + 1)
                        if best_cont is None or cont < best_cont:
                            best_cont = cont
                            best_ni, best_nj = ni, nj
            res.append(best_char)
            i, j = best_ni + 1, best_nj + 1
        return ''.join(res)

    # The above still uses best() which is recursive; let's just do a clean
    # bottom-up DP for lexicographically smallest LCS.
    # dp2[i][j] = lexicographically smallest LCS of a[i:] and b[j:]
    # Memory: O(n*m*L) could be large but n,m <= 300, L <= 300 -> 27M chars worst case.
    # That's too much. Instead, reconstruct greedily with correct tie-breaking.

    # Correct greedy: at each step, among all characters c that can start an LCS,
    # pick the smallest c. Then among all occurrence pairs (ni,nj) of c with
    # 1+dp[ni+1][nj+1]==target, pick the pair that yields the lexicographically
    # smallest continuation. But continuation depends on future choices, so we
    # need to compare full continuations. We can do this by computing the
    # lexicographically smallest LCS from (ni+1, nj+1) recursively with memoization.

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def best_from(i, j):
        if i >= n or j >= m or dp[i][j] == 0:
            return ""
        target = dp[i][j]
        # find smallest char
        best_char = None
        for ni in range(i, n):
            c = a[ni]
            if best_char is not None and c >= best_char:
                continue
            for nj in range(j, m):
                if b[nj] == c and 1 + dp[ni + 1][nj + 1] == target:
                    best_char = c
                    break
        # among occurrences of best_char, pick best continuation
        best_cont = None
        for ni in range(i, n):
            if a[ni] != best_char:
                continue
            for nj in range(j, m):
                if b[nj] == best_char and 1 + dp[ni + 1][nj + 1] == target:
                    cont = best_from(ni + 1, nj + 1)
                    if best_cont is None or cont < best_cont:
                        best_cont = cont
        return best_char + best_cont

    return best_from(0, 0)

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # dp[i][j] = LCS length of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
