def smallest_lcs(a: str, b: str) -> str:
    m, n = len(a), len(b)

    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    # best[i][j] = lexicographically smallest LCS of a[i:] and b[j:]
    # Build from the end so suffixes are available.
    best = [[None] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        best[i][n] = ""
    for j in range(n + 1):
        best[m][j] = ""

    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if a[i] == b[j]:
                best[i][j] = a[i] + best[i + 1][j + 1]
            else:
                # Choose the lexicographically smaller of the two options,
                # preferring the longer one when lengths differ.
                c1 = best[i + 1][j]
                c2 = best[i][j + 1]
                if len(c1) > len(c2):
                    best[i][j] = c1
                elif len(c2) > len(c1):
                    best[i][j] = c2
                else:
                    best[i][j] = c1 if c1 < c2 else c2

    return best[0][0]

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # dp[i][j] = lexicographically smallest LCS of a[i:] and b[j:]
    dp = [[""] * (m + 1) for _ in range(n + 1)]

    def better(s1: str, s2: str) -> str:
        if len(s1) != len(s2):
            return s1 if len(s1) > len(s2) else s2
        return s1 if s1 < s2 else s2

    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            best = better(dp[i + 1][j], dp[i][j + 1])
            if a[i] == b[j]:
                cand = a[i] + dp[i + 1][j + 1]
                best = better(best, cand)
            dp[i][j] = best

    return dp[0][0]

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # dp[i][j] = LCS length of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = 1 + dp[i + 1][j + 1]
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j + 1])

    # Characters that appear in both strings, sorted for lexicographic choice.
    common = sorted(set(a) & set(b))

    # next_a[i][c] = smallest index >= i where a[index] == c, else n
    next_a = {c: [n] * (n + 1) for c in common}
    for c in common:
