    next_b = {c: [m] * (m + 1) for c in common}
    for c in common:
        for j in range(m - 1, -1, -1):
            next_b[c][j] = j if b[j] == c else next_b[c][j + 1]

    # Reconstruct lexicographically smallest LCS greedily.
    res = []
    i = j = 0
    while dp[i][j] > 0:
        for c in common:
            ni = next_a[c][i]
            nj = next_b[c][j]
            if ni < n and nj < m and 1 + dp[ni + 1][nj + 1] == dp[i][j]:
                res.append(c)
                i = ni + 1
                j = nj + 1
                break

    return ''.join(res)

