                    # expired entry: treat as new key
                    del cache[key]
                else:
                    # replace value/expiry, mark MRU
                    del cache[key]
                    cache[key] = (value, expire)
                    continue

            # new key (or expired one removed above)
            # evict LRU among non-expired entries if at capacity
            if len(cache) >= capacity:
                # purge expired entries first (they don't count)
                expired_keys = [k for k, v in cache.items() if is_expired(v, time)]
                for k in expired_keys:
                    del cache[k]

                if len(cache) >= capacity:
                    # evict least recently used (first item)
                    cache.popitem(last=False)

            cache[key] = (value, expire)

        elif op[0] == "get":
            _, key, time = op
            if key in cache:
                entry = cache[key]
                if is_expired(entry, time):
                    del cache[key]
                    results.append(None)
                else:
                    # mark as MRU
                    del cache[key]
                    cache[key] = entry
                    results.append(entry[0])
            else:
                results.append(None)

    return results

