            purge_expired(time)
            if key in cache:
                value, expire_time, _ = cache[key]
                counter += 1
                cache[key] = (value, expire_time, counter)
                results.append(value)
            else:
                results.append(None)

    return results

def simulate_cache(capacity: int, ops: list[tuple]) -> list:
    # Each entry: key -> [value, expire_at, recency]
    # recency is a monotonically increasing counter; larger = more recently used.
    cache = {}
    recency = 0
    results = []

