        exp = entry[1]
        return exp is not None and time >= exp

    def purge_expired(time):
        # Remove expired entries so they don't count toward capacity.
        expired_keys = [k for k, e in cache.items() if is_expired(e, time)]
        for k in expired_keys:
            del cache[k]

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op
            purge_expired(time)

            expire_at = None if ttl is None else time + ttl

            if key in cache and not is_expired(cache[key], time):
                # Replace value and expiry, make most recently used.
                recency += 1
                cache[key] = [value, expire_at, recency]
            else:
                # New key (or expired key): may need to evict.
                if key in cache:
                    del cache[key]
                if len(cache) >= capacity:
                    # Evict least recently used.
                    lru_key = min(cache, key=lambda k: cache[k][2])
                    del cache[lru_key]
                recency += 1
                cache[key] = [value, expire_at, recency]

        elif op[0] == "get":
            _, key, time = op
            purge_expired(time)

            if key in cache and not is_expired(cache[key], time):
                recency += 1
                cache[key][2] = recency
                results.append(cache[key][0])
            else:
                results.append(None)

    return results

