from collections import OrderedDict

def simulate_cache(capacity: int, ops: list[tuple]) -> list:
    if capacity < 1:
        raise ValueError("capacity must be >= 1")

    cache = OrderedDict()  # key -> (value, expire_time or None)
    results = []

    def is_expired(expire_time, now):
        return expire_time is not None and now >= expire_time

    def purge_expired(now):
        expired_keys = [k for k, (_, exp) in cache.items() if is_expired(exp, now)]
        for k in expired_keys:
            del cache[k]

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op
            if ttl is not None and ttl <= 0:
                raise ValueError("ttl must be positive or None")
            expire_time = None if ttl is None else time + ttl

            purge_expired(time)

            if key in cache:
                del cache[key]
                cache[key] = (value, expire_time)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = (value, expire_time)

        elif op[0] == "get":
            _, key, time = op
            purge_expired(time)

            if key in cache:
                value, expire_time = cache[key]
                del cache[key]
                cache[key] = (value, expire_time)
                results.append(value)
            else:
                results.append(None)

    return results

