def simulate_cache(capacity: int, ops: list[tuple]) -> list:
    cache = {}  # key -> (value, expire_time, recency)
    counter = 0
    results = []

    def expired(exp, t):
        return exp is not None and t >= exp

    for op in ops:
        if op[0] == "put":
            _, key, value, t, ttl = op
            exp = None if ttl is None else t + ttl

            if key in cache:
                _, old_exp, _ = cache[key]
                if not expired(old_exp, t):
                    counter += 1
                    cache[key] = (value, exp, counter)
                    continue
                else:
                    del cache[key]

            # remove all expired entries
            for k in [k for k, (_, e, _) in cache.items() if expired(e, t)]:
                del cache[k]

            if len(cache) >= capacity:
                lru = min(cache, key=lambda k: cache[k][2])
                del cache[lru]

            counter += 1
            cache[key] = (value, exp, counter)

        elif op[0] == "get":
            _, key, t = op
            if key in cache:
                value, exp, _ = cache[key]
                if not expired(exp, t):
                    counter += 1
                    cache[key] = (value, exp, counter)
                    results.append(value)
                else:
                    del cache[key]
                    results.append(None)
            else:
                results.append(None)

    return results

def simulate_cache(capacity: int, ops: list[tuple]) -> list:
    cache = {}          # key -> [value, expiry, recency]
    recency = 0
    results = []

    def is_expired(entry, t):
        exp = entry[1]
        return exp is not None and t >= exp

    def purge_expired(t):
        for k in [k for k, e in cache.items() if is_expired(e, t)]:
            del cache[k]

    def touch(key):
        nonlocal recency
        recency += 1
        cache[key][2] = recency

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op
            expiry = None if ttl is None else time + ttl

            purge_expired(time)

            if key in cache:
                cache[key][0] = value
                cache[key][1] = expiry
                touch(key)
            else:
                if len(cache) >= capacity:
                    lru = min(cache, key=lambda k: cache[k][2])
                    del cache[lru]
                cache[key] = [value, expiry, 0]
                touch(key)

        elif op[0] == "get":
            _, key, time = op
            purge_expired(time)
            if key in cache:
                touch(key)
                results.append(cache[key][0])
            else:
                results.append(None)

    return results

def simulate_cache(capacity: int, ops: list[tuple]) -> list:
    # Each entry: key -> (value, expire_time_or_None, last_used_time)
    cache = {}
    results = []

    def is_expired(entry, time):
        _, expire, _ = entry
        return expire is not None and time >= expire

    def evict_lru(time):
        # Remove expired entries first
        expired_keys = [k for k, v in cache.items() if is_expired(v, time)]
        for k in expired_keys:
            del cache[k]

        # If still at capacity, evict least recently used
        if len(cache) >= capacity:
            lru_key = min(cache, key=lambda k: cache[k][2])
            del cache[lru_key]

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op
            expire = None if ttl is None else time + ttl

            if key in cache and not is_expired(cache[key], time):
                # Replace existing entry
                cache[key] = (value, expire, time)
            else:
                # New key or expired entry
                if key in cache:
                    del cache[key]  # remove expired entry
                if len(cache) >= capacity:
                    evict_lru(time)
                cache[key] = (value, expire, time)

        elif op[0] == "get":
            _, key, time = op
            if key in cache:
                entry = cache[key]
                if is_expired(entry, time):
                    del cache[key]
                    results.append(None)
                else:
                    value, expire, _ = entry
                    cache[key] = (value, expire, time)  # update recency
                    results.append(value)
            else:
                results.append(None)

    return results

