from collections import OrderedDict

def simulate_cache(capacity: int, ops: list[tuple]) -> list:
    cache = OrderedDict()  # key -> (value, expiry_time or None)
    results = []

    def is_expired(expiry, t):
        return expiry is not None and t >= expiry

    def purge_expired(t):
        # Remove all expired entries (does not affect recency of live ones)
        expired_keys = [k for k, (_, exp) in cache.items() if is_expired(exp, t)]
        for k in expired_keys:
            del cache[k]

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op
            expiry = None if ttl is None else time + ttl

            # Remove if expired
            if key in cache and is_expired(cache[key][1], time):
                del cache[key]

            if key in cache:
                # Replace value and expiry, mark as most recently used
                del cache[key]
                cache[key] = (value, expiry)
            else:
                # New key: purge expired entries first
                purge_expired(time)
                if len(cache) >= capacity:
                    # Evict least recently used
                    cache.popitem(last=False)
                cache[key] = (value, expiry)

        elif op[0] == "get":
            _, key, time = op
            if key in cache:
                value, expiry = cache[key]
                if is_expired(expiry, time):
                    del cache[key]
                    results.append(None)
                else:
                    # Mark as most recently used
                    del cache[key]
                    cache[key] = (value, expiry)
                    results.append(value)
            else:
                results.append(None)

    return results
